def _default_country_code_for_currency(currency_code: str) -> str:
    """
    Map a currency code to the default country code used for global pricing rows.
    We keep it short (<=3 chars) to fit the column definition.
    """
    if not currency_code:
        return 'INT'
    code = currency_code.strip().upper()
    return code[:3] if len(code) >= 3 else code.ljust(3, 'X')

PRICING_TYPE_AUTO = 'S'  # Stored as single-character in DB (Standard / System generated)
PRICING_TYPE_MANUAL = 'M'  # Manual override / Locked pricing


def normalize_pricing_type(value) -> str:
    """
    Normalise the pricing type flag coming from the database/UI into the single-character
    code that is persisted in MySQL.
    Supported values:
      - 'auto', 'standard', 's' → 'S'
      - 'manual', 'locked', 'm' → 'M'
    """
    if value is None:
        return PRICING_TYPE_AUTO

    value_str = str(value).strip()
    if not value_str:
        return PRICING_TYPE_AUTO

    value_upper = value_str.upper()
    if value_upper in ('M', 'MANUAL', 'LOCKED'):
        return PRICING_TYPE_MANUAL
    if value_upper in ('S', 'STANDARD', 'AUTO'):
        return PRICING_TYPE_AUTO

    # Fall back to single-character codes if already provided
    if value_upper == PRICING_TYPE_MANUAL:
        return PRICING_TYPE_MANUAL
    return PRICING_TYPE_AUTO


def normalize_override_type(value) -> str:
    """
    Normalize override_type for ProductRegionalOverride table.
    Database ENUM expects: 'auto', 'manual', 'locked'
    """
    if value is None:
        return 'auto'
    
    value_str = str(value).strip().lower()
    if not value_str:
        return 'auto'
    
    # Map various inputs to ENUM values
    if value_str in ('auto', 'a', 's', 'standard'):
        return 'auto'
    elif value_str in ('manual', 'm', 'admin', 'admin_set'):
        return 'manual'
    elif value_str in ('locked', 'l', 'fixed', 'fixed_price'):
        return 'locked'
    
    # Default to 'auto' if unrecognized
    return 'auto'


def pricing_type_label(value) -> str:
    """Return human readable label for pricing type."""
    normalized = normalize_pricing_type(value)
    return 'manual' if normalized == PRICING_TYPE_MANUAL else 'auto'


def normalize_country_code_to_3_letter(code):
    """
    ✅ CRITICAL: Normalize country code to 3-letter format for consistency.
    This ensures that "IN" becomes "IND", "AU" becomes "AUS", etc.
    This is used everywhere to ensure database lookups match correctly.
    """
    if not code:
        return None
    
    code_upper = str(code).upper().strip()
    
    # If already 3-letter, return as-is
    if len(code_upper) == 3:
        return code_upper
    
    # Convert 2-letter to 3-letter codes
    if len(code_upper) == 2:
        country_code_map = {
            'AU': 'AUS', 'IN': 'IND', 'US': 'USA', 'GB': 'GBR', 'CA': 'CAN',
            'JP': 'JPN', 'CN': 'CHN', 'BR': 'BRA', 'SG': 'SGP', 'CH': 'CHE',
            'ZA': 'ZAF', 'NZ': 'NZL', 'AE': 'ARE', 'SA': 'SAU', 'DE': 'DEU',
            'FR': 'FRA', 'IT': 'ITA', 'ES': 'ESP', 'NL': 'NLD', 'BE': 'BEL',
            'AT': 'AUT', 'SE': 'SWE', 'NO': 'NOR', 'DK': 'DNK', 'FI': 'FIN',
            'PL': 'POL', 'CZ': 'CZE', 'HU': 'HUN', 'RO': 'ROU', 'GR': 'GRC',
            'PT': 'PRT', 'IE': 'IRL', 'MX': 'MEX', 'AR': 'ARG', 'CL': 'CHL',
            'CO': 'COL', 'PE': 'PER', 'VE': 'VEN', 'KR': 'KOR', 'TH': 'THA',
            'MY': 'MYS', 'ID': 'IDN', 'PH': 'PHL', 'VN': 'VNM', 'IL': 'ISR',
            'EG': 'EGY', 'PK': 'PAK', 'BD': 'BGD', 'LK': 'LKA', 'NP': 'NPL'
        }
        return country_code_map.get(code_upper, code_upper)
    
    # For other lengths, return as-is (might be already 3-letter or something else)
    return code_upper


def _coerce_date(value):
    """Parse a date string in YYYY-MM-DD format into a date object."""
    if not value:
        return None
    try:
        return datetime.strptime(value[:10], '%Y-%m-%d').date()
    except (TypeError, ValueError):
        return None


def parse_date_range(default_days=30):
    """
    Normalize incoming date range parameters.
    Accepts ?start_date=YYYY-MM-DD&end_date=YYYY-MM-DD or ?days=N.
    Returns both date and datetime boundaries plus the previous comparison window.
    Uses UTC timezone for all datetime calculations to match MySQL TIMESTAMP behavior.
    """
    days_param = request.args.get('days', type=int)
    if days_param and days_param > 0:
        default_days = days_param

    today = datetime.utcnow().date()
    end_date = (
        _coerce_date(request.args.get('end_date')) or
        _coerce_date(request.args.get('endDate')) or
        today
    )
    start_date = (
        _coerce_date(request.args.get('start_date')) or
        _coerce_date(request.args.get('startDate'))
    )

    if not start_date:
        # Match MySQL DATE_SUB(CURDATE(), INTERVAL N DAY) behavior exactly
        # For "last 30 days", we want exactly 30 days including today
        # If today is Jan 15 and we want last 30 days, we want Dec 16 to Jan 15 (30 days total)
        # So we go back (default_days - 1) days from today
        offset = max(default_days - 1, 0)  # For 30 days: use 29 days back to include today
        start_date = end_date - timedelta(days=offset)
        # print(f"[Date Range] Calculated start_date: {start_date}, end_date: {end_date}, offset: {offset}, default_days: {default_days}")

    if start_date > end_date:
        start_date, end_date = end_date, start_date

    period_days = (end_date - start_date).days + 1
    previous_end_date = start_date - timedelta(days=1)
    previous_start_date = previous_end_date - timedelta(days=period_days - 1)

    # Use UTC timezone for all datetime objects to match MySQL TIMESTAMP behavior
    start_datetime = datetime.combine(start_date, datetime.min.time(), tzinfo=timezone.utc)
    end_datetime = datetime.combine(end_date, datetime.max.time(), tzinfo=timezone.utc)
    end_datetime_exclusive = datetime.combine(end_date + timedelta(days=1), datetime.min.time(), tzinfo=timezone.utc)

    previous_start_datetime = datetime.combine(previous_start_date, datetime.min.time(), tzinfo=timezone.utc)
    previous_end_datetime = datetime.combine(previous_end_date, datetime.max.time(), tzinfo=timezone.utc)
    previous_end_exclusive = datetime.combine(previous_end_date + timedelta(days=1), datetime.min.time(), tzinfo=timezone.utc)

    return {
        'start_date': start_date,
        'end_date': end_date,
        'start_datetime': start_datetime,
        'end_datetime': end_datetime,
        'end_datetime_exclusive': end_datetime_exclusive,
        'days': period_days,
        'previous_start_date': previous_start_date,
        'previous_end_date': previous_end_date,
        'previous_start_datetime': previous_start_datetime,
        'previous_end_datetime': previous_end_datetime,
        'previous_end_datetime_exclusive': previous_end_exclusive
    }


# ==================== TAX CALCULATION HELPERS ====================

# Helper function to calculate tax rate for a product based on country (Shopify-style)
def calculate_product_tax_rate(product, country_code, db_session):
    """
    Calculate tax rate for a product based on country (Shopify-style)
    Priority:
    1. Product-specific regional tax override for the country
    2. Regional tax rate from tax_rates table for the country
    3. Country's default_tax_rate
    4. Product's default tax rate (if any)
    5. 0% (no tax)
    
    Args:
        product: Product object
        country_code: Country code (e.g., 'AUS', 'IND')
        db_session: Database session
    
    Returns:
        float: Tax rate percentage (e.g., 10.0 for 10%)
    """
    try:
        if not country_code:
            return 0.0
        
        # ✅ CRITICAL: Normalize country code to 3-letter format (IN -> IND)
        country_code_upper = normalize_country_code_to_3_letter(country_code)
        if not country_code_upper:
            return 0.0
        
        # 1. Check for product-specific regional tax override (ProductRegionalOverride table)
        try:
            # ✅ CRITICAL: Try exact match first with normalized code
            regional_override = ProductRegionalOverride.query.filter_by(
                product_id=product.id,
                country_code=country_code_upper
            ).first()
            
            # ✅ If not found, try with original 2-letter code (for backward compatibility)
            if not regional_override and len(country_code_upper) == 3:
                # Try converting 3-letter back to 2-letter (reverse lookup)
                reverse_map = {
                    'AUS': 'AU', 'IND': 'IN', 'USA': 'US', 'GBR': 'GB', 'CAN': 'CA',
                    'JPN': 'JP', 'CHN': 'CN', 'BRA': 'BR', 'SGP': 'SG', 'CHE': 'CH',
                    'ZAF': 'ZA', 'NZL': 'NZ', 'ARE': 'AE', 'SAU': 'SA', 'DEU': 'DE',
                    'FRA': 'FR', 'ITA': 'IT', 'ESP': 'ES', 'NLD': 'NL', 'BEL': 'BE',
                    'AUT': 'AT', 'SWE': 'SE', 'NOR': 'NO', 'DNK': 'DK', 'FIN': 'FI',
                    'POL': 'PL', 'CZE': 'CZ', 'HUN': 'HU', 'ROU': 'RO', 'GRC': 'GR',
                    'PRT': 'PT', 'IRL': 'IE', 'MEX': 'MX', 'ARG': 'AR', 'CHL': 'CL',
                    'COL': 'CO', 'PER': 'PE', 'KOR': 'KR', 'THA': 'TH', 'MYS': 'MY',
                    'IDN': 'ID', 'PHL': 'PH', 'VNM': 'VN', 'ISR': 'IL', 'EGY': 'EG',
                    'PAK': 'PK', 'BGD': 'BD', 'LKA': 'LK', 'NPL': 'NP'
                }
                two_letter = reverse_map.get(country_code_upper)
                if two_letter:
                    regional_override = ProductRegionalOverride.query.filter_by(
                        product_id=product.id,
                        country_code=two_letter
                    ).first()
                    if regional_override:
                        print(f"[Tax Calc] Product {product.id} - {country_code_upper}: Found override using 2-letter code '{two_letter}' (override ID={regional_override.id})")
                        # ✅ IMPORTANT: Update the override's country_code to normalized format for future queries
                        if regional_override.country_code != country_code_upper:
                            print(f"[Tax Calc] ⚠️  Migrating override ID {regional_override.id} country_code from '{regional_override.country_code}' to '{country_code_upper}'")
                            regional_override.country_code = country_code_upper
                            try:
                                db_session.commit()
                            except Exception as migrate_err:
                                print(f"[Tax Calc] ⚠️  Could not migrate country_code: {migrate_err}")
                                db_session.rollback()
            
            # ✅ Also check for any override with this product_id to see what country_codes exist
            if not regional_override:
                all_overrides = ProductRegionalOverride.query.filter_by(product_id=product.id, is_active=True).all()
                if all_overrides:
                    existing_codes = [o.country_code for o in all_overrides]
                    print(f"[Tax Calc] Product {product.id} - {country_code_upper}: No override found. Existing overrides: {existing_codes}")
            
            if regional_override:
                print(f"[Tax Calc] Product {product.id} - {country_code_upper}: Found override (ID={regional_override.id}), tax_rate_override={regional_override.tax_rate_override}, use_country_default_tax={regional_override.use_country_default_tax}")
                # If use_country_default_tax is True, skip the override and use country's default
                if regional_override.use_country_default_tax:
                    print(f"[Tax Calc] Product {product.id} - {country_code_upper}: use_country_default_tax=True, skipping override")
                    # Continue to next check (country's default tax)
                elif regional_override.tax_rate_override is not None:
                    # tax_rate_override can be 0% - that's a valid value
                    tax_rate = float(regional_override.tax_rate_override)
                    print(f"[Tax Calc] ✅ Product {product.id} - {country_code_upper}: Using override tax_rate={tax_rate}% (override ID={regional_override.id})")
                    return tax_rate
                else:
                    # Override exists but tax_rate_override is None - skip it
                    print(f"[Tax Calc] Product {product.id} - {country_code_upper}: Override exists but tax_rate_override is None, skipping")
            else:
                print(f"[Tax Calc] Product {product.id} - {country_code_upper}: No regional override found")
        except Exception as e:
            print(f"[Tax Calc] ❌ Error checking regional override: {e}")
            import traceback
            traceback.print_exc()
            pass  # Table might not exist - continue to next check
        
        # 2. Check product's regional_tax_rates JSON field (if exists)
        if hasattr(product, 'regional_tax_rates') and product.regional_tax_rates:
            try:
                regional_taxes = json.loads(product.regional_tax_rates) if isinstance(product.regional_tax_rates, str) else product.regional_tax_rates
                if isinstance(regional_taxes, dict) and country_code_upper in regional_taxes:
                    tax_rate = float(regional_taxes[country_code_upper])
                    if tax_rate >= 0:
                        return tax_rate
            except (json.JSONDecodeError, ValueError, TypeError):
                pass
        
        # 3. Check TaxCountry table (tax_countries) - this is where Tax Management stores rates
        try:
            tax_country = TaxCountry.query.filter_by(
                country_code=country_code_upper,
                is_active=True
            ).first()
            if tax_country and tax_country.default_tax_rate is not None:
                tax_rate = float(tax_country.default_tax_rate)
                # Return even if 0% - we need to know the country's tax rate (0% is valid)
                return tax_rate
        except Exception:
            pass
        
        # 3b. Check country's default_tax_rate from Country table (fallback)
        # This is synced from TaxCountry but may not always be in sync
        try:
            country = Country.query.filter_by(country_code=country_code_upper).first()
            if country and country.default_tax_rate is not None:
                tax_rate = float(country.default_tax_rate)
                # Return even if 0% - we need to know the country's tax rate (0% is valid)
                return tax_rate
        except Exception:
            pass
        
        # 4. Product's default tax rate (if product has a tax_rate field)
        if hasattr(product, 'tax_rate') and product.tax_rate:
            try:
                return float(product.tax_rate)
            except (ValueError, TypeError):
                pass
        
        # 5. Default: no tax
        return 0.0
        
    except Exception as e:
        print(f"[Tax Calculation] Error calculating tax rate: {e}")
        return 0.0


# Helper function to calculate price with tax
def calculate_price_with_tax(base_price, tax_rate):
    """
    Calculate price including tax with high precision using Decimal
    
    Args:
        base_price: Base price (without tax)
        tax_rate: Tax rate percentage (e.g., 10.0 for 10%)
    
    Returns:
        tuple: (price_with_tax, tax_amount) - both rounded to 2 decimal places
    """
    try:
        from decimal import Decimal, ROUND_HALF_UP
        
        # Convert to Decimal for precise calculations
        base = Decimal(str(base_price)) if base_price else Decimal('0')
        tax = Decimal(str(tax_rate)) if tax_rate else Decimal('0')
        
        # Calculate tax amount with precision
        tax_amount = (base * tax / Decimal('100')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        
        # Calculate price with tax
        price_with_tax = (base + tax_amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        
        # Return as floats (for JSON serialization) but with precise rounding
        return float(price_with_tax), float(tax_amount)
    except (ValueError, TypeError, Exception) as e:
        # Fallback to simple calculation if Decimal fails
        try:
            base_price = float(base_price) if base_price else 0.0
            tax_rate = float(tax_rate) if tax_rate else 0.0
            tax_amount = (base_price * tax_rate) / 100.0
            price_with_tax = base_price + tax_amount
            return round(price_with_tax, 2), round(tax_amount, 2)
        except:
            return float(base_price) if base_price else 0.0, 0.0

def safe_get_attr(obj, attr_name, default=None):
    """
    Safely get an attribute from a SQLAlchemy model without triggering lazy loading.
    This prevents errors when accessing columns that don't exist in the database.
    
    Args:
        obj: SQLAlchemy model instance or any object
        attr_name: Name of the attribute to get
        default: Default value to return if attribute doesn't exist or can't be accessed
    
    Returns:
        Attribute value or default
    """
    try:
        # First, check if attribute is already in the instance dict (already loaded)
        # This is the safest check - if it's in __dict__, it's already loaded
        if hasattr(obj, '__dict__') and attr_name in obj.__dict__:
            return obj.__dict__[attr_name]
        
        # For SQLAlchemy models, check if attribute is loaded without triggering lazy load
        if hasattr(obj, '__mapper__'):
            from sqlalchemy import inspect
            from sqlalchemy.orm import PASSIVE_NO_INITIALIZE
            from sqlalchemy.exc import OperationalError
            
            try:
                insp = inspect(obj)
                # Check if the attribute exists in the mapper
                if attr_name in insp.mapper.attrs:
                    # Check if the attribute is already loaded using PASSIVE_NO_INITIALIZE
                    # This won't trigger a lazy load
                    state = insp.get_history(attr_name, PASSIVE_NO_INITIALIZE)
                    if state.has_value():
                        # Attribute is loaded, safe to access directly from __dict__
                        if attr_name in obj.__dict__:
                            return obj.__dict__[attr_name]
                        # If not in __dict__ but has_value, try getattr but catch errors
                        try:
                            return getattr(obj, attr_name)
                        except (OperationalError, AttributeError, Exception):
                            return default
                    else:
                        # Attribute not loaded - return default to avoid triggering lazy load
                        # This prevents queries for non-existent columns
                        return default
                else:
                    # Attribute doesn't exist in mapper, try regular getattr
                    return getattr(obj, attr_name, default)
            except (OperationalError, AttributeError):
                # Database error or attribute error - return default
                return default
            except Exception:
                # For any other error, return default
                return default
        else:
            # Not a SQLAlchemy model, use regular getattr
            return getattr(obj, attr_name, default)
    except Exception:
        pass
        # If anything goes wrong, return default
        return default


