# Product Pack Model
class ProductPack(db.Model):
    __tablename__ = 'product_packs'
    __table_args__ = {'extend_existing': True}  # Allow redefinition if table already exists
    id = db.Column(db.Integer, primary_key=True)
    product_id = db.Column(db.Integer, db.ForeignKey('products.id', ondelete='CASCADE'), nullable=False)
    name = db.Column(db.String(255), nullable=False)
    bottles = db.Column(db.Integer, default=1)
    tablets = db.Column(db.Integer, default=0)
    months = db.Column(db.Integer, default=1)
    discount_percentage = db.Column(db.Float, default=0.0)
    price = db.Column(db.Float)  # Cached calculated price
    original_price = db.Column(db.Float)  # Cached original price
    savings = db.Column(db.Float)  # Cached savings amount
    badge = db.Column(db.String(100))
    display_order = db.Column(db.Integer, default=0)
    is_active = db.Column(db.Boolean, default=True)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    
    product = db.relationship('Product', backref=db.backref('packs', lazy='dynamic', cascade='all, delete-orphan'))
    
    def calculate_prices(self):
        """Calculate price, original_price, and savings based on product base_price"""
        if not self.product:
            return
        
        # Get product base price
        base_price = self.product.base_price or 0
        
        # Calculate original price (bottles * base_price)
        self.original_price = float(self.bottles * base_price) if self.bottles else 0
        
        # Calculate discount amount
        discount_amount = (self.original_price * self.discount_percentage) / 100
        
        # Calculate final price after discount
        self.price = self.original_price - discount_amount
        
        # Calculate savings
        self.savings = discount_amount
    
    def to_dict(self):
        # Calculate prices if not already set
        if self.price is None or self.original_price is None:
            self.calculate_prices()
        
        return {
            'id': self.id,
            'product_id': self.product_id,
            'name': self.name,
            'bottles': self.bottles,
            'tablets': self.tablets,
            'months': self.months,
            'discount_percentage': self.discount_percentage,
            'price': self.price,
            'original_price': self.original_price,
            'savings': self.savings,
            'badge': self.badge,
            'display_order': self.display_order,
            'is_active': self.is_active,
            'product': {
                'id': self.product.id if self.product else None,
                'name': self.product.name if self.product else None,
                'base_price': self.product.base_price if self.product else None
            } if self.product else None,
            'created_at': self.created_at.isoformat() if self.created_at else None,
            'updated_at': self.updated_at.isoformat() if self.updated_at else None
        }

