@app.route('/api/product-regional-overrides/<int:override_id>', methods=['PUT'])
@jwt_required()
def update_product_regional_override(override_id):
    """Update regional price override"""
    try:
        data = request.get_json() or {}
        current_user = get_jwt_identity()
        
        print(f"[PRODUCT REGIONAL OVERRIDE PUT] Updating ID {override_id}, data: {data}")
        
        override = db.session.get(ProductRegionalOverride, override_id)
        if not override:
            return jsonify({'error': 'Regional override not found'}), 404
        
        # ✅ CRITICAL: Normalize country_code if provided (to ensure consistency)
        if 'country_code' in data:
            normalized_country_code = normalize_country_code_to_3_letter(data['country_code'])
            if normalized_country_code and normalized_country_code != override.country_code:
                print(f"[PRODUCT REGIONAL OVERRIDE PUT] Normalizing country_code: {override.country_code} -> {normalized_country_code}")
                override.country_code = normalized_country_code
        
        # Store old values for audit
        old_values = {
            'base_price_override': override.base_price_override,
            'sale_price_override': override.sale_price_override,
            'tax_rate_override': override.tax_rate_override,
            'country_code': override.country_code
        }
        
        # Update fields
        if 'override_type' in data:
            override.override_type = normalize_override_type(data['override_type'])  # ✅ Use ENUM-compatible function
        if 'base_price_override' in data:
            override.base_price_override = data['base_price_override']
        if 'sale_price_override' in data:
            override.sale_price_override = data['sale_price_override']
        if 'adjustment_percentage' in data:
            override.adjustment_percentage = data['adjustment_percentage']
        if 'tax_rate_override' in data:
            # Parse tax_rate_override properly - 0 is a valid value
            tax_val = data['tax_rate_override']
            if tax_val in [None, '', 'null', 'undefined']:
                override.tax_rate_override = None
                print(f"[PRODUCT REGIONAL OVERRIDE PUT] Set tax_rate_override to None")
            else:
                try:
                    override.tax_rate_override = float(tax_val)  # 0.0 is valid
                    print(f"[PRODUCT REGIONAL OVERRIDE PUT] Set tax_rate_override to {override.tax_rate_override}%")
                    # ✅ CRITICAL: If setting a tax_rate_override (even 0%), automatically set use_country_default_tax to False
                    # This ensures the override is used, not the country default
                    if 'use_country_default_tax' not in data:
                        override.use_country_default_tax = False
                        print(f"[PRODUCT REGIONAL OVERRIDE PUT] Auto-set use_country_default_tax=False since tax_rate_override is set")
                except (ValueError, TypeError) as e:
                    print(f"❌ Invalid tax_rate_override: {tax_val}, error: {e}")
                    return jsonify({'error': f'Invalid tax_rate_override value: {tax_val}'}), 400
        if 'use_country_default_tax' in data:
            override.use_country_default_tax = bool(data['use_country_default_tax'])
            print(f"[PRODUCT REGIONAL OVERRIDE PUT] Set use_country_default_tax to {override.use_country_default_tax}")
        if 'price_locked' in data:
            override.price_locked = bool(data['price_locked'])
        if 'lock_reason' in data:
            override.lock_reason = data['lock_reason']
        
        # IMPORTANT: Explicitly update timestamp
        override.updated_at = datetime.now(timezone.utc)
        
        db.session.commit()
        
        # Log the action
        log_pricing_action(
            action_type='update_regional_override',
            entity_type='product_regional_override',
            entity_id=override_id,
            old_value=str(old_values),
            new_value=str(data),
            performed_by=current_user
        )
        
        return jsonify({
            'success': True,
            'message': 'Regional override updated successfully',
            'id': override_id
        }), 200
        
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

