# Helper function for logging user actions (general audit log)
def log_user_action(action_type, actor_type=None, user_id=None, resource_type=None, resource_id=None, old_value=None, new_value=None, notes=None, ip_address=None, user_agent=None):
    """Log user actions for audit trail"""
    try:
        # Ensure tables are initialized (especially for audit_logs schema migration)
        try:
            init_analytics_tables()
        except Exception as init_err:
            print(f"[WARNING] Could not initialize analytics tables: {init_err}")
        
        # Get IP address and user agent from request (if not provided and request is available)
        from flask import request
        if ip_address is None:
            try:
                ip_address = request.remote_addr if request else None
            except Exception:
                pass  # Request might not be available in some contexts
        
        if user_agent is None:
            try:
                user_agent = request.headers.get('User-Agent') if request else None
            except Exception:
                pass  # Request might not be available in some contexts
        
        log = AuditLog(
            action_type=action_type,
            actor_type=actor_type,
            user_id=user_id,
            resource_type=resource_type,
            resource_id=resource_id,
            old_value=old_value,
            new_value=new_value,
            ip_address=ip_address,
            user_agent=user_agent,
            notes=notes
        )
        db.session.add(log)
        db.session.commit()
    except Exception as e:
        # Don't fail the main action if logging fails
        db.session.rollback()
        pass  # Failed to log user action

# Helper function for logging pricing actions
def log_pricing_action(action_type, entity_type, entity_id=None, old_value=None, new_value=None, performed_by=None, notes=None):
    """Log pricing-related actions for audit trail"""
    try:
        log = PricingAuditLog(
            action_type=action_type,
            entity_type=entity_type,
            entity_id=entity_id,
            old_value=old_value,
            new_value=new_value,
            performed_by=performed_by,
            notes=notes
        )
        db.session.add(log)
        db.session.commit()
    except Exception as e:
        # Don't fail the main action if logging fails
        db.session.rollback()

