@app.route('/api/countries/cleanup', methods=['POST'])
@jwt_required()
def cleanup_countries():
    """
    Clean up countries table to match active currencies
    DELETES all countries except the 15 that match active currencies
    Ensures only 15 countries exist (one per active currency)
    """
    try:
        # Get active currencies
        active_currencies = Currency.query.filter_by(is_active=True).all()
        currency_codes = {curr.currency_code.upper() for curr in active_currencies}
        
        # Map currencies to their primary countries (2-letter codes)
        currency_to_country = {
            'USD': ('US', 'United States'),
            'INR': ('IN', 'India'),
            'EUR': ('DE', 'Germany'),  # Using Germany as primary EUR country
            'GBP': ('GB', 'United Kingdom'),
            'AUD': ('AU', 'Australia'),
            'CAD': ('CA', 'Canada'),
            'JPY': ('JP', 'Japan'),
            'SAR': ('SA', 'Saudi Arabia'),
            'CNY': ('CN', 'China'),
            'BRL': ('BR', 'Brazil'),
            'SGD': ('SG', 'Singapore'),
            'CHF': ('CH', 'Switzerland'),
            'ZAR': ('ZA', 'South Africa'),
            'NZD': ('NZ', 'New Zealand'),
            'AED': ('AE', 'United Arab Emirates')
        }
        
        # Normalize country codes (3-letter to 2-letter mapping)
        code_normalization = {
            'IND': 'IN', 'USA': 'US', 'GBR': 'GB', 'DEU': 'DE', 'FRA': 'FR',
            'AUS': 'AU', 'CAN': 'CA', 'JPN': 'JP', 'SAU': 'SA', 'CHN': 'CN',
            'BRA': 'BR', 'SGP': 'SG', 'CHE': 'CH', 'ZAF': 'ZA', 'NZL': 'NZ',
            'ARE': 'AE', 'ESP': 'ES', 'EU': 'DE'  # EU -> Germany
        }
        
        # Get all countries
        all_countries = Country.query.all()
        
        # Track which country codes we want to keep (2-letter codes)
        valid_country_codes = {code for code, _ in currency_to_country.values()}
        
        # Map to track which countries to keep (by normalized 2-letter code)
        countries_to_keep = {}  # {normalized_code: country_id}
        countries_to_delete = []
        
        deleted_count = 0
        kept_count = 0
        created_count = 0
        updated_count = 0
        
        # First pass: identify countries to keep or delete
        for country in all_countries:
            code = country.country_code.upper() if country.country_code else None
            if not code:
                # Country with no code - delete it
                countries_to_delete.append(country.id)
                continue
            
            # Normalize code (3-letter to 2-letter)
            normalized_code = code_normalization.get(code, code)
            if len(normalized_code) == 3:
                # Still 3-letter, try to extract 2-letter
                normalized_code = code[:2] if len(code) >= 2 else code
            
            # Check if this normalized code is one we want to keep
            if normalized_code in valid_country_codes:
                currency_code = country.currency_code.upper() if country.currency_code else None
                expected_currency = None
                for curr_code, (country_code, _) in currency_to_country.items():
                    if country_code == normalized_code:
                        expected_currency = curr_code
                        break
                
                # Check if we already have a country for this code
                if normalized_code not in countries_to_keep:
                    # This is the first/only country for this code - keep it
                    countries_to_keep[normalized_code] = country.id
                    # Update country to ensure it has correct code and currency
                    if country.country_code != normalized_code or country.currency_code != expected_currency:
                        country.country_code = normalized_code
                        if expected_currency:
                            country.currency_code = expected_currency
                        country.is_active = True
                        # Update country name if needed
                        for curr_code, (country_code, country_name) in currency_to_country.items():
                            if country_code == normalized_code:
                                country.country_name = country_name
                                break
                        updated_count += 1
                    kept_count += 1
                else:
                    # Duplicate - delete this one
                    countries_to_delete.append(country.id)
            else:
                # Not a valid country code - delete it
                countries_to_delete.append(country.id)
        
        # Delete all countries that are not in our keep list
        if countries_to_delete:
            deleted_count = Country.query.filter(Country.id.in_(countries_to_delete)).delete(synchronize_session=False)
        
        # Create missing countries for active currencies
        for currency in active_currencies:
            currency_code = currency.currency_code.upper()
            if currency_code in currency_to_country:
                country_code, country_name = currency_to_country[currency_code]
                
                # Check if we already have this country
                existing = Country.query.filter(
                    func.upper(Country.country_code) == country_code.upper()
                ).first()
                
                if not existing:
                    # Create new country
                    new_country = Country(
                        country_code=country_code,
                        country_name=country_name,
                        currency_code=currency_code,
                        is_active=True
                    )
                    db.session.add(new_country)
                    created_count += 1
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Cleanup completed: {deleted_count} countries deleted, {kept_count} kept, {created_count} created, {updated_count} updated. Total countries: {len(countries_to_keep) + created_count}',
            'deleted': deleted_count,
            'kept': kept_count,
            'created': created_count,
            'updated': updated_count,
            'total': len(countries_to_keep) + created_count
        }), 200
        
    except Exception as e:
        db.session.rollback()
        print(f"[ERROR] Failed to cleanup countries: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

@app.route('/api/countries/sync-with-currencies', methods=['POST'])
@jwt_required()
def sync_countries_with_currencies():
    """
    Sync countries table with currencies table
    Creates missing countries for active currencies and ensures consistency
    """
    try:
        # Get active currencies
        active_currencies = Currency.query.filter_by(is_active=True).all()
        
        # Map currencies to their primary countries
        currency_to_country = {
            'USD': ('US', 'United States'),
            'INR': ('IN', 'India'),
            'EUR': ('DE', 'Germany'),  # Using Germany as primary EUR country
            'GBP': ('GB', 'United Kingdom'),
            'AUD': ('AU', 'Australia'),
            'CAD': ('CA', 'Canada'),
            'JPY': ('JP', 'Japan'),
            'SAR': ('SA', 'Saudi Arabia'),
            'CNY': ('CN', 'China'),
            'BRL': ('BR', 'Brazil'),
            'SGD': ('SG', 'Singapore'),
            'CHF': ('CH', 'Switzerland'),
            'ZAR': ('ZA', 'South Africa'),
            'NZD': ('NZ', 'New Zealand'),
            'AED': ('AE', 'United Arab Emirates')
        }
        
        created_count = 0
        updated_count = 0
        
        for currency in active_currencies:
            currency_code = currency.currency_code.upper()
            if currency_code in currency_to_country:
                country_code, country_name = currency_to_country[currency_code]
                
                # Check if country exists (case-insensitive)
                existing = Country.query.filter(
                    func.upper(Country.country_code) == country_code.upper()
                ).first()
                
                if existing:
                    # Update existing country
                    if existing.currency_code.upper() != currency_code:
                        existing.currency_code = currency_code
                        updated_count += 1
                    if not existing.is_active:
                        existing.is_active = True
                    if existing.country_name != country_name:
                        existing.country_name = country_name
                else:
                    # Create new country
                    new_country = Country(
                        country_code=country_code,
                        country_name=country_name,
                        currency_code=currency_code,
                        is_active=True
                    )
                    db.session.add(new_country)
                    created_count += 1
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Sync completed: {created_count} countries created, {updated_count} updated',
            'created': created_count,
            'updated': updated_count
        }), 200
        
    except Exception as e:
        db.session.rollback()
        print(f"[ERROR] Failed to sync countries with currencies: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

