@app.route('/api/rewards-v2/transactions', methods=['GET'])
@jwt_required()
def get_rewards_v2_transactions():
    """Get reward transactions for rewards-v2 page"""
    try:
        limit = request.args.get('limit', 100, type=int)
        user_id_filter = request.args.get('user_id', type=int)
        
        # Get conversion rate from reward_settings table dynamically
        conversion_rate = 0.1  # Default fallback
        try:
            # Try points_to_currency_rate first
            rate_query = text("""
                SELECT setting_value FROM reward_settings 
                WHERE setting_key = 'points_to_currency_rate' OR setting_key = 'conversion_rate'
                ORDER BY CASE WHEN setting_key = 'points_to_currency_rate' THEN 1 ELSE 2 END
                LIMIT 1
            """)
            result = db.session.execute(rate_query).fetchone()
            if result and result[0]:
                conversion_rate = float(result[0])
                print(f"[Transactions] Conversion rate from DB: {result[0]} -> {conversion_rate}")
        except Exception as rate_error:
            print(f"[Transactions] Error fetching conversion rate: {str(rate_error)}, using default 0.1")
        
        # Use raw SQL to join with users table
        query = text("""
            SELECT 
                rt.id, rt.user_id, rt.transaction_type, rt.points,
                rt.balance_after, rt.description, rt.created_at,
                u.full_name, u.email
            FROM reward_transactions rt
            LEFT JOIN users u ON rt.user_id = u.id
            WHERE (:user_id IS NULL OR rt.user_id = :user_id)
            ORDER BY rt.created_at DESC
            LIMIT :limit
        """)
        
        result = db.session.execute(query, {
            'user_id': user_id_filter,
            'limit': limit
        }).fetchall()
        
        transactions_data = [{
            'id': row[0],
            'user_id': row[1],
            'transaction_type': row[2],
            'points': row[3],
            'balance_after': row[4],
            'description': row[5],
            'created_at': row[6].isoformat() if row[6] else None,
            'user_name': row[7] or f'User #{row[1]}',
            'full_name': row[7],
            'user_email': row[8] or '',
            'value_in_currency': row[3] * conversion_rate if row[3] else 0  # Dynamic conversion rate
        } for row in result]
        
        print(f"[Transactions] Returning {len(transactions_data)} transactions with conversion rate {conversion_rate}")
        return jsonify({'transactions': transactions_data}), 200
    except Exception as e:
        print(f"[Transactions] Error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'transactions': []}), 200

# Helper function to apply reward campaigns to an order
def apply_reward_campaigns(user_id, order_id, order_total, base_points):
    """
    Apply active reward campaigns to calculate final reward points.
    Returns: (final_points, applied_campaigns_list)
    """
    try:
        from datetime import date, datetime
        import json
        
        # Get user's tier
        user_tier_query = text("""
            SELECT COALESCE(user_tier, 'bronze') FROM user_reward_summary WHERE user_id = :user_id
        """)
        tier_result = db.session.execute(user_tier_query, {'user_id': user_id}).fetchone()
        user_tier = (tier_result[0] if tier_result else 'bronze').lower()
        
        # Get today's date (IST)
        today = date.today()
        
        # Query active campaigns applicable to this user
        campaigns_query = text("""
            SELECT 
                id, name, campaign_type, bonus_multiplier, bonus_points,
                min_purchase_amount, applicable_tiers, valid_from, valid_until,
                is_active, priority, stackable, max_uses_per_user, auto_apply
            FROM reward_campaigns
            WHERE is_active = 1
                AND (valid_from IS NULL OR DATE(valid_from) <= :today)
                AND (valid_until IS NULL OR DATE(valid_until) >= :today)
                AND (min_purchase_amount IS NULL OR min_purchase_amount <= :order_total)
            ORDER BY priority DESC, created_at DESC
        """)
        
        campaigns_result = db.session.execute(campaigns_query, {
            'today': today,
            'order_total': order_total
        }).fetchall()
        
        applied_campaigns = []
        final_points = base_points
        applied_multiplier = 1.0
        total_bonus_points = 0
        multiplier_campaigns = []  # Track multiplier campaigns separately
        
        for campaign_row in campaigns_result:
            campaign_id = campaign_row[0]
            campaign_name = campaign_row[1]
            campaign_type = campaign_row[2]
            bonus_multiplier = float(campaign_row[3]) if campaign_row[3] else 1.0
            bonus_points = int(campaign_row[4]) if campaign_row[4] else 0
            min_purchase = float(campaign_row[5]) if campaign_row[5] else 0
            applicable_tiers_str = campaign_row[6] or ''
            valid_from = campaign_row[7]
            valid_until = campaign_row[8]
            is_active = bool(campaign_row[9])
            priority = int(campaign_row[10]) if campaign_row[10] else 0
            stackable = bool(campaign_row[11])
            max_uses = int(campaign_row[12]) if campaign_row[12] else None
            
            # Check tier eligibility
            if applicable_tiers_str:
                try:
                    if applicable_tiers_str.startswith('['):
                        applicable_tiers = json.loads(applicable_tiers_str)
                    else:
                        applicable_tiers = [t.strip().lower() for t in applicable_tiers_str.split(',') if t.strip()]
                    
                    if applicable_tiers and user_tier not in [t.lower() for t in applicable_tiers]:
                        continue  # User tier not eligible
                except:
                    pass  # If parsing fails, allow campaign
            
            # Check max uses per user
            if max_uses:
                usage_count_query = text("""
                    SELECT COUNT(*) FROM order_campaign_applications
                    WHERE campaign_id = :campaign_id AND order_id IN (
                        SELECT id FROM orders WHERE user_id = :user_id
                    )
                """)
                usage_count = db.session.execute(usage_count_query, {
                    'campaign_id': campaign_id,
                    'user_id': user_id
                }).fetchone()[0] or 0
                
                if usage_count >= max_uses:
                    continue  # User has exceeded max uses
            
            # Apply campaign based on type
            campaign_applied = False
            campaign_multiplier = 1.0
            campaign_bonus = 0
            
            if campaign_type == 'multiplier':
                # Apply multiplier (only highest priority multiplier applies unless stackable)
                if stackable:
                    # Stackable: multiply together
                    multiplier_campaigns.append({'multiplier': bonus_multiplier, 'priority': priority, 'campaign_id': campaign_id})
                    campaign_applied = True
                    campaign_multiplier = bonus_multiplier
                elif applied_multiplier == 1.0:
                    # Non-stackable: only apply if no multiplier yet
                    applied_multiplier = bonus_multiplier
                    campaign_applied = True
                    campaign_multiplier = bonus_multiplier
            elif campaign_type == 'bonus_points':
                # Add bonus points (can stack)
                total_bonus_points += bonus_points
                campaign_applied = True
                campaign_bonus = bonus_points
            elif campaign_type == 'double_points':
                # Double points multiplier
                if stackable:
                    multiplier_campaigns.append({'multiplier': 2.0, 'priority': priority, 'campaign_id': campaign_id})
                    campaign_applied = True
                    campaign_multiplier = 2.0
                elif applied_multiplier == 1.0:
                    applied_multiplier = 2.0
                    campaign_applied = True
                    campaign_multiplier = 2.0
            elif campaign_type == 'birthday_bonus':
                # Check if user's birthday matches (simplified - would need user DOB)
                # For now, just add bonus points
                total_bonus_points += bonus_points
                campaign_applied = True
                campaign_bonus = bonus_points
            elif campaign_type == 'signup_bonus':
                # Check if this is user's first order
                first_order_query = text("""
                    SELECT COUNT(*) FROM orders WHERE user_id = :user_id AND payment_status = 'paid'
                """)
                order_count = db.session.execute(first_order_query, {'user_id': user_id}).fetchone()[0] or 0
                if order_count <= 1:  # First or second order (accounting for current order)
                    total_bonus_points += bonus_points
                    campaign_applied = True
                    campaign_bonus = bonus_points
            
            if campaign_applied:
                # Record campaign application
                try:
                    insert_campaign_query = text("""
                        INSERT INTO order_campaign_applications 
                        (order_id, campaign_id, points_earned, multiplier_applied, bonus_points, created_at)
                        VALUES (:order_id, :campaign_id, :points, :multiplier, :bonus, NOW())
                    """)
                    db.session.execute(insert_campaign_query, {
                        'order_id': order_id,
                        'campaign_id': campaign_id,
                        'points': base_points,  # Base points before multiplier
                        'multiplier': campaign_multiplier,
                        'bonus': campaign_bonus
                    })
                    
                    applied_campaigns.append({
                        'campaign_id': campaign_id,
                        'campaign_name': campaign_name,
                        'campaign_type': campaign_type,
                        'multiplier': campaign_multiplier,
                        'bonus_points': campaign_bonus
                    })
                    
                    print(f"[Campaign Applied] Campaign '{campaign_name}' (ID: {campaign_id}, Type: {campaign_type}) applied to order {order_id}")
                except Exception as insert_err:
                    print(f"[Campaign] Error recording campaign application: {insert_err}")
                    db.session.rollback()
        
        # Calculate final multiplier (multiply all stackable multipliers, or use highest non-stackable)
        if multiplier_campaigns:
            # Sort by priority and multiply together
            multiplier_campaigns.sort(key=lambda x: x['priority'], reverse=True)
            for mc in multiplier_campaigns:
                applied_multiplier *= mc['multiplier']
        elif applied_multiplier == 1.0:
            # No multiplier campaigns applied, keep base
            applied_multiplier = 1.0
        
        # Calculate final points: (base_points * multiplier) + bonus_points
        final_points = int(round(base_points * applied_multiplier)) + total_bonus_points
        
        print(f"[Campaign] Query found {len(campaigns_result)} active campaigns for order {order_id}")
        if applied_campaigns:
            print(f"[Campaign] ✅ Applied {len(applied_campaigns)} campaigns. Base: {base_points}, Multiplier: {applied_multiplier}, Bonus: {total_bonus_points}, Final: {final_points}")
            for camp in applied_campaigns:
                print(f"[Campaign]   - {camp['campaign_name']} ({camp['campaign_type']}): multiplier={camp['multiplier']}, bonus={camp['bonus_points']}")
        else:
            print(f"[Campaign] ⚠️ No campaigns applied. Base: {base_points}, Final: {final_points}")
        
        return final_points, applied_campaigns
        
    except Exception as e:
        print(f"[Campaign] Error applying campaigns: {str(e)}")
        import traceback
        traceback.print_exc()
        # Return base points if campaign application fails
        return base_points, []

# Helper function to validate stacking (coupon + reward points)
def validate_stacking(coupon_code, reward_points_used):
    """
    Validate if coupon can be combined with reward points.
    Returns: (is_valid, error_message)
    """
    try:
        from datetime import date, datetime
        
        # Both coupon and reward points must be present for stacking validation
        if not coupon_code:
            return False, "Coupon code is required to test stacking"
        
        if not reward_points_used or reward_points_used == 0:
            return False, "Reward points must be greater than 0 to test stacking"
        
        # Find coupon
        coupon = Coupon.query.filter_by(code=coupon_code.upper()).first()
        if not coupon:
            return False, f"Coupon '{coupon_code}' not found"
        
        # Check if coupon is active
        if not coupon.is_active:
            return False, f"Coupon '{coupon_code}' is not active"
        
        # Check coupon expiration - handle both date and datetime objects
        today = date.today()
        
        # Convert valid_from to date if it's a datetime
        if coupon.valid_from:
            valid_from = coupon.valid_from
            if isinstance(valid_from, datetime):
                valid_from = valid_from.date()
            elif isinstance(valid_from, str):
                # Parse string date
                try:
                    valid_from = datetime.strptime(valid_from.split('T')[0], '%Y-%m-%d').date()
                except:
                    valid_from = None
            
            if valid_from and today < valid_from:
                return False, f"Coupon '{coupon_code}' is not yet valid (valid from {valid_from})"
        
        # Convert valid_until to date if it's a datetime
        if coupon.valid_until:
            valid_until = coupon.valid_until
            if isinstance(valid_until, datetime):
                valid_until = valid_until.date()
            elif isinstance(valid_until, str):
                # Parse string date
                try:
                    valid_until = datetime.strptime(valid_until.split('T')[0], '%Y-%m-%d').date()
                except:
                    valid_until = None
            
            if valid_until and today > valid_until:
                return False, f"Coupon '{coupon_code}' has expired (expired on {valid_until})"
        
        # Check if coupon allows combining with reward points
        if not coupon.can_combine_with_reward_points:
            return False, f"Coupon '{coupon_code}' cannot be combined with reward points. Please use either the coupon or reward points, not both."
        
        return True, f"Coupon '{coupon_code}' can be combined with reward points"
        
    except Exception as e:
        print(f"[Stacking Validation] Error: {str(e)}")
        import traceback
        traceback.print_exc()
        return False, f"Error validating stacking: {str(e)}"

# Helper function to get conversion rate from reward_settings table
def get_conversion_rate():
    """Get points to currency conversion rate from reward_settings table"""
    try:
        # Try points_to_currency_rate first, then conversion_rate
        rate_query = text("""
            SELECT setting_value FROM reward_settings 
            WHERE setting_key = 'points_to_currency_rate' OR setting_key = 'conversion_rate'
            ORDER BY CASE WHEN setting_key = 'points_to_currency_rate' THEN 1 ELSE 2 END
            LIMIT 1
        """)
        result = db.session.execute(rate_query).fetchone()
        if result and result[0]:
            rate_value = float(result[0])
            print(f"[Conversion Rate] Read from reward_settings: {result[0]} -> {rate_value}")
            return rate_value
    except Exception as e:
        print(f"[Conversion Rate] Error fetching from reward_settings: {str(e)}, using default 0.1")
    return 0.1  # Default fallback

