@app.route('/api/reward-campaigns/campaigns', methods=['POST'])
@jwt_required()
def create_reward_campaign():
    """Create a new reward campaign"""
    try:
        data = request.get_json()
        
        # Ensure reward_campaigns table has all required columns
        try:
            alter_table = text("""
                ALTER TABLE reward_campaigns
                ADD COLUMN IF NOT EXISTS priority INT DEFAULT 0,
                ADD COLUMN IF NOT EXISTS stackable BOOLEAN DEFAULT FALSE,
                ADD COLUMN IF NOT EXISTS max_uses_per_user INT NULL,
                ADD COLUMN IF NOT EXISTS auto_apply BOOLEAN DEFAULT FALSE
            """)
            db.session.execute(alter_table)
            db.session.commit()
        except Exception as alter_err:
            # Columns might already exist, ignore
            db.session.rollback()
            pass
        
        # Handle bonus_multiplier vs bonus_points based on campaign_type
        bonus_multiplier = None
        bonus_points = None
        if data.get('campaign_type') == 'multiplier':
            bonus_multiplier = float(data.get('bonus_multiplier') or data.get('multiplier_value', 1.0))
        elif data.get('campaign_type') == 'bonus_points':
            bonus_points = int(data.get('bonus_points', 0))
        
        # Handle applicable_tiers
        applicable_tiers = data.get('applicable_tiers', [])
        if isinstance(applicable_tiers, list):
            tiers_str = json.dumps(applicable_tiers) if applicable_tiers else ''
        else:
            tiers_str = str(applicable_tiers) if applicable_tiers else ''
        
        # Handle date strings - remove timezone if present
        valid_from = data.get('valid_from')
        valid_until = data.get('valid_until')
        if valid_from and 'T' in valid_from:
            valid_from = valid_from.split('T')[0]
        if valid_until and 'T' in valid_until:
            valid_until = valid_until.split('T')[0]
        
        query = text("""
            INSERT INTO reward_campaigns (
                name, description, campaign_type, bonus_multiplier, bonus_points,
                min_purchase_amount, applicable_tiers, valid_from, valid_until, 
                is_active, priority, stackable, max_uses_per_user, auto_apply
            ) VALUES (
                :name, :description, :campaign_type, :bonus_multiplier, :bonus_points,
                :min_purchase, :tiers, :valid_from, :valid_until, :is_active,
                :priority, :stackable, :max_uses, :auto_apply
            )
        """)
        
        db.session.execute(query, {
            'name': data.get('name'),
            'description': data.get('description', ''),
            'campaign_type': data.get('campaign_type', 'multiplier'),
            'bonus_multiplier': bonus_multiplier,
            'bonus_points': bonus_points,
            'min_purchase': float(data.get('min_purchase_amount', 0)),
            'tiers': tiers_str,
            'valid_from': valid_from,
            'valid_until': valid_until,
            'is_active': bool(data.get('is_active', True)),
            'priority': int(data.get('priority', 0)),
            'stackable': bool(data.get('stackable', False)),
            'max_uses': int(data.get('max_uses_per_user')) if data.get('max_uses_per_user') else None,
            'auto_apply': bool(data.get('auto_apply', False))
        })
        
        db.session.commit()
        print(f"[Campaigns] Created campaign: {data.get('name')}")
        return jsonify({'success': True, 'message': 'Campaign created successfully'}), 201
    except Exception as e:
        db.session.rollback()
        print(f"[Campaigns] Create error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500
