@app.route('/api/reward-transactions/', methods=['POST'])
@jwt_required()
def create_reward_transaction():
    """Create reward transaction (earn/redeem points)"""
    try:
        data = request.get_json()
        user_id = data.get('user_id')
        
        # Get user
        user = db.session.get(User, user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        
        points = data.get('points', 0)
        transaction_type = data.get('transaction_type', 'earned')
        
        # Update user balance
        if transaction_type == 'earned':
            user.reward_points += points
        elif transaction_type == 'redeemed':
            if user.reward_points < points:
                return jsonify({'error': 'Insufficient reward points'}), 400
            user.reward_points -= points
        
        # Create transaction record
        # Normalize reference_type to ensure it fits database constraints (max 20 chars, or ENUM)
        ref_type = data.get('reference_type')
        if ref_type:
            # Map long values to shorter standard values
            ref_type_lower = ref_type.lower()
            if 'admin' in ref_type_lower:
                ref_type = 'admin'
            elif 'order' in ref_type_lower:
                ref_type = 'order'
            elif 'review' in ref_type_lower:
                ref_type = 'product_review'
            elif 'referral' in ref_type_lower:
                ref_type = 'referral'
            elif len(ref_type) > 20:
                ref_type = ref_type[:20]  # Truncate to 20 chars if still too long
        
        transaction = RewardTransaction(
            user_id=user_id,
            transaction_type=transaction_type,
            points=points,
            balance_after=user.reward_points,
            reference_type=ref_type,
            reference_id=data.get('reference_id'),
            description=data.get('description'),
            expiry_date=parse_date(data.get('expiry_date'))
        )
        
        db.session.add(transaction)
        db.session.commit()
        
        return jsonify({
            'message': 'Reward transaction created successfully',
            'transaction_id': transaction.id,
            'new_balance': user.reward_points
        }), 201
        
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500
