@app.route('/api/wallet-transactions/', methods=['POST'])
@jwt_required()
def create_wallet_transaction():
    """Create wallet transaction (credit/debit)"""
    try:
        data = request.get_json()
        user_id = data.get('user_id')
        
        # Get user
        user = db.session.get(User, user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        
        amount = data.get('amount', 0)
        transaction_type = data.get('transaction_type', 'credit')
        
        # Update user wallet balance
        if transaction_type == 'credit' or transaction_type == 'refund':
            user.wallet_balance += amount
        elif transaction_type == 'debit':
            if user.wallet_balance < amount:
                return jsonify({'error': 'Insufficient wallet balance'}), 400
            user.wallet_balance -= amount
        
        # Create transaction record
        # Normalize reference_type to ensure it fits database constraints
        ref_type = data.get('reference_type')
        if ref_type:
            # Map long values to shorter standard values
            ref_type_lower = ref_type.lower()
            if 'admin' in ref_type_lower:
                ref_type = 'admin'
            elif 'order' in ref_type_lower:
                ref_type = 'order'
            elif 'refund' in ref_type_lower:
                ref_type = 'refund'
            elif len(ref_type) > 20:
                ref_type = ref_type[:20]  # Truncate to 20 chars if still too long
        
        transaction = WalletTransaction(
            user_id=user_id,
            transaction_type=transaction_type,
            amount=amount,
            currency=data.get('currency', 'INR'),
            balance_after=user.wallet_balance,
            reference_type=ref_type,
            reference_id=data.get('reference_id'),
            description=data.get('description'),
            status=data.get('status', 'completed')
        )
        
        db.session.add(transaction)
        db.session.commit()
        
        return jsonify({
            'message': 'Wallet transaction created successfully',
            'transaction_id': transaction.id,
            'new_balance': user.wallet_balance
        }), 201
        
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

