@app.route('/api/messages/enquiries', methods=['GET'])
@jwt_required()
def get_enquiries():
    """Get all enquiries/messages with filtering and search"""
    try:
        status = request.args.get('status', 'all')
        search = request.args.get('search', '')
        
        query = Message.query
        
        # Filter by status
        if status and status != 'all':
            query = query.filter_by(status=status)
        
        # Search functionality
        if search:
            search_pattern = f'%{search}%'
            query = query.filter(
                or_(
                    Message.name.like(search_pattern),
                    Message.email.like(search_pattern),
                    Message.subject.like(search_pattern),
                    Message.message.like(search_pattern)
                )
            )
        
        # Order by created_at descending (newest first)
        messages = query.order_by(desc(Message.created_at)).all()
        
        # Calculate stats
        total_messages = Message.query.count()
        unread_count = Message.query.filter_by(status='unread').count()
        read_count = Message.query.filter_by(status='read').count()
        replied_count = Message.query.filter_by(status='replied').count()
        
        # Transform messages data
        messages_data = [{
            'id': msg.id,
            'name': msg.name,
            'email': msg.email,
            'phone': msg.phone,
            'subject': msg.subject,
            'message': msg.message,
            'status': msg.status,
            'is_starred': msg.is_starred,
            'replied_at': msg.replied_at.isoformat() if msg.replied_at else None,
            'created_at': msg.created_at.isoformat() if msg.created_at else None,
            'admin_notes': getattr(msg, 'admin_notes', None)  # In case this column exists
        } for msg in messages]
        
        return jsonify({
            'success': True,
            'data': messages_data,
            'stats': {
                'total': total_messages,
                'unread': unread_count,
                'read': read_count,
                'replied': replied_count
            }
        }), 200
        
    except Exception as e:
        print(f"Error fetching enquiries: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

