@app.route('/api/settings', methods=['GET'])
@jwt_required()
def get_general_settings():
    """Get general settings - ONLY from settings table"""
    try:
        settings = {}
        
        # ONLY read from settings table (single source of truth)
        try:
            # Simple query - get all settings from settings table
            query_settings = text("""
                SELECT setting_key, setting_value, setting_type, updated_at
                FROM settings
                WHERE category IN ('general', 'store') OR setting_key LIKE 'store_%'
                ORDER BY setting_key, updated_at DESC
            """)
            result_settings = db.session.execute(query_settings).fetchall()
            
            # Get the most recent updated_at timestamp from all general/store settings
            max_updated_query = text("""
                SELECT MAX(updated_at) as last_updated
                FROM settings
                WHERE category IN ('general', 'store') OR setting_key LIKE 'store_%'
            """)
            max_updated_result = db.session.execute(max_updated_query).fetchone()
            last_updated_at = max_updated_result[0] if max_updated_result and max_updated_result[0] else None
            
            # Process results - if duplicates exist, use the most recent (first one due to DESC)
            seen_keys = set()
            for row in result_settings:
                key = row[0]
                if key not in seen_keys:  # Only take first occurrence (most recent)
                    seen_keys.add(key)
                    value = row[1]
                    setting_type = row[2] if len(row) > 2 else 'string'
                    
                    # Convert based on type
                    if setting_type == 'json':
                        try:
                            value = json.loads(value)
                        except:
                            pass
                    elif setting_type == 'boolean':
                        value = value.lower() in ('true', '1', 'yes') if value else False
                    elif setting_type == 'number':
                        try:
                            value = float(value) if '.' in str(value) else int(value) if value else 0
                        except (ValueError, TypeError):
                            value = 0
                    
                    settings[key] = value
                    print(f"[GENERAL SETTINGS GET] Loaded: {key} = {str(value)[:50]}")
            
            print(f"[GENERAL SETTINGS GET] ✅ Loaded {len(settings)} settings from settings table")
            if last_updated_at:
                print(f"[GENERAL SETTINGS GET] Last updated at: {last_updated_at}")
        except Exception as settings_err:
            print(f"[GENERAL SETTINGS GET] ❌ Error reading from settings table: {settings_err}")
            import traceback
            traceback.print_exc()
        
        # Default values if no settings found
        if not settings:
            settings = {
                'store_name': 'My Store',
                'store_email': 'contact@example.com',
                'store_phone': '+1 (555) 000-0000',
                'legal_name': '',
                'address': {'street': '', 'city': '', 'state': '', 'postal_code': '', 'country': ''},
                'timezone': 'UTC',
                'currency': 'USD',
                'weight_unit': 'kg',
                'order_prefix': '#',
                'order_suffix': '',
                'locale': 'en'
            }
        
        # Format last_updated_at for JSON response - ensure ISO format with timezone
        last_updated_str = None
        if last_updated_at:
            try:
                from datetime import datetime, timezone
                if isinstance(last_updated_at, datetime):
                    # Make timezone-aware if it's naive (assume UTC)
                    if last_updated_at.tzinfo is None:
                        last_updated_at = last_updated_at.replace(tzinfo=timezone.utc)
                    # Convert to ISO format string
                    last_updated_str = last_updated_at.isoformat()
                elif isinstance(last_updated_at, str):
                    # If it's already a string, try to parse and reformat it
                    try:
                        # Try parsing as MySQL datetime format
                        if ' ' in last_updated_at and 'T' not in last_updated_at:
                            # MySQL format: YYYY-MM-DD HH:MM:SS
                            parsed_dt = datetime.strptime(last_updated_at, '%Y-%m-%d %H:%M:%S')
                            parsed_dt = parsed_dt.replace(tzinfo=timezone.utc)
                            last_updated_str = parsed_dt.isoformat()
                        else:
                            # Already in ISO format or other format
                            parsed_dt = datetime.fromisoformat(last_updated_at.replace('Z', '+00:00'))
                            if parsed_dt.tzinfo is None:
                                parsed_dt = parsed_dt.replace(tzinfo=timezone.utc)
                            last_updated_str = parsed_dt.isoformat()
                    except:
                        # If parsing fails, use the string as-is
                        last_updated_str = last_updated_at
                else:
                    last_updated_str = str(last_updated_at)
                print(f"[GENERAL SETTINGS GET] Formatted last_updated_at: {last_updated_str}")
            except Exception as fmt_err:
                print(f"[GENERAL SETTINGS GET] Error formatting timestamp: {fmt_err}")
                import traceback
                traceback.print_exc()
                last_updated_str = str(last_updated_at) if last_updated_at else None
        
        return jsonify({
            'success': True,
            'settings': settings,
            'meta': {'last_updated_at': last_updated_str}
        }), 200
    except Exception as e:
        print(f"Error fetching general settings: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings', methods=['PUT'])
@jwt_required()
def update_general_settings():
    """Update general settings - ONLY use settings table"""
    try:
        data = request.get_json()
        settings_data = data.get('settings', {})
        user_id = get_jwt_identity()
        
        # Extract numeric admin ID if needed
        if isinstance(user_id, str) and user_id.startswith('admin_'):
            try:
                user_id = int(user_id.replace('admin_', ''))
            except ValueError:
                pass
        
        print(f"[GENERAL SETTINGS UPDATE] Received {len(settings_data)} settings to update")
        print(f"[GENERAL SETTINGS UPDATE] User ID: {user_id}")
        
        if not settings_data:
            return jsonify({'success': False, 'error': 'No settings data provided'}), 400
        
        updated_count = 0
        
        for key, value in settings_data.items():
            setting_type = 'string'
            original_value = value
            
            # Convert value to string based on type
            if isinstance(value, bool):
                setting_type = 'boolean'
                value = str(value).lower()
            elif isinstance(value, (int, float)):
                setting_type = 'number'
                value = str(value)
            elif isinstance(value, dict):
                setting_type = 'json'
                value = json.dumps(value)
            elif value is None:
                value = ''
            else:
                value = str(value)
            
            print(f"[GENERAL SETTINGS UPDATE] Processing: {key} = {value[:100]} (type: {setting_type})")
            
            # Determine category
            category = 'general'
            if key.startswith('store_'):
                category = 'store'
            
            # SIMPLE APPROACH: Delete all existing rows for this key, then insert new one
            # This ensures no duplicates and always has the latest value
            try:
                # Delete all existing rows with this key
                delete_query = text("""
                    DELETE FROM settings 
                    WHERE setting_key = :key
                """)
                deleted = db.session.execute(delete_query, {'key': key}).rowcount
                if deleted > 0:
                    print(f"[GENERAL SETTINGS UPDATE] Deleted {deleted} old row(s) for {key}")
                
                # Insert the new/updated value
                insert_query = text("""
                    INSERT INTO settings (setting_key, setting_value, setting_type, category, updated_by, created_at, updated_at)
                    VALUES (:key, :value, :type, :category, :user_id, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                """)
                db.session.execute(insert_query, {
                    'key': key,
                    'value': value,
                    'type': setting_type,
                    'category': category,
                    'user_id': user_id
                })
                updated_count += 1
                print(f"[GENERAL SETTINGS UPDATE] ✅ Saved: {key} = {value[:50]}")
                
            except Exception as e:
                print(f"[GENERAL SETTINGS UPDATE] ❌ Error saving {key}: {str(e)}")
                import traceback
                traceback.print_exc()
                db.session.rollback()
                return jsonify({
                    'success': False,
                    'error': f'Failed to save setting {key}: {str(e)}'
                }), 500
        
        # Commit all changes
        db.session.commit()
        print(f"[GENERAL SETTINGS UPDATE] ✅ Successfully saved {updated_count} settings to settings table")
        
        # Verify the save by reading back from database
        try:
            keys_list = list(settings_data.keys())
            if keys_list:
                placeholders = ','.join([f':key{i}' for i in range(len(keys_list))])
                verify_query = text(f"""
                    SELECT setting_key, setting_value, updated_at
                    FROM settings 
                    WHERE setting_key IN ({placeholders})
                    ORDER BY setting_key
                """)
                params = {f'key{i}': key for i, key in enumerate(keys_list)}
                verify_result = db.session.execute(verify_query, params).fetchall()
                print(f"[GENERAL SETTINGS UPDATE] Verification - Read back {len(verify_result)} settings from settings table:")
                for row in verify_result:
                    print(f"  ✅ {row[0]}: {row[1][:50]} (updated: {row[2]})")
        except Exception as verify_err:
            print(f"[GENERAL SETTINGS UPDATE] Warning: Could not verify saved settings: {verify_err}")
        
        return jsonify({
            'success': True, 
            'message': 'Settings updated successfully',
            'updated_count': updated_count
        }), 200
    except Exception as e:
        db.session.rollback()
        print(f"[GENERAL SETTINGS UPDATE] ❌ Error updating general settings: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings/billing', methods=['GET'])
@jwt_required()
def get_billing_settings():
    """Get billing settings - check both app_settings and settings tables"""
    try:
        user_id = get_jwt_identity()
        print(f"[BILLING GET] JWT identity: {user_id}")
        
        # Remove 'admin_' prefix if present
        if user_id and str(user_id).startswith('admin_'):
            user_id = int(str(user_id).replace('admin_', ''))
        
        print(f"[BILLING GET] Querying for user_id: {user_id}")
        billing = {}
        
        # 1. Try app_settings table first (new table)
        try:
            query_app = text("""
                SELECT setting_key, setting_value, setting_type
                FROM app_settings
                WHERE category = 'billing' AND user_id = :user_id
            """)
            result_app = db.session.execute(query_app, {'user_id': user_id}).fetchall()
            print(f"[BILLING GET] Found {len(result_app)} billing settings in app_settings for user {user_id}")
            
            for row in result_app:
                key = row[0]
                value = row[1]
                setting_type = row[2] if len(row) > 2 else 'string'
                
                # Parse JSON values
                if setting_type == 'json':
                    try:
                        value = json.loads(value)
                    except:
                        pass
                elif setting_type == 'number':
                    try:
                        value = float(value) if '.' in str(value) else int(value)
                    except:
                        pass
                
                billing[key] = value
        except Exception as app_err:
            print(f"[BILLING GET] ⚠️ Could not read from app_settings: {app_err}")
        
        # 2. If no data found, try settings table (legacy)
        if not billing or len(billing) == 0:
            try:
                query_settings = text("""
                    SELECT setting_key, setting_value, setting_type
                    FROM settings
                    WHERE category = 'billing' AND updated_by = :user_id
                """)
                result_settings = db.session.execute(query_settings, {'user_id': user_id}).fetchall()
                print(f"[BILLING GET] Found {len(result_settings)} billing settings in settings table for user {user_id}")
                
                for row in result_settings:
                    key = row[0]
                    value = row[1]
                    setting_type = row[2] if len(row) > 2 else 'string'
                    
                    # Parse JSON values
                    if setting_type == 'json':
                        try:
                            value = json.loads(value)
                        except:
                            pass
                    elif setting_type == 'number':
                        try:
                            value = float(value) if '.' in str(value) else int(value)
                        except:
                            pass
                    
                    billing[key] = value
            except Exception as settings_err:
                print(f"[BILLING GET] ⚠️ Could not read from settings table: {settings_err}")
        
        # 3. If still no data, try user_id = 1 (default admin)
        if not billing or len(billing) == 0:
            try:
                query_default = text("""
                    SELECT setting_key, setting_value, setting_type
                    FROM app_settings
                    WHERE category = 'billing' AND user_id = 1
                """)
                result_default = db.session.execute(query_default).fetchall()
                print(f"[BILLING GET] Found {len(result_default)} billing settings for default user (user_id=1)")
                
                for row in result_default:
                    key = row[0]
                    value = row[1]
                    setting_type = row[2] if len(row) > 2 else 'string'
                    
                    # Parse JSON values
                    if setting_type == 'json':
                        try:
                            value = json.loads(value)
                        except:
                            pass
                    elif setting_type == 'number':
                        try:
                            value = float(value) if '.' in str(value) else int(value)
                        except:
                            pass
                    
                    billing[key] = value
            except Exception as default_err:
                print(f"[BILLING GET] ⚠️ Could not read default billing: {default_err}")
        
        # Map backend keys to frontend expected keys
        # Backend uses: plan_price, subscription_status
        # Frontend expects: amount, plan_status, currency, next_billing_date
        
        # Convert plan_price to amount
        if 'plan_price' in billing:
            billing['amount'] = str(billing['plan_price'])
        elif 'amount' in billing:
            billing['amount'] = str(billing['amount'])
        elif 'amount' not in billing:
            billing['amount'] = '0.00'
        
        # Convert subscription_status to plan_status (CRITICAL: check both fields)
        if 'subscription_status' in billing:
            billing['plan_status'] = billing['subscription_status']
        elif 'plan_status' in billing:
            # Keep existing plan_status
            pass
        else:
            billing['plan_status'] = 'active'  # Default to active if not specified
        
        # Ensure plan_status is lowercase for frontend
        if 'plan_status' in billing:
            billing['plan_status'] = str(billing['plan_status']).lower()
        
        # Add currency if not present
        if 'currency' not in billing:
            billing['currency'] = 'USD'
        
        # Calculate next_billing_date if not present
        if 'next_billing_date' not in billing or not billing['next_billing_date']:
            from datetime import datetime, timedelta
            billing_cycle = billing.get('billing_cycle', 'monthly')
            if billing_cycle == 'monthly':
                next_date = datetime.now() + timedelta(days=30)
            else:  # yearly
                next_date = datetime.now() + timedelta(days=365)
            billing['next_billing_date'] = next_date.strftime('%Y-%m-%d')
        
        # Ensure payment_method is properly formatted
        if 'payment_method' in billing and billing['payment_method']:
            if isinstance(billing['payment_method'], str):
                try:
                    billing['payment_method'] = json.loads(billing['payment_method'])
                except:
                    billing['payment_method'] = None
        else:
            billing['payment_method'] = None
        
        # Defaults if empty
        if not billing or len(billing) == 0:
            from datetime import datetime, timedelta
            billing = {
                'plan_name': 'Free',
                'plan_status': 'active',
                'billing_cycle': 'monthly',
                'next_billing_date': (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d'),
                'amount': '0.00',
                'currency': 'USD',
                'payment_method': None
            }
        
        print(f"[BILLING GET] ✅ Returning billing data: plan_name={billing.get('plan_name')}, amount={billing.get('amount')}, plan_status={billing.get('plan_status')}, subscription_status={billing.get('subscription_status')}")
        return jsonify({'success': True, 'billing': billing}), 200
    except Exception as e:
        print(f"[BILLING GET] ❌ Error fetching billing settings: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings/billing/upgrade', methods=['POST'])
@jwt_required()
def upgrade_plan():
    """Upgrade subscription plan"""
    try:
        user_id = get_jwt_identity()
        
        # Remove 'admin_' prefix if present
        if user_id and str(user_id).startswith('admin_'):
            user_id = int(str(user_id).replace('admin_', ''))
        
        data = request.get_json()
        
        plan_name = data.get('plan_name', 'Enterprise Pro')
        amount = data.get('amount', 99.00)
        billing_cycle = data.get('billing_cycle', 'monthly')
        
        # Calculate next billing date
        from datetime import datetime, timedelta
        if billing_cycle == 'monthly':
            next_billing_date = (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d')
        else:  # yearly
            next_billing_date = (datetime.now() + timedelta(days=365)).strftime('%Y-%m-%d')
        
        # Update billing settings - store both plan_price (backend) and amount (frontend compatibility)
        settings_to_update = [
            ('plan_name', plan_name, 'string'),
            ('plan_price', str(amount), 'string'),
            ('amount', str(amount), 'string'),  # Also store as 'amount' for frontend
            ('billing_cycle', billing_cycle, 'string'),
            ('next_billing_date', next_billing_date, 'string'),
            ('plan_status', 'active', 'string'),
            ('subscription_status', 'active', 'string'),  # Keep both for compatibility
            ('currency', 'USD', 'string')  # Default currency
        ]
        
        for key, value, setting_type in settings_to_update:
            # Check if exists first (handle NULL user_id in unique constraint)
            check_query = text("""
                SELECT id FROM app_settings 
                WHERE setting_key = :key AND category = 'billing' AND user_id = :user_id
            """)
            existing = db.session.execute(check_query, {'key': key, 'user_id': user_id}).fetchone()
            
            # 1. Save to app_settings table
            try:
                if existing:
                    update_query = text("""
                        UPDATE app_settings 
                        SET setting_value = :value, 
                            setting_type = :type, 
                            updated_at = UTC_TIMESTAMP()
                        WHERE setting_key = :key AND category = 'billing' AND user_id = :user_id
                    """)
                    db.session.execute(update_query, {'key': key, 'value': str(value), 'type': setting_type, 'user_id': user_id})
                else:
                    insert_query = text("""
                        INSERT INTO app_settings (setting_key, setting_value, setting_type, category, user_id, updated_at)
                        VALUES (:key, :value, :type, 'billing', :user_id, UTC_TIMESTAMP())
                    """)
                    db.session.execute(insert_query, {'key': key, 'value': str(value), 'type': setting_type, 'user_id': user_id})
            except Exception as app_err:
                print(f"[BILLING UPGRADE] ⚠️ Could not update app_settings: {app_err}")
            
            # 2. Also save to settings table (legacy)
            try:
                check_settings = text("""
                    SELECT id FROM settings 
                    WHERE setting_key = :key AND category = 'billing' AND updated_by = :user_id
                """)
                existing_settings = db.session.execute(check_settings, {'key': key, 'user_id': user_id}).fetchone()
                
                if existing_settings:
                    update_settings = text("""
                        UPDATE settings 
                        SET setting_value = :value, 
                            setting_type = :type,
                            updated_at = UTC_TIMESTAMP(),
                            updated_by = :user_id
                        WHERE setting_key = :key AND category = 'billing' AND updated_by = :user_id
                    """)
                    db.session.execute(update_settings, {'key': key, 'value': str(value), 'type': setting_type, 'user_id': user_id})
                else:
                    insert_settings = text("""
                        INSERT INTO settings (setting_key, setting_value, setting_type, category, updated_by, created_at, updated_at)
                        VALUES (:key, :value, :type, 'billing', :user_id, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                    """)
                    db.session.execute(insert_settings, {'key': key, 'value': str(value), 'type': setting_type, 'user_id': user_id})
            except Exception as settings_err:
                print(f"[BILLING UPGRADE] ⚠️ Could not update settings table: {settings_err}")
        
        db.session.commit()
        print(f"[BILLING UPGRADE] ✅ Successfully updated billing settings in BOTH tables for user {user_id}: plan_name={plan_name}, amount={amount}")
        return jsonify({'success': True, 'message': 'Plan upgraded successfully'}), 200
    except Exception as e:
        db.session.rollback()
        print(f"Error upgrading plan: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

