@app.route('/api/settings/security', methods=['GET'])
@jwt_required()
def get_security_settings():
    """Get security settings"""
    try:
        query = text("""
            SELECT setting_key, setting_value
            FROM app_settings
            WHERE category = 'security'
        """)
        result = db.session.execute(query).fetchall()
        
        settings = {}
        for row in result:
            value = row[1]
            if row[0].endswith('_enabled'):
                value = value.lower() in ('true', '1', 'yes')
            settings[row[0]] = value
        
        # Map database keys to frontend expected keys
        mapped_settings = {}
        for key, value in settings.items():
            # Map old keys to new keys for frontend compatibility
            if key == 'require_uppercase':
                mapped_settings['password_require_uppercase'] = value
            elif key == 'require_lowercase':
                mapped_settings['password_require_lowercase'] = value
            elif key == 'require_numbers':
                mapped_settings['password_require_numbers'] = value
            elif key == 'require_symbols' or key == 'require_special':
                mapped_settings['password_require_special'] = value
            elif key == 'login_attempts_limit':
                mapped_settings['login_max_attempts'] = value
            elif key == 'session_timeout_minutes':
                mapped_settings['session_timeout'] = int(value) * 60 if value else None  # Convert minutes to seconds
            else:
                mapped_settings[key] = value
        
        # Defaults (only if no settings exist)
        if not mapped_settings:
            mapped_settings = {
                'two_factor_enabled': False,
                'login_max_attempts': 5,
                'login_lockout_duration': 30,
                'session_timeout': 3600,  # 60 minutes in seconds
                'password_min_length': 8,
                'password_require_uppercase': False,
                'password_require_lowercase': False,
                'password_require_numbers': False,
                'password_require_special': False,
                'ip_whitelist_enabled': False,
                'captcha_enabled': False
            }
        else:
            # Ensure all expected keys exist with defaults
            defaults = {
                'password_min_length': 8,
                'password_require_uppercase': False,
                'password_require_lowercase': False,
                'password_require_numbers': False,
                'password_require_special': False,
                'login_max_attempts': 5,
                'login_lockout_duration': 30,
                'session_timeout': 3600,
                'ip_whitelist_enabled': False,
                'captcha_enabled': False
            }
            for key, default_value in defaults.items():
                if key not in mapped_settings:
                    mapped_settings[key] = default_value
        
        return jsonify({'success': True, 'settings': mapped_settings}), 200
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings/security', methods=['PUT'])
@jwt_required()
def update_security_settings():
    """Update security settings"""
    try:
        data = request.get_json()
        print(f"[SECURITY SETTINGS UPDATE] Received {len(data)} settings to update: {list(data.keys())}")
        
        for key, value in data.items():
            # First, delete any duplicate rows for this key (keep only the most recent one)
            # This prevents accumulation of duplicate entries
            try:
                # Get the ID of the most recent row to keep
                keep_id_query = text("""
                    SELECT id FROM app_settings
                    WHERE category = 'security' AND setting_key = :key AND user_id IS NULL
                    ORDER BY updated_at DESC, id DESC
                    LIMIT 1
                """)
                keep_id_result = db.session.execute(keep_id_query, {'key': key}).fetchone()
                keep_id = keep_id_result[0] if keep_id_result else None
                
                if keep_id:
                    # Delete all other rows for this key
                    delete_duplicates_query = text("""
                        DELETE FROM app_settings
                        WHERE category = 'security' 
                        AND setting_key = :key 
                        AND user_id IS NULL
                        AND id != :keep_id
                    """)
                    deleted_count = db.session.execute(delete_duplicates_query, {'key': key, 'keep_id': keep_id}).rowcount
                    if deleted_count > 0:
                        print(f"[SECURITY SETTINGS UPDATE] Deleted {deleted_count} duplicate row(s) for key: {key}, keeping id: {keep_id}")
                        db.session.commit()
            except Exception as cleanup_err:
                db.session.rollback()
                print(f"[SECURITY SETTINGS UPDATE] Warning: Could not clean duplicates for {key}: {cleanup_err}")
            
            # Determine setting type
            if isinstance(value, bool):
                setting_type = 'boolean'
                value_str = str(value).lower()
            elif isinstance(value, (int, float)):
                setting_type = 'number'
                value_str = str(value)
            else:
                setting_type = 'string'
                value_str = str(value)
            
            print(f"[SECURITY SETTINGS UPDATE] Processing key: {key}, type: {setting_type}, value: {value_str}")
            
            # Check if row exists first (handle NULL user_id in unique constraint)
            # Security settings are global (user_id IS NULL)
            check_query = text("""
                SELECT id FROM app_settings 
                WHERE setting_key = :key AND category = 'security' AND user_id IS NULL
            """)
            existing = db.session.execute(check_query, {'key': key}).fetchone()
            
            if existing:
                # Update existing row
                print(f"[SECURITY SETTINGS UPDATE] Updating existing row for key: {key} with value: {value_str}")
                update_query = text("""
                    UPDATE app_settings 
                    SET setting_value = :value, 
                        setting_type = :type, 
                        updated_at = UTC_TIMESTAMP()
                    WHERE setting_key = :key AND category = 'security' AND user_id IS NULL
                """)
                db.session.execute(update_query, {'key': key, 'value': value_str, 'type': setting_type})
            else:
                # Insert new row
                print(f"[SECURITY SETTINGS UPDATE] Inserting new row for key: {key} with value: {value_str}")
                insert_query = text("""
                    INSERT INTO app_settings (setting_key, setting_value, setting_type, category, user_id, updated_at)
                    VALUES (:key, :value, :type, 'security', NULL, UTC_TIMESTAMP())
                """)
                db.session.execute(insert_query, {'key': key, 'value': value_str, 'type': setting_type})
        
        db.session.commit()
        print(f"[SECURITY SETTINGS UPDATE] ✅ Successfully updated {len(data)} settings in app_settings table")
        
        # Verify the update by reading back the values
        for key in data.keys():
            verify_value = get_security_setting(key)
            print(f"[SECURITY SETTINGS UPDATE] Verified {key} = {verify_value} (type: {type(verify_value).__name__})")
        
        return jsonify({'success': True, 'message': 'Security settings updated successfully'}), 200
    except Exception as e:
        db.session.rollback()
        print(f"[SECURITY SETTINGS UPDATE] ❌ Error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

