@app.route('/api/settings/email', methods=['GET'])
@jwt_required()
def get_email_settings():
    """Get MSG91 email settings"""
    try:
        query = text("""
            SELECT setting_key, setting_value, setting_type
            FROM app_settings
            WHERE category = 'email'
            ORDER BY updated_at DESC, id DESC
        """)
        result = db.session.execute(query).fetchall()
        
        # Group by key and take the most recent value for each key
        settings = {}
        seen_keys = set()
        for row in result:
            key = row[0]
            if key not in seen_keys:
                seen_keys.add(key)
                value = row[1]
                setting_type = row[2] if len(row) > 2 else 'string'
                
                # Convert based on setting_type
                if setting_type == 'boolean':
                    value = value.lower() in ('true', '1', 'yes')
                elif setting_type == 'number':
                    try:
                        value = float(value) if '.' in str(value) else int(value)
                    except ValueError:
                        pass
                
                settings[key] = value
        
        # Default values from environment variables if no settings found
        if not settings:
            settings = {
                'msg91_api_key': os.environ.get('MSG91_API_KEY', ''),
                'msg91_domain': os.environ.get('MSG91_DOMAIN', ''),
                'msg91_from_email': os.environ.get('MSG91_FROM_EMAIL', ''),
                'msg91_template_nda_signing': os.environ.get('MSG91_TEMPLATE_NDA_SIGNING', '')
            }
        
        return jsonify({'success': True, 'settings': settings}), 200
    except Exception as e:
        print(f"Error fetching email settings: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

