def get_msg91_template_id(email_type=None):
    """
    Get MSG91 template ID for email type
    
    Args:
        email_type: Email type - 'revenue_alert', 'test_email', 'password_reset', or 'nda_signing'
    
    Returns:
        str: Template ID from environment variable, or empty string if not configured
    """
    template_map = {
        'revenue_alert': os.environ.get('MSG91_TEMPLATE_REVENUE_ALERT', ''),
        'test_email': os.environ.get('MSG91_TEMPLATE_TEST_EMAIL', ''),
        'password_reset': os.environ.get('MSG91_TEMPLATE_PASSWORD_RESET', ''),
        'nda_signing': os.environ.get('MSG91_TEMPLATE_NDA_SIGNING', '')
    }
    
    if email_type and email_type in template_map:
        template_id = template_map[email_type]
    else:
        # Default to NDA template for backward compatibility
        template_id = template_map.get('nda_signing', '')
    
    if template_id:
        print(f"🔍 MSG91 Template ID for '{email_type}': '{template_id}'")
    else:
        print(f"⚠️ MSG91 Template ID for '{email_type}' not configured in environment variables")
    
    return template_id

def send_email(to_email, subject, html_body, text_body=None, template_id=None, variables=None):
    """Send email using MSG91 API"""
    try:
        # Always use MSG91 API for email sending
        return send_email_msg91(to_email, subject, html_body, text_body, template_id, variables)
    except Exception as e:
        print(f"[EMAIL] Error in send_email: {str(e)}")
        import traceback
        traceback.print_exc()
        return False

def send_email_msg91(to_email, subject, html_body, text_body=None, template_id=None, variables=None):
    """
    Send email using MSG91 API (simplified - only uses NDA template)
    
    Args:
        to_email: Recipient email address (string or list of strings)
        subject: Email subject (required for non-template emails)
        html_body: HTML email body (optional, for raw emails)
        text_body: Plain text email body (optional, for raw emails)
        template_id: Template ID if using MSG91 template (optional, defaults to NDA template if 'nda' in subject)
        variables: Dictionary of template variables if using templates (optional)
    
    Returns:
        bool: True if email sent successfully, False otherwise
    """
    try:
        # Get MSG91 credentials from environment variables
        msg91_api_key = os.environ.get('MSG91_API_KEY')
        msg91_domain = os.environ.get('MSG91_DOMAIN')
        msg91_from_email = os.environ.get('MSG91_FROM_EMAIL')
        
        if not msg91_api_key:
            print("[EMAIL] MSG91_API_KEY not configured in environment variables")
            return False
        
        if not msg91_domain:
            print("[EMAIL] MSG91_DOMAIN not configured in environment variables")
            return False
        
        # Use configured from_email or construct from MSG91 domain
        sender_email = msg91_from_email or f"no-reply@{msg91_domain}"
        # Ensure sender email uses MSG91 domain
        if '@' in sender_email and not sender_email.endswith(f'@{msg91_domain}'):
            sender_email = f"no-reply@{msg91_domain}"
        
        # MSG91 Email API endpoint (v5 API)
        msg91_url = "https://control.msg91.com/api/v5/email/send"
        
        # Determine if we should use template_id or body format
        use_template = False
        final_template_id = None
        
        # Convert to_email to proper format
        if isinstance(to_email, str):
            recipients_list = [{"to": [{"email": to_email, "name": ""}]}]
        elif isinstance(to_email, list):
            if len(to_email) > 0 and isinstance(to_email[0], dict):
                if "to" in to_email[0]:
                    recipients_list = to_email
                else:
                    recipients_list = [{"to": [{"email": item.get("email", ""), "name": item.get("name", "")} for item in to_email]}]
            else:
                recipients_list = [{"to": [{"email": email, "name": ""} for email in to_email]}]
        else:
            print("[EMAIL] Invalid recipient format")
            return False
        
        # Determine which template to use
        final_template_id = None
        
        # Check if template_id is provided explicitly
        if template_id:
            final_template_id = str(template_id).strip()
        else:
            # Try to detect email type from subject or use default
            subject_lower = (subject or '').lower()
            if 'revenue' in subject_lower or 'alert' in subject_lower:
                final_template_id = get_msg91_template_id('revenue_alert')
            elif 'test' in subject_lower and 'email' in subject_lower:
                final_template_id = get_msg91_template_id('test_email')
            elif 'password' in subject_lower or 'reset' in subject_lower:
                final_template_id = get_msg91_template_id('password_reset')
            else:
                # Default to NDA template for backward compatibility
                final_template_id = get_msg91_template_id('nda_signing')
        
        if not final_template_id:
            print("[EMAIL] MSG91 template ID not configured")
            return False
        
        # Add variables to recipients BEFORE creating payload
        # If no variables provided, use empty dict or default variables
        if not variables:
            variables = {}
        
        for recipient in recipients_list:
            recipient["variables"] = variables
        
        # Prepare email data according to MSG91 API format
        payload = {
            "recipients": recipients_list,
            "from": {
                "email": sender_email
            },
            "domain": msg91_domain,
            "template_id": final_template_id
        }
        
        print(f"✅ Using MSG91 template: '{final_template_id}'")
        print(f"📧 Email Subject: '{subject}'")
        print(f"📧 Template ID provided explicitly: {template_id is not None}")
        print(f"📧 Variables provided: {variables is not None and len(variables) > 0}")
        
        # Prepare headers (MSG91 uses 'authkey' header)
        headers = {
            "Accept": "application/json",
            "Content-Type": "application/json",
            "authkey": msg91_api_key
        }
        
        # Debug logging - always log the full payload for troubleshooting
        import json
        print(f"🔍 MSG91 API URL: {msg91_url}")
        print(f"🔍 MSG91 Payload: {json.dumps(payload, indent=2)}")
        print(f"🔍 MSG91 Headers: {json.dumps({k: v if k != 'authkey' else '***REDACTED***' for k, v in headers.items()}, indent=2)}")
        if final_template_id:
            print(f"🔍 Template ID: '{final_template_id}'")
        if variables:
            print(f"🔍 Template Variables ({len(variables)} variables): {json.dumps(variables, indent=2)}")
        else:
            print(f"⚠️ No template variables provided - template may not render correctly")
        
        # Make API request
        print(f"[EMAIL] Sending request to MSG91 API...")
        print(f"[EMAIL] Request URL: {msg91_url}")
        try:
            response = requests.post(msg91_url, json=payload, headers=headers, timeout=30)
        except requests.exceptions.RequestException as req_err:
            print(f"[EMAIL] ❌ Request failed: {str(req_err)}")
            import traceback
            traceback.print_exc()
            return False
        
        # Log response for debugging
        print(f"[EMAIL] MSG91 API Response Status: {response.status_code}")
        print(f"[EMAIL] MSG91 API Response Headers: {dict(response.headers)}")
        print(f"[EMAIL] MSG91 API Response Body: {response.text}")
        
        if response.status_code in [200, 201, 202]:
            try:
                response_data = response.json()
                if (response_data.get('status') in ['success', 'sent', 'ok', 'queued'] or 
                    response_data.get('success') == True or
                    response_data.get('type') == 'success' or
                    (response_data.get('message') and 'success' in str(response_data.get('message', '')).lower())):
                    recipient_emails = []
                    for rec in recipients_list:
                        for to_item in rec.get('to', []):
                            recipient_emails.append(to_item.get('email', ''))
                    print(f"✅ MSG91 email sent successfully to {', '.join(recipient_emails)}")
                    print(f"📧 Template used: '{final_template_id}'")
                    return True
                else:
                    error_msg = response_data.get('message', response_data.get('error', 'Unknown error'))
                    print(f"❌ MSG91 API error: {error_msg}")
                    print(f"📧 Template attempted: '{final_template_id}'")
                    print(f"Response: {response_data}")
                    # Check for common template-related errors
                    if 'template' in str(error_msg).lower() or 'template' in str(response_data).lower():
                        print(f"⚠️ Template-related error detected. Check:")
                        print(f"   1. Template ID '{final_template_id}' exists in MSG91")
                        print(f"   2. Template is approved (not in Draft status)")
                        print(f"   3. Template ID matches exactly (case-sensitive)")
                    return False
            except Exception as parse_error:
                print(f"⚠️ Could not parse MSG91 response as JSON: {parse_error}")
                if response.status_code in [200, 201, 202]:
                    print(f"✅ MSG91 email sent (HTTP {response.status_code})")
                    return True
                return False
        else:
            try:
                error_data = response.json()
                error_msg = error_data.get('message', f"HTTP {response.status_code}")
                if 'errors' in error_data:
                    print(f"[EMAIL] MSG91 Validation errors: {error_data.get('errors')}")
            except:
                error_msg = f"HTTP {response.status_code}: {response.text}"
            print(f"❌ MSG91 API request failed: {error_msg}")
            return False
            
    except requests.exceptions.RequestException as e:
        print(f"[EMAIL] ❌ MSG91 API request exception: {str(e)}")
        import traceback
        traceback.print_exc()
        return False
    except Exception as e:
        print(f"[EMAIL] ❌ Error sending email via MSG91: {str(e)}")
        import traceback
        traceback.print_exc()
        return False

@app.route('/api/settings/security/login-attempts', methods=['GET'])
@jwt_required()
def get_login_attempts():
    """Get login attempts history"""
    try:
        # Initialize analytics tables if they don't exist (ensures audit_logs table exists)
        try:
            init_analytics_tables()
        except Exception as init_err:
            print(f"[WARNING] Could not initialize analytics tables: {init_err}")
        
        # Check if audit_logs table exists and has required columns
        try:
            # First, check if user_id column exists, if not add it
            check_col_query = text("""
                SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS 
                WHERE TABLE_SCHEMA = DATABASE() 
                AND TABLE_NAME = 'audit_logs' 
                AND COLUMN_NAME = 'user_id'
            """)
            has_user_id = db.session.execute(check_col_query).scalar() > 0
            
            if not has_user_id:
                try:
                    db.session.execute(text("ALTER TABLE audit_logs ADD COLUMN user_id VARCHAR(100) AFTER actor_type"))
                    db.session.commit()
                except Exception as alter_err:
                    db.session.rollback()
            
            # Force fresh query - no caching, no time limits, get all login attempts
            # Get latest 50 records to ensure we have a good mix of both success and failed
            # Then we'll return the latest 20 to frontend
            query = text("""
                SELECT action_type, user_id, ip_address, timestamp, notes
                FROM audit_logs
                WHERE action_type IN ('LOGIN_SUCCESS', 'LOGIN_ATTEMPT_FAILED')
                ORDER BY timestamp DESC
                LIMIT 50
            """)
            result = db.session.execute(query).fetchall()
            
            print(f"[LOGIN ATTEMPTS] Found {len(result)} login attempt records in audit_logs")
            
            attempts = []
            for row in result:
                timestamp_str = None
                timestamp_dt = None
                if row[3]:
                    try:
                        from datetime import datetime, timezone
                        # Convert datetime to ISO format if it's a datetime object
                        if isinstance(row[3], datetime):
                            # Make timezone-aware for consistent handling
                            if row[3].tzinfo is None:
                                timestamp_dt = row[3].replace(tzinfo=timezone.utc)
                            else:
                                timestamp_dt = row[3]
                            timestamp_str = timestamp_dt.isoformat()
                        elif isinstance(row[3], str):
                            # Try to parse string timestamp
                            try:
                                timestamp_dt = datetime.fromisoformat(row[3].replace('Z', '+00:00'))
                                if timestamp_dt.tzinfo is None:
                                    timestamp_dt = timestamp_dt.replace(tzinfo=timezone.utc)
                                timestamp_str = timestamp_dt.isoformat()
                            except:
                                timestamp_str = str(row[3])
                        else:
                            timestamp_str = str(row[3])
                    except Exception as ts_err:
                        print(f"[LOGIN ATTEMPTS] Error processing timestamp: {ts_err}")
                        timestamp_str = str(row[3]) if row[3] else None
                
                # Map action_type to status for frontend (use lowercase to match frontend check)
                is_success = row[0] == 'LOGIN_SUCCESS'
                status = 'success' if is_success else 'failed'
                
                # Extract username/email from user_id or notes
                username_email = row[1] if row[1] and str(row[1]).strip() and str(row[1]) != 'Unknown' else None
                
                # Try to extract from notes if user_id is missing or Unknown
                if not username_email or username_email == 'Unknown' or (isinstance(username_email, str) and 'admin_' in username_email):
                    if row[4]:
                        notes_str = str(row[4])
                        if 'Failed login attempt for' in notes_str:
                            # Extract username from notes: "Failed login attempt for {username} from {ip}"
                            try:
                                notes_parts = notes_str.split('Failed login attempt for ')
                                if len(notes_parts) > 1:
                                    username_from_notes = notes_parts[1].split(' from ')[0].strip()
                                    if username_from_notes:
                                        username_email = username_from_notes
                            except Exception as e:
                                print(f"[LOGIN ATTEMPTS] Error extracting username from notes: {e}")
                        elif 'Admin login from' in notes_str or 'login from' in notes_str.lower():
                            # For successful logins, extract from user_id (format: admin_1)
                            if row[1] and 'admin_' in str(row[1]):
                                try:
                                    admin_id = str(row[1]).replace('admin_', '').strip()
                                    if admin_id.isdigit():
                                        # Try to get admin username/email from admin_users table
                                        admin_query = text("SELECT username, email, full_name FROM admin_users WHERE id = :admin_id LIMIT 1")
                                        admin_result = db.session.execute(admin_query, {'admin_id': int(admin_id)}).fetchone()
                                        if admin_result:
                                            username_email = admin_result[0] or admin_result[1] or admin_result[2] or username_email
                                except Exception as e:
                                    print(f"[LOGIN ATTEMPTS] Error fetching admin user: {e}")
                
                # Fallback to Unknown if still no username
                if not username_email or username_email == 'Unknown':
                    username_email = 'Unknown'
                else:
                    # Clean up username_email (remove any None values)
                    username_email = str(username_email).strip()
                    if not username_email or username_email == 'None':
                        username_email = 'Unknown'
                
                # Clean up IP address
                ip_address = row[2] if row[2] else 'Unknown'
                if not ip_address or ip_address == 'None':
                    ip_address = 'Unknown'
                
                attempts.append({
                    'action': row[0],
                    'status': status,  # lowercase to match frontend
                    'success': is_success,  # boolean for frontend compatibility
                    'username': username_email,
                    'email': username_email,
                    'user_id': row[1] if row[1] else None,
                    'ip_address': ip_address,
                    'timestamp': timestamp_str,
                    'notes': row[4] if row[4] else None
                })
            
            print(f"[LOGIN ATTEMPTS] Processed {len(attempts)} login attempts")
            success_count = sum(1 for a in attempts if a.get('success') or a.get('status') == 'success')
            failed_count = len(attempts) - success_count
            print(f"[LOGIN ATTEMPTS] Success: {success_count}, Failed: {failed_count}")
            
            # Return latest 20 attempts (to ensure good mix of both success and failed)
            # The attempts are already sorted by timestamp DESC, so we just take first 20
            latest_attempts = attempts[:20]
            
            latest_success = sum(1 for a in latest_attempts if a.get('success'))
            latest_failed = len(latest_attempts) - latest_success
            print(f"[LOGIN ATTEMPTS] Returning latest {len(latest_attempts)} attempts: {latest_success} success, {latest_failed} failed")
            
            # Set no-cache headers to ensure fresh data
            response = jsonify({
                'success': True, 
                'attempts': latest_attempts,  # Return only latest 20
                'total': len(attempts),  # Total in database
                'returned': len(latest_attempts),  # Number being returned
                'success_count': latest_success,
                'failed_count': latest_failed
            })
            response.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
            response.headers['Pragma'] = 'no-cache'
            response.headers['Expires'] = '0'
            return response, 200
        except Exception as query_err:
            # Table might not exist - return empty array
            print(f"[WARNING] Could not query audit_logs table: {query_err}")
            import traceback
            traceback.print_exc()
            return jsonify({'success': True, 'attempts': [], 'warning': str(query_err)}), 200
    except Exception as e:
        print(f"[ERROR] Error in get_login_attempts: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e), 'attempts': []}), 500

@app.route('/api/settings/notifications', methods=['GET'])
@jwt_required()
def get_notification_settings():
    """Get notification preferences from notification_preferences table"""
    try:
        current_user_id = get_jwt_identity()
        # Extract admin ID from JWT identity
        admin_id = None
        if isinstance(current_user_id, str) and current_user_id.startswith('admin_'):
            admin_id = int(current_user_id.replace('admin_', ''))
        elif isinstance(current_user_id, int):
            admin_id = current_user_id
        
        if not admin_id:
            return jsonify({'success': False, 'error': 'Invalid user'}), 401
        
        # Get notification preferences from notification_preferences table
        query = text("""
            SELECT notification_type, is_enabled
            FROM notification_preferences
            WHERE user_id = :user_id
        """)
        result = db.session.execute(query, {'user_id': admin_id}).fetchall()
        
        # Build preferences object
        preferences = {}
        for row in result:
            notification_type = row[0]
            is_enabled = bool(row[1]) if row[1] is not None else True
            preferences[notification_type] = is_enabled
        
        # Define grouped notification types - one toggle per resource type controls all CRUD operations
        # When a group is enabled, all CRUD operations for that resource are enabled
        all_notification_types = {
            'product_operations': {
                'label': 'Product Operations',
                'description': 'Receive notifications for product creation, updates, and deletions.',
                'default': True
            },
            'order_operations': {
                'label': 'Order Operations',
                'description': 'Receive notifications for new orders, order updates, cancellations, and payment receipts.',
                'default': True
            },
            'coupon_operations': {
                'label': 'Coupon Operations',
                'description': 'Receive notifications for coupon creation, updates, and deletions.',
                'default': True
            },
            'payment_operations': {
                'label': 'Payment Operations',
                'description': 'Receive notifications for payment gateway updates and payment processing.',
                'default': True
            },
            'reward_operations': {
                'label': 'Reward Operations',
                'description': 'Receive notifications for reward points adjustments and earnings.',
                'default': True
            },
            'revenue_alerts': {
                'label': 'Revenue Alerts',
                'description': 'Receive alerts for revenue targets and milestones.',
                'default': True
            },
            'email_operations': {
                'label': 'Email Operations',
                'description': 'Receive notifications for emails sent and email delivery failures.',
                'default': True
            },
            'system_operations': {
                'label': 'System Operations',
                'description': 'Receive critical system alerts and inventory notifications.',
                'default': True
            },
            'customer_operations': {
                'label': 'Customer Operations',
                'description': 'Receive notifications for new customer registrations and profile updates.',
                'default': True
            }
        }
        
        # Merge fetched preferences with default/all types
        final_preferences = {}
        for type_key, type_info in all_notification_types.items():
            final_preferences[type_key] = preferences.get(type_key, type_info['default'])
        
        return jsonify({
            'success': True, 
            'preferences': final_preferences,
            'available_types': all_notification_types
        }), 200
    except Exception as e:
        print(f"[ERROR] Error getting notification settings: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings/notifications', methods=['PUT'])
@jwt_required()
def update_notification_settings():
    """Update notification preferences in notification_preferences table"""
    try:
        current_user_id = get_jwt_identity()
        # Extract admin ID from JWT identity
        admin_id = None
        if isinstance(current_user_id, str) and current_user_id.startswith('admin_'):
            admin_id = int(current_user_id.replace('admin_', ''))
        elif isinstance(current_user_id, int):
            admin_id = current_user_id
        
        if not admin_id:
            return jsonify({'success': False, 'error': 'Invalid user'}), 401
        
        data = request.get_json()
        preferences_data = data.get('preferences', {})
        
        print(f"[NOTIFICATION PREFERENCES UPDATE] Received request from admin {admin_id}")
        print(f"[NOTIFICATION PREFERENCES UPDATE] Preferences data: {preferences_data}")
        
        if not preferences_data:
            return jsonify({'success': False, 'error': 'No preferences provided'}), 400
        
        # Ensure notification_preferences table has unique constraint on (user_id, notification_type)
        try:
            # Check if unique constraint exists
            check_constraint_query = text("""
                SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS 
                WHERE TABLE_SCHEMA = DATABASE() 
                AND TABLE_NAME = 'notification_preferences' 
                AND CONSTRAINT_TYPE = 'UNIQUE'
                AND CONSTRAINT_NAME LIKE '%user_id%notification_type%'
            """)
            has_constraint = db.session.execute(check_constraint_query).scalar() > 0
            
            if not has_constraint:
                print("[NOTIFICATION PREFERENCES] Adding unique constraint on (user_id, notification_type)...")
                # Try to add unique constraint
                try:
                    add_constraint_query = text("""
                        ALTER TABLE notification_preferences 
                        ADD UNIQUE KEY unique_user_notification (user_id, notification_type)
                    """)
                    db.session.execute(add_constraint_query)
                    db.session.commit()
                    print("[NOTIFICATION PREFERENCES] ✅ Added unique constraint")
                except Exception as constraint_err:
                    print(f"[NOTIFICATION PREFERENCES] Could not add constraint (may already exist): {constraint_err}")
                    db.session.rollback()
        except Exception as check_err:
            print(f"[NOTIFICATION PREFERENCES] Error checking constraint: {check_err}")
            db.session.rollback()
        
        # Update or insert each notification preference
        saved_count = 0
        for notification_type, is_enabled in preferences_data.items():
            # Convert boolean to int for database
            is_enabled_int = 1 if is_enabled else 0
            
            print(f"[NOTIFICATION PREFERENCES UPDATE] Saving: {notification_type} = {is_enabled} (int: {is_enabled_int})")
            
            try:
                upsert_query = text("""
                    INSERT INTO notification_preferences (user_id, notification_type, is_enabled, created_at, updated_at)
                    VALUES (:user_id, :notification_type, :is_enabled, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                    ON DUPLICATE KEY UPDATE 
                        is_enabled = :is_enabled,
                        updated_at = UTC_TIMESTAMP()
                """)
                result = db.session.execute(upsert_query, {
                    'user_id': admin_id,
                    'notification_type': notification_type,
                    'is_enabled': is_enabled_int
                })
                saved_count += 1
                print(f"[NOTIFICATION PREFERENCES UPDATE] ✅ Saved {notification_type} for user {admin_id}")
            except Exception as save_err:
                print(f"[NOTIFICATION PREFERENCES UPDATE] ❌ Error saving {notification_type}: {save_err}")
                import traceback
                traceback.print_exc()
                db.session.rollback()
                # Try without ON DUPLICATE KEY UPDATE (in case constraint doesn't exist)
                try:
                    # First try to delete existing
                    delete_query = text("""
                        DELETE FROM notification_preferences 
                        WHERE user_id = :user_id AND notification_type = :notification_type
                    """)
                    db.session.execute(delete_query, {
                        'user_id': admin_id,
                        'notification_type': notification_type
                    })
                    # Then insert
                    insert_query = text("""
                        INSERT INTO notification_preferences (user_id, notification_type, is_enabled, created_at, updated_at)
                        VALUES (:user_id, :notification_type, :is_enabled, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                    """)
                    db.session.execute(insert_query, {
                        'user_id': admin_id,
                        'notification_type': notification_type,
                        'is_enabled': is_enabled_int
                    })
                    saved_count += 1
                    print(f"[NOTIFICATION PREFERENCES UPDATE] ✅ Saved {notification_type} (using delete+insert method)")
                except Exception as retry_err:
                    print(f"[NOTIFICATION PREFERENCES UPDATE] ❌ Failed to save {notification_type} even with retry: {retry_err}")
                    db.session.rollback()
        
        print(f"[NOTIFICATION PREFERENCES UPDATE] Committing {saved_count} preferences...")
        db.session.commit()
        print(f"[NOTIFICATION PREFERENCES UPDATE] ✅ Successfully saved {saved_count} preferences")
        
        # Return updated preferences
        query = text("""
            SELECT notification_type, is_enabled
            FROM notification_preferences
            WHERE user_id = :user_id
        """)
        result = db.session.execute(query, {'user_id': admin_id}).fetchall()
        
        updated_preferences = {}
        for row in result:
            updated_preferences[row[0]] = bool(row[1])
        
        return jsonify({
            'success': True, 
            'message': 'Notification preferences updated successfully',
            'preferences': updated_preferences
        }), 200
    except Exception as e:
        db.session.rollback()
        print(f"[ERROR] Error updating notification settings: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings/payment-gateways', methods=['GET'])
@jwt_required()
def get_payment_gateways():
    """Get all payment gateways"""
    try:
        # Verify database connection and current database
        try:
            db_info_query = text("SELECT DATABASE() as current_db, USER() as `current_user`, @@hostname as hostname")
            db_info = db.session.execute(db_info_query).fetchone()
            if db_info:
                print(f"[PAYMENT GATEWAYS GET] 🔍 Database Info: DB={db_info[0]}, User={db_info[1]}, Host={db_info[2]}")
            else:
                print("[PAYMENT GATEWAYS GET] ⚠️ Could not get database info")
        except Exception as db_info_err:
            print(f"[PAYMENT GATEWAYS GET] ⚠️ Error getting database info: {db_info_err}")
        
        # Ensure table exists and default gateways are initialized
        init_analytics_tables()
        
        # ALWAYS ensure default gateways exist (use INSERT IGNORE to handle duplicates)
        print("[PAYMENT GATEWAYS GET] Ensuring default gateways exist...")
        
        # Always try to insert defaults (INSERT IGNORE will skip if they exist)
        default_gateways = [
            {'gateway_code': 'razorpay', 'gateway_name': 'Razorpay', 'mode': 'test', 'currency': 'INR', 'is_enabled': False},
            {'gateway_code': 'stripe', 'gateway_name': 'Stripe', 'mode': 'test', 'currency': 'USD', 'is_enabled': False},
            {'gateway_code': 'paypal', 'gateway_name': 'PayPal', 'mode': 'test', 'currency': 'USD', 'is_enabled': False},
            {'gateway_code': 'phonepe', 'gateway_name': 'PhonePe', 'mode': 'test', 'currency': 'INR', 'is_enabled': False}
        ]
        
        inserted = 0
        for gateway in default_gateways:
            try:
                # Use INSERT IGNORE to avoid errors if somehow exists
                insert_query = text("""
                    INSERT IGNORE INTO payment_gateways 
                    (gateway_code, gateway_name, mode, currency, is_enabled, created_at, updated_at)
                    VALUES 
                    (:gateway_code, :gateway_name, :mode, :currency, :is_enabled, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                """)
                result = db.session.execute(insert_query, gateway)
                if result.rowcount > 0:
                    inserted += 1
                    print(f"[PAYMENT GATEWAYS GET] ✅ Inserted {gateway['gateway_name']}")
            except Exception as insert_err:
                print(f"[PAYMENT GATEWAYS GET] ⚠️ Could not insert {gateway['gateway_code']}: {insert_err}")
                import traceback
                traceback.print_exc()
                continue
        
        if inserted > 0:
            db.session.commit()
            db.session.flush()  # Ensure changes are visible
            print(f"[PAYMENT GATEWAYS GET] ✅ Successfully initialized {inserted} default payment gateways")
        else:
            print(f"[PAYMENT GATEWAYS GET] ℹ️ All default gateways already exist")
            db.session.commit()  # Commit anyway to ensure consistency
        
        # Now query for all gateways
        count_query = text("SELECT COUNT(*) FROM payment_gateways")
        gateway_count = db.session.execute(count_query).scalar() or 0
        print(f"[PAYMENT GATEWAYS GET] Current gateway count after initialization: {gateway_count}")
        
        if gateway_count == 0:
            print("[PAYMENT GATEWAYS GET] ⚠️ No gateways found, initializing defaults immediately...")
            default_gateways = [
                {'gateway_code': 'razorpay', 'gateway_name': 'Razorpay', 'mode': 'test', 'currency': 'INR', 'is_enabled': False},
                {'gateway_code': 'stripe', 'gateway_name': 'Stripe', 'mode': 'test', 'currency': 'USD', 'is_enabled': False},
                {'gateway_code': 'paypal', 'gateway_name': 'PayPal', 'mode': 'test', 'currency': 'USD', 'is_enabled': False},
                {'gateway_code': 'phonepe', 'gateway_name': 'PhonePe', 'mode': 'test', 'currency': 'INR', 'is_enabled': False}
            ]
            
            inserted = 0
            for gateway in default_gateways:
                try:
                    # Use INSERT IGNORE to avoid errors if somehow exists
                    insert_query = text("""
                        INSERT IGNORE INTO payment_gateways 
                        (gateway_code, gateway_name, mode, currency, is_enabled, created_at, updated_at)
                        VALUES 
                        (:gateway_code, :gateway_name, :mode, :currency, :is_enabled, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                    """)
                    result = db.session.execute(insert_query, gateway)
                    if result.rowcount > 0:
                        inserted += 1
                        print(f"[PAYMENT GATEWAYS GET] ✅ Inserted {gateway['gateway_name']}")
                except Exception as insert_err:
                    print(f"[PAYMENT GATEWAYS GET] ⚠️ Could not insert {gateway['gateway_code']}: {insert_err}")
                    import traceback
                    traceback.print_exc()
                    continue
            
            if inserted > 0:
                db.session.commit()
                db.session.flush()  # Ensure changes are visible
                print(f"[PAYMENT GATEWAYS GET] ✅ Successfully initialized {inserted} default payment gateways")
            else:
                print(f"[PAYMENT GATEWAYS GET] ⚠️ No gateways were inserted (may already exist)")
                # Don't rollback - gateways might already exist
                # But still commit to ensure any pending changes are saved
                db.session.commit()
        
        # Re-query to get fresh data (including any just inserted)
        # Use a fresh query to ensure we see committed data
        db.session.expire_all()  # Expire all cached objects
        
        # First, check what columns actually exist in the table
        try:
            columns_check = text("""
                SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS 
                WHERE TABLE_SCHEMA = DATABASE() 
                AND TABLE_NAME = 'payment_gateways'
                ORDER BY ORDINAL_POSITION
            """)
            existing_columns = [row[0] for row in db.session.execute(columns_check).fetchall()]
            print(f"[PAYMENT GATEWAYS GET] Table columns: {existing_columns}")
        except Exception as col_check_err:
            print(f"[PAYMENT GATEWAYS GET] Could not check columns: {col_check_err}")
            existing_columns = []
        
        # Build query based on available columns (webhook_url might not exist)
        # Also check for created_at and updated_at
        select_columns = ['gateway_code', 'gateway_name', 'mode', 'currency', 'is_enabled', 'api_key_public', 'merchant_id']
        
        # Add optional columns if they exist
        if 'webhook_url' in existing_columns:
            select_columns.append('webhook_url')
        else:
            select_columns.append('NULL as webhook_url')
            
        if 'created_at' in existing_columns:
            select_columns.append('created_at')
        else:
            select_columns.append('NULL as created_at')
            
        if 'updated_at' in existing_columns:
            select_columns.append('updated_at')
        else:
            select_columns.append('NULL as updated_at')
        
        query_sql = f"""
            SELECT {', '.join(select_columns)}
            FROM payment_gateways
            ORDER BY gateway_name ASC
        """
        
        print(f"[PAYMENT GATEWAYS GET] Executing query: {query_sql}")
        query = text(query_sql)
        try:
            result = db.session.execute(query).fetchall()
            print(f"[PAYMENT GATEWAYS GET] Query executed successfully, returned {len(result)} rows")
            # Log each row's gateway_code to see what we got
            for idx, row in enumerate(result):
                if len(row) > 0:
                    print(f"[PAYMENT GATEWAYS GET] Row {idx}: gateway_code={row[0]}, gateway_name={row[1] if len(row) > 1 else 'N/A'}")
        except Exception as query_err:
            print(f"[PAYMENT GATEWAYS GET] ❌ Query failed: {query_err}")
            import traceback
            traceback.print_exc()
            # Try a simpler query as fallback
            print("[PAYMENT GATEWAYS GET] Trying simpler fallback query...")
            fallback_query = text("SELECT gateway_code, gateway_name, mode, currency, is_enabled, api_key_public, merchant_id FROM payment_gateways ORDER BY gateway_name ASC")
            result = db.session.execute(fallback_query).fetchall()
            print(f"[PAYMENT GATEWAYS GET] Fallback query returned {len(result)} rows")
        
        # Also do a direct count to verify
        count_query = text("SELECT COUNT(*) FROM payment_gateways")
        total_count = db.session.execute(count_query).scalar() or 0
        print(f"[PAYMENT GATEWAYS GET] Direct COUNT query shows {total_count} total gateways in table")
        
        # Check specifically for the "test" gateway
        test_gateway_query = text("SELECT gateway_code, gateway_name FROM payment_gateways WHERE gateway_code = 'test' OR gateway_name LIKE '%test%' OR gateway_name LIKE '%tst%'")
        test_gateway = db.session.execute(test_gateway_query).fetchall()
        print(f"[PAYMENT GATEWAYS GET] Test gateway check: {test_gateway}")
        
        # List ALL gateway codes in the table
        all_codes_query = text("SELECT id, gateway_code, gateway_name FROM payment_gateways ORDER BY id ASC")
        all_codes_result = db.session.execute(all_codes_query).fetchall()
        print(f"[PAYMENT GATEWAYS GET] All gateways by ID: {[(row[0], row[1], row[2]) for row in all_codes_result]}")
        
        # If still empty after initialization, try one more time with direct insert
        if len(result) == 0:
            print("[PAYMENT GATEWAYS GET] ⚠️ Still no gateways found after initialization, forcing insert...")
            try:
                # First, verify table exists and check its structure
                table_check = text("SHOW TABLES LIKE 'payment_gateways'")
                table_exists = db.session.execute(table_check).fetchone()
                print(f"[PAYMENT GATEWAYS GET] Table exists check: {table_exists}")
                
                # Check current count again
                count_check = text("SELECT COUNT(*) FROM payment_gateways")
                current_count = db.session.execute(count_check).scalar() or 0
                print(f"[PAYMENT GATEWAYS GET] Current count before force insert: {current_count}")
                
                force_insert = text("""
                    INSERT IGNORE INTO payment_gateways 
                    (gateway_code, gateway_name, mode, currency, is_enabled, created_at, updated_at)
                    VALUES 
                    ('razorpay', 'Razorpay', 'test', 'INR', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
                    ('stripe', 'Stripe', 'test', 'USD', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
                    ('paypal', 'PayPal', 'test', 'USD', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
                    ('phonepe', 'PhonePe', 'test', 'INR', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                """)
                insert_result = db.session.execute(force_insert)
                db.session.commit()
                db.session.flush()
                print(f"[PAYMENT GATEWAYS GET] ✅ Force insert executed, rowcount: {insert_result.rowcount}")
                
                # Wait a tiny bit and re-query after force insert
                import time
                time.sleep(0.1)  # Small delay to ensure DB commit is visible
                db.session.expire_all()
                result = db.session.execute(query).fetchall()
                print(f"[PAYMENT GATEWAYS GET] After force insert, query returned {len(result)} rows")
            except Exception as force_err:
                print(f"[PAYMENT GATEWAYS GET] ⚠️ Force insert failed: {force_err}")
                import traceback
                traceback.print_exc()
                db.session.rollback()
        
        print(f"[PAYMENT GATEWAYS GET] Query returned {len(result)} rows")
        
        # Log all gateway codes found in database (simple query to verify count)
        try:
            all_codes_query = text("SELECT gateway_code, gateway_name FROM payment_gateways ORDER BY gateway_name ASC")
            all_codes = db.session.execute(all_codes_query).fetchall()
            gateway_list = [f"{code[1] or 'NULL'} ({code[0] or 'NULL'})" for code in all_codes]
            print(f"[PAYMENT GATEWAYS GET] All gateways in DB (simple query): {gateway_list}")
            print(f"[PAYMENT GATEWAYS GET] Simple query returned {len(all_codes)} rows")
        except Exception as simple_err:
            print(f"[PAYMENT GATEWAYS GET] ⚠️ Simple query failed: {simple_err}")
            all_codes = []
        
        gateways = []
        seen_codes = set()  # Track duplicates
        for idx, row in enumerate(result):
            try:
                # Handle variable row length based on available columns
                gateway_code = row[0] if len(row) > 0 and row[0] else None
                gateway_name = (row[1] if len(row) > 1 and row[1] else None) or gateway_code or f'Unknown_{idx}'
                
                if not gateway_code:
                    print(f"[PAYMENT GATEWAYS GET] ⚠️ Skipping row {idx}: missing gateway_code, row={row}")
                    continue
                
                # Check for duplicate gateway_code
                if gateway_code in seen_codes:
                    print(f"[PAYMENT GATEWAYS GET] ⚠️ Skipping duplicate gateway_code: {gateway_code}")
                    continue
                seen_codes.add(gateway_code)
                
                # Safely extract values with defaults - handle variable column count
                gateway = {
                    'gateway_code': gateway_code,
                    'gateway_name': gateway_name,
                    'name': gateway_name,  # Alias for compatibility
                    'mode': (row[2] if len(row) > 2 and row[2] else None) or 'test',
                    'currency': (row[3] if len(row) > 3 and row[3] else None) or 'USD',
                    'is_enabled': bool(row[4] if len(row) > 4 else False),
                    'status': 'active' if bool(row[4] if len(row) > 4 else False) else 'inactive',
                    'api_key_public': (row[5] if len(row) > 5 and row[5] else None) or '',
                    'merchant_id': (row[6] if len(row) > 6 and row[6] else None) or '',
                    'webhook_url': (row[7] if len(row) > 7 and row[7] else None) or '',
                    'created_at': row[8].isoformat() if len(row) > 8 and row[8] else None,
                    'updated_at': row[9].isoformat() if len(row) > 9 and row[9] else None,
                    'configured': bool(row[5] if len(row) > 5 and row[5] else False)  # Has API key configured
                }
                gateways.append(gateway)
                print(f"[PAYMENT GATEWAYS GET] ✅ Added gateway: {gateway['gateway_name']} ({gateway['gateway_code']})")
            except Exception as row_err:
                print(f"[PAYMENT GATEWAYS GET] ⚠️ Error processing row {idx}: {row_err}")
                print(f"[PAYMENT GATEWAYS GET] Row data: {row}")
                import traceback
                traceback.print_exc()
                continue
        
        print(f"[PAYMENT GATEWAYS GET] ✅ Returning {len(gateways)} gateways to frontend (DB COUNT={total_count}, simple query={len(all_codes)}, main query={len(result)})")
        return jsonify({'success': True, 'gateways': gateways}), 200
    except Exception as e:
        print(f"[PAYMENT GATEWAYS] Error fetching gateways: {str(e)}")
        import traceback
        traceback.print_exc()
        # Return empty list if table doesn't exist
        return jsonify({'success': True, 'gateways': []}), 200

@app.route('/api/payments/gateways/<gateway_code>', methods=['GET'])
@jwt_required()
def get_payment_gateway(gateway_code):
    """Get a single payment gateway by code"""
    try:
        init_analytics_tables()
        
        query = text("""
            SELECT gateway_code, gateway_name, mode, currency, is_enabled, 
                   api_key_public, api_key_secret, merchant_id, webhook_secret, webhook_url,
                   created_at, updated_at
            FROM payment_gateways
            WHERE gateway_code = :gateway_code
        """)
        result = db.session.execute(query, {'gateway_code': gateway_code}).fetchone()
        
        if not result or len(result) < 12:
            return jsonify({'success': False, 'error': 'Gateway not found'}), 404
        
        # Don't expose the actual secret, show encrypted indicator
        api_key_secret = result[6] if len(result) > 6 and result[6] else ''
        if api_key_secret and not api_key_secret.startswith('encrypted:'):
            api_key_secret = 'encrypted:****'  # Show encrypted indicator
        
        gateway = {
            'gateway_code': result[0] if len(result) > 0 else gateway_code,
            'gateway_name': (result[1] if len(result) > 1 and result[1] else None) or gateway_code,
            'name': (result[1] if len(result) > 1 and result[1] else None) or gateway_code,
            'mode': (result[2] if len(result) > 2 and result[2] else None) or 'test',
            'currency': (result[3] if len(result) > 3 and result[3] else None) or 'USD',
            'is_enabled': bool(result[4] if len(result) > 4 else False),
            'status': 'active' if bool(result[4] if len(result) > 4 else False) else 'inactive',
            'api_key_public': result[5] if len(result) > 5 and result[5] else '',
            'api_key_secret': api_key_secret,
            'secret_key': api_key_secret,  # Alias
            'merchant_id': result[7] if len(result) > 7 and result[7] else '',
            'webhook_secret': result[8] if len(result) > 8 and result[8] else '',
            'webhook_url': result[9] if len(result) > 9 and result[9] else '',
            'created_at': result[10].isoformat() if len(result) > 10 and result[10] else None,
            'updated_at': result[11].isoformat() if len(result) > 11 and result[11] else None
        }
        
        return jsonify({'success': True, 'gateway': gateway}), 200
    except Exception as e:
        print(f"[PAYMENT GATEWAYS] Error fetching gateway: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/payments/gateways', methods=['POST'])
@jwt_required()
def create_payment_gateway():
    """Create a new payment gateway"""
    try:
        init_analytics_tables()
        data = request.get_json()
        
        gateway_code = data.get('gateway_code', '').lower().strip()
        if not gateway_code:
            return jsonify({'success': False, 'error': 'Gateway code is required'}), 400
        
        # Check if gateway already exists
        check_query = text("""
            SELECT gateway_code FROM payment_gateways WHERE gateway_code = :gateway_code
        """)
        existing = db.session.execute(check_query, {'gateway_code': gateway_code}).fetchone()
        if existing:
            return jsonify({'success': False, 'error': 'Gateway with this code already exists'}), 400
        
        # Encrypt secret key if provided
        api_key_secret = data.get('api_key_secret', '') or data.get('secret_key', '')
        if api_key_secret and not api_key_secret.startswith('encrypted:'):
            # In production, encrypt this properly
            api_key_secret = f'encrypted:{api_key_secret}'
        
        insert_query = text("""
            INSERT INTO payment_gateways 
            (gateway_code, gateway_name, mode, currency, is_enabled, 
             api_key_public, api_key_secret, merchant_id, webhook_secret, webhook_url)
            VALUES 
            (:gateway_code, :gateway_name, :mode, :currency, :is_enabled,
             :api_key_public, :api_key_secret, :merchant_id, :webhook_secret, :webhook_url)
        """)
        
        db.session.execute(insert_query, {
            'gateway_code': gateway_code,
            'gateway_name': data.get('gateway_name', gateway_code),
            'mode': data.get('mode', 'test'),
            'currency': data.get('currency', 'USD'),
            'is_enabled': data.get('is_enabled', False),
            'api_key_public': data.get('api_key_public', '') or data.get('api_key', ''),
            'api_key_secret': api_key_secret,
            'merchant_id': data.get('merchant_id', ''),
            'webhook_secret': data.get('webhook_secret', ''),
            'webhook_url': data.get('webhook_url', '')
        })
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': 'Payment gateway created successfully',
            'gateway_code': gateway_code
        }), 201
        
    except Exception as e:
        db.session.rollback()
        print(f"[PAYMENT GATEWAYS] Error creating gateway: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/payments/gateways/<gateway_code>', methods=['PUT'])
@jwt_required()
def update_payment_gateway(gateway_code):
    """Update a payment gateway"""
    try:
        init_analytics_tables()
        data = request.get_json()
        
        # Check if gateway exists
        check_query = text("""
            SELECT gateway_code FROM payment_gateways WHERE gateway_code = :gateway_code
        """)
        existing = db.session.execute(check_query, {'gateway_code': gateway_code}).fetchone()
        if not existing:
            return jsonify({'success': False, 'error': 'Gateway not found'}), 404
        
        # Build update query dynamically
        update_fields = []
        update_params = {'gateway_code': gateway_code}
        
        # Handle secret key - only update if new value provided
        api_key_secret = data.get('api_key_secret', '') or data.get('secret_key', '')
        secret_provided = bool(api_key_secret and api_key_secret.strip())
        
        if secret_provided:
            # If it's not already encrypted and not the placeholder, encrypt it
            if not api_key_secret.startswith('encrypted:') and api_key_secret != 'encrypted:****':
                api_key_secret = f'encrypted:{api_key_secret}'
                update_fields.append('api_key_secret = :api_key_secret')
                update_params['api_key_secret'] = api_key_secret
        # If secret is not provided, don't update it (keep existing)
        
        if 'gateway_name' in data:
            update_fields.append('gateway_name = :gateway_name')
            update_params['gateway_name'] = data['gateway_name']
        
        if 'mode' in data:
            update_fields.append('mode = :mode')
            update_params['mode'] = data['mode']
        
        if 'currency' in data:
            update_fields.append('currency = :currency')
            update_params['currency'] = data['currency']
        
        if 'is_enabled' in data:
            update_fields.append('is_enabled = :is_enabled')
            update_params['is_enabled'] = data['is_enabled']
        
        if 'api_key_public' in data or 'api_key' in data:
            update_fields.append('api_key_public = :api_key_public')
            update_params['api_key_public'] = data.get('api_key_public', '') or data.get('api_key', '')
        
        if 'merchant_id' in data:
            update_fields.append('merchant_id = :merchant_id')
            update_params['merchant_id'] = data['merchant_id']
        
        if 'webhook_secret' in data:
            update_fields.append('webhook_secret = :webhook_secret')
            update_params['webhook_secret'] = data['webhook_secret']
        
        if 'webhook_url' in data:
            update_fields.append('webhook_url = :webhook_url')
            update_params['webhook_url'] = data['webhook_url']
        
        if not update_fields:
            return jsonify({'success': False, 'error': 'No fields to update'}), 400
        
        update_query = text(f"""
            UPDATE payment_gateways 
            SET {', '.join(update_fields)}, updated_at = UTC_TIMESTAMP()
            WHERE gateway_code = :gateway_code
        """)
        
        print(f"[PAYMENT GATEWAYS] Updating gateway {gateway_code} with fields: {list(update_params.keys())}")
        db.session.execute(update_query, update_params)
        db.session.commit()
        
        print(f"[PAYMENT GATEWAYS] ✅ Successfully updated gateway {gateway_code}")
        return jsonify({
            'success': True,
            'message': 'Payment gateway updated successfully'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        error_msg = str(e)
        print(f"[PAYMENT GATEWAYS] ❌ Error updating gateway {gateway_code}: {error_msg}")
        import traceback
        traceback.print_exc()
        
        # Provide more specific error messages
        if 'Duplicate entry' in error_msg:
            return jsonify({'success': False, 'error': 'A gateway with this code already exists'}), 400
        elif 'not found' in error_msg.lower():
            return jsonify({'success': False, 'error': 'Gateway not found'}), 404
        else:
            return jsonify({'success': False, 'error': f'Failed to update gateway: {error_msg}'}), 500

