@app.route('/api/payments/gateways/<gateway_code>/test', methods=['POST'])
@jwt_required()
def test_payment_gateway(gateway_code):
    """Test payment gateway connection - validates format and structure"""
    try:
        init_analytics_tables()
        data = request.get_json() or {}
        
        # Get gateway info
        query = text("""
            SELECT gateway_code, gateway_name, mode FROM payment_gateways 
            WHERE gateway_code = :gateway_code
        """)
        gateway = db.session.execute(query, {'gateway_code': gateway_code}).fetchone()
        
        if not gateway:
            return jsonify({'success': False, 'error': 'Gateway not found'}), 404
        
        gateway_name = gateway[1] or gateway_code
        gateway_name_lower = gateway_name.lower()
        gateway_code_lower = gateway_code.lower()
        mode = gateway[2] or 'test'
        
        # Get credentials from request or from database
        api_key_public = data.get('api_key_public', '') or data.get('api_key', '')
        api_key_secret = data.get('api_key_secret', '') or data.get('secret_key', '')
        merchant_id = data.get('merchant_id', '')
        
        # If credentials not in request, try to get from database
        if not api_key_public or not api_key_secret:
            get_creds_query = text("""
                SELECT api_key_public, api_key_secret, merchant_id 
                FROM payment_gateways 
                WHERE gateway_code = :gateway_code
            """)
            db_creds = db.session.execute(get_creds_query, {'gateway_code': gateway_code}).fetchone()
            if db_creds:
                if not api_key_public:
                    api_key_public = db_creds[0] or ''
                if not api_key_secret:
                    # Remove encrypted: prefix if present
                    api_key_secret = (db_creds[1] or '').replace('encrypted:', '')
                if not merchant_id:
                    merchant_id = db_creds[2] or ''
        
        # Validation results
        validation_results = {
            'format_valid': True,
            'required_fields_present': True,
            'warnings': [],
            'errors': []
        }
        
        # Gateway-specific validation
        if gateway_code_lower == 'razorpay':
            if not api_key_public or not api_key_secret:
                validation_results['errors'].append('Razorpay requires API Key and Secret Key')
                validation_results['required_fields_present'] = False
            else:
                # Razorpay keys typically start with rzp_test_ or rzp_live_
                if mode == 'test':
                    if not api_key_public.startswith('rzp_test_'):
                        validation_results['warnings'].append('Test mode: API Key should start with "rzp_test_"')
                    if not api_key_secret.startswith('rzp_test_'):
                        validation_results['warnings'].append('Test mode: Secret Key should start with "rzp_test_"')
                else:
                    if not api_key_public.startswith('rzp_live_'):
                        validation_results['warnings'].append('Live mode: API Key should start with "rzp_live_"')
                    if not api_key_secret.startswith('rzp_live_'):
                        validation_results['warnings'].append('Live mode: Secret Key should start with "rzp_live_"')
                
                # Check minimum length
                if len(api_key_public) < 20:
                    validation_results['warnings'].append('API Key seems too short (should be ~20+ characters)')
                if len(api_key_secret) < 20:
                    validation_results['warnings'].append('Secret Key seems too short (should be ~20+ characters)')
        
        elif gateway_code_lower == 'stripe':
            if not api_key_public or not api_key_secret:
                validation_results['errors'].append('Stripe requires Publishable Key and Secret Key')
                validation_results['required_fields_present'] = False
            else:
                # Stripe keys: pk_test_/pk_live_ for public, sk_test_/sk_live_ for secret
                if mode == 'test':
                    if not api_key_public.startswith('pk_test_'):
                        validation_results['warnings'].append('Test mode: Publishable Key should start with "pk_test_"')
                    if not api_key_secret.startswith('sk_test_'):
                        validation_results['warnings'].append('Test mode: Secret Key should start with "sk_test_"')
                else:
                    if not api_key_public.startswith('pk_live_'):
                        validation_results['warnings'].append('Live mode: Publishable Key should start with "pk_live_"')
                    if not api_key_secret.startswith('sk_live_'):
                        validation_results['warnings'].append('Live mode: Secret Key should start with "sk_live_"')
                
                # Check minimum length
                if len(api_key_public) < 30:
                    validation_results['warnings'].append('Publishable Key seems too short (should be ~30+ characters)')
                if len(api_key_secret) < 30:
                    validation_results['warnings'].append('Secret Key seems too short (should be ~30+ characters)')
        
        elif gateway_code_lower == 'paypal':
            if not api_key_public or not api_key_secret:
                validation_results['errors'].append('PayPal requires Client ID and Secret')
                validation_results['required_fields_present'] = False
            else:
                # PayPal credentials are typically longer alphanumeric strings
                if len(api_key_public) < 20:
                    validation_results['warnings'].append('Client ID seems too short')
                if len(api_key_secret) < 20:
                    validation_results['warnings'].append('Secret seems too short')
        
        elif gateway_code_lower == 'phonepe':
            if not merchant_id or not api_key_secret:
                validation_results['errors'].append('PhonePe requires Merchant ID and Salt Key')
                validation_results['required_fields_present'] = False
            else:
                # PhonePe-specific validation - check if wrong gateway credentials are used
                if api_key_public:
                    # Check if Stripe credentials are used for PhonePe
                    if api_key_public.startswith('pk_test_') or api_key_public.startswith('pk_live_'):
                        validation_results['errors'].append('❌ Invalid: Stripe credentials detected. PhonePe does not use pk_test_/pk_live_ format.')
                    # Check if Razorpay credentials are used
                    elif api_key_public.startswith('rzp_test_') or api_key_public.startswith('rzp_live_'):
                        validation_results['errors'].append('❌ Invalid: Razorpay credentials detected. PhonePe does not use rzp_test_/rzp_live_ format.')
                
                if api_key_secret:
                    # Check if Stripe secret is used for PhonePe
                    if api_key_secret.startswith('sk_test_') or api_key_secret.startswith('sk_live_'):
                        validation_results['errors'].append('❌ Invalid: Stripe secret key detected. PhonePe uses Salt Key, not sk_test_/sk_live_ format.')
                    # Check if Razorpay secret is used
                    elif api_key_secret.startswith('rzp_test_') or api_key_secret.startswith('rzp_live_'):
                        validation_results['errors'].append('❌ Invalid: Razorpay secret key detected. PhonePe uses Salt Key, not rzp_test_/rzp_live_ format.')
                
                # PhonePe Merchant ID is typically alphanumeric
                if len(merchant_id) < 5:
                    validation_results['warnings'].append('Merchant ID seems too short')
                if len(api_key_secret) < 10:
                    validation_results['warnings'].append('Salt Key seems too short')
        
        # Additional cross-gateway validation - check for wrong credentials
        if api_key_public and api_key_secret:
            # Check if Stripe credentials are used for non-Stripe gateway
            if gateway_code_lower != 'stripe':
                if (api_key_public.startswith('pk_test_') or api_key_public.startswith('pk_live_')) or \
                   (api_key_secret.startswith('sk_test_') or api_key_secret.startswith('sk_live_')):
                    validation_results['errors'].append(f'❌ Invalid: Stripe credentials detected for {gateway_name}. Please use {gateway_name} credentials.')
            
            # Check if Razorpay credentials are used for non-Razorpay gateway
            if gateway_code_lower != 'razorpay':
                if (api_key_public.startswith('rzp_test_') or api_key_public.startswith('rzp_live_')) or \
                   (api_key_secret.startswith('rzp_test_') or api_key_secret.startswith('rzp_live_')):
                    validation_results['errors'].append(f'❌ Invalid: Razorpay credentials detected for {gateway_name}. Please use {gateway_name} credentials.')
        
        # Check if there are errors
        if validation_results['errors']:
            return jsonify({
                'success': False,
                'error': '; '.join(validation_results['errors']),
                'validation': validation_results
            }), 400
        
        # Build response message
        messages = []
        if validation_results['required_fields_present']:
            messages.append(f'✅ All required credentials are present for {gateway_name}')
        
        if validation_results['warnings']:
            messages.append('⚠️ Format warnings: ' + '; '.join(validation_results['warnings']))
            messages.append('Note: These are format checks. Actual API validation requires real credentials.')
        else:
            messages.append('✅ Credential formats appear valid')
        
        messages.append(f'Mode: {mode.upper()}')
        messages.append('💡 This is a format validation. To fully test, use real credentials from your payment gateway dashboard.')
        
        return jsonify({
            'success': True,
            'message': ' | '.join(messages),
            'validation': validation_results,
            'test_mode': True,
            'note': 'This validates credential format. For actual API testing, use real credentials from your payment gateway.'
        }), 200
        
    except Exception as e:
        print(f"[PAYMENT GATEWAYS] Error testing gateway: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings/api-keys', methods=['GET'])
@jwt_required()
def get_api_keys():
    """Get API keys"""
    try:
        query = text("""
            SELECT id, key_name, key_prefix, created_at, last_used_at, is_active
            FROM api_keys
            ORDER BY created_at DESC
        """)
        result = db.session.execute(query).fetchall()
        
        keys = []
        for row in result:
            keys.append({
                'id': row[0],
                'key_name': row[1],  # Use key_name to match frontend expectation
                'name': row[1],  # Also include 'name' for compatibility
                'key_prefix': row[2],  # Use key_prefix to match frontend
                'prefix': row[2],  # Also include 'prefix' for compatibility
                'created_at': row[3].isoformat() if row[3] else None,
                'last_used_at': row[4].isoformat() if row[4] else None,
                'is_active': bool(row[5]),  # Use is_active to match frontend
                'active': bool(row[5])  # Also include 'active' for compatibility
            })
        
        return jsonify({'success': True, 'keys': keys, 'api_keys': keys}), 200
    except Exception:
        return jsonify({'success': True, 'keys': [], 'api_keys': []}), 200

@app.route('/api/settings/api-keys', methods=['POST'])
@jwt_required()
def create_api_key():
    """Create API key"""
    try:
        # Ensure tables are initialized with correct columns
        init_analytics_tables()
        
        data = request.get_json()
        # Support both 'name' and 'key_name' for compatibility
        key_name = data.get('key_name') or data.get('name', 'New API Key')
        
        # Generate key prefix and full key
        key_prefix = f"sk_live_{''.join(random.choices(string.ascii_letters + string.digits, k=24))}"
        # Generate full key (prefix + secret part)
        key_secret = ''.join(random.choices(string.ascii_letters + string.digits, k=32))
        full_key = f"{key_prefix}_{key_secret}"
        
        # Check which columns exist in the table
        check_cols = text("""
            SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE TABLE_SCHEMA = DATABASE() 
            AND TABLE_NAME = 'api_keys'
        """)
        existing_cols = [row[0] for row in db.session.execute(check_cols).fetchall()]
        
        # Build insert query based on available columns
        if 'api_key' in existing_cols and 'key_prefix' in existing_cols:
            # Both columns exist - use key_prefix, set api_key to same value
            query = text("""
                INSERT INTO api_keys (key_name, key_prefix, api_key, created_at, is_active)
                VALUES (:name, :prefix, :prefix, UTC_TIMESTAMP(), 1)
            """)
            result = db.session.execute(query, {'name': key_name, 'prefix': key_prefix})
        elif 'key_prefix' in existing_cols:
            # Only key_prefix exists - use it
            query = text("""
                INSERT INTO api_keys (key_name, key_prefix, created_at, is_active)
                VALUES (:name, :prefix, UTC_TIMESTAMP(), 1)
            """)
            result = db.session.execute(query, {'name': key_name, 'prefix': key_prefix})
        elif 'api_key' in existing_cols:
            # Only api_key exists - use it (old structure)
            query = text("""
                INSERT INTO api_keys (key_name, api_key, created_at, is_active)
                VALUES (:name, :prefix, UTC_TIMESTAMP(), 1)
            """)
            result = db.session.execute(query, {'name': key_name, 'prefix': key_prefix})
        else:
            # Fallback - try with just key_name
            query = text("""
                INSERT INTO api_keys (key_name, created_at, is_active)
                VALUES (:name, UTC_TIMESTAMP(), 1)
            """)
            result = db.session.execute(query, {'name': key_name})
        db.session.commit()
        
        # Get the inserted ID
        key_id = result.lastrowid
        
        return jsonify({
            'success': True, 
            'api_key': {
                'id': key_id,
                'key_name': key_name,
                'key_prefix': key_prefix,
                'full_key': full_key  # Show this only once, user must copy it
            },
            'message': 'API key created successfully. Copy the key now - you won\'t be able to see it again!'
        }), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

