@app.route('/api/settings/feature-flags', methods=['GET'])
@jwt_required()
def get_feature_flags():
    """Get feature flags"""
    try:
        # First, check which columns exist in the feature_flags table
        check_cols = text("""
            SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE TABLE_SCHEMA = DATABASE() 
            AND TABLE_NAME = 'feature_flags'
            ORDER BY ORDINAL_POSITION
        """)
        existing_cols = [row[0] for row in db.session.execute(check_cols).fetchall()]
        
        # Build SELECT query dynamically based on available columns
        select_fields = []
        
        # Find primary key column
        pk_col = None
        if 'flag_key' in existing_cols:
            pk_col = 'flag_key'
            select_fields.append('flag_key')
        elif 'key' in existing_cols:
            pk_col = 'key'
            select_fields.append('key')
        elif 'feature_key' in existing_cols:
            pk_col = 'feature_key'
            select_fields.append('feature_key')
        else:
            # No primary key found - return empty
            return jsonify({'success': True, 'flags': {}, 'feature_flags': []}), 200
        
        # Find value/enabled column
        value_col = None
        if 'flag_value' in existing_cols:
            value_col = 'flag_value'
            select_fields.append('flag_value')
        elif 'is_enabled' in existing_cols:
            value_col = 'is_enabled'
            select_fields.append('is_enabled')
        elif 'enabled' in existing_cols:
            value_col = 'enabled'
            select_fields.append('enabled')
        
        # Find description/name column
        desc_col = None
        if 'description' in existing_cols:
            desc_col = 'description'
            select_fields.append('description')
        elif 'flag_name' in existing_cols:
            desc_col = 'flag_name'
            select_fields.append('flag_name')
        elif 'feature_name' in existing_cols:
            desc_col = 'feature_name'
            select_fields.append('feature_name')
        elif 'name' in existing_cols and 'name' != pk_col:
            desc_col = 'name'
            select_fields.append('name')
        
        if not select_fields:
            return jsonify({'success': True, 'flags': {}, 'feature_flags': []}), 200
        
        # Build and execute query
        query = text(f"SELECT {', '.join(select_fields)} FROM feature_flags")
        result = db.session.execute(query).fetchall()
        
        flags = {}
        flags_array = []
        
        for row in result:
            pk_value = row[0]  # Primary key is always first
            value = row[1] if len(row) > 1 and value_col else 0
            description = row[2] if len(row) > 2 and desc_col else (row[1] if len(row) > 1 and not value_col and desc_col else pk_value)
            
            # If only 2 columns and second is not value_col, it might be description
            if len(row) == 2 and not value_col:
                description = row[1]
                value = 0
            
            enabled = bool(value) if value is not None else False
            
            flags[pk_value] = {
                'enabled': enabled,
                'description': description or pk_value
            }
            
            # Add to array for frontend
            flags_array.append({
                'id': pk_value,
                'flag_key': pk_value,
                'key': pk_value,
                'feature_key': pk_value,
                'flag_name': description or pk_value,
                'feature_name': description or pk_value,
                'name': description or pk_value,
                'description': description or '',
                'is_enabled': enabled,
                'enabled': enabled,
                'flag_value': 1 if enabled else 0
            })
        
        return jsonify({'success': True, 'flags': flags, 'feature_flags': flags_array}), 200
    except Exception as e:
        print(f"[GET FEATURE FLAGS] Error: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': True, 'flags': {}, 'feature_flags': []}), 200

@app.route('/api/settings/feature-flags', methods=['POST'])
@jwt_required()
def create_feature_flag():
    """Create/Update feature flag"""
    try:
        # Ensure tables are initialized with correct columns
        init_analytics_tables()
        
        data = request.get_json()
        # Support both 'key' and 'flag_key', both 'feature_key'
        flag_key = data.get('flag_key') or data.get('feature_key') or data.get('key')
        if not flag_key:
            return jsonify({'success': False, 'error': 'Flag key is required'}), 400
        
        # Support both 'enabled' and 'is_enabled', also 'flag_value'
        if 'is_enabled' in data:
            flag_value = int(data['is_enabled'])
        elif 'enabled' in data:
            flag_value = int(data['enabled'])
        elif 'flag_value' in data:
            flag_value = int(data['flag_value'])
        else:
            flag_value = 0
        
        # Support both 'description' and 'flag_name', also 'feature_name'
        description = data.get('description') or data.get('flag_name') or data.get('feature_name') or flag_key
        
        # Check which columns exist in the table and their nullability
        check_cols = text("""
            SELECT COLUMN_NAME, IS_NULLABLE, COLUMN_DEFAULT 
            FROM INFORMATION_SCHEMA.COLUMNS 
            WHERE TABLE_SCHEMA = DATABASE() 
            AND TABLE_NAME = 'feature_flags'
        """)
        existing_cols_info = {row[0]: {'nullable': row[1] == 'YES', 'default': row[2]} for row in db.session.execute(check_cols).fetchall()}
        existing_cols = list(existing_cols_info.keys())
        
        # Build insert query based on available columns
        insert_cols = []
        insert_values = []
        params = {}
        
        # Handle primary key - could be flag_key, key, or feature_key - REQUIRED
        pk_col = None
        if 'flag_key' in existing_cols:
            pk_col = 'flag_key'
        elif 'key' in existing_cols:
            pk_col = 'key'
        elif 'feature_key' in existing_cols:
            pk_col = 'feature_key'
        
        if not pk_col:
            return jsonify({'success': False, 'error': 'Feature flags table structure is invalid - no primary key column found'}), 500
        
        insert_cols.append(pk_col)
        insert_values.append(f':{pk_col}')
        params[pk_col] = flag_key
        
        # Handle flag_value/is_enabled/enabled - include if NOT NULL or preferred
        if 'flag_value' in existing_cols:
            insert_cols.append('flag_value')
            insert_values.append(':flag_value')
            params['flag_value'] = flag_value
        elif 'is_enabled' in existing_cols:
            insert_cols.append('is_enabled')
            insert_values.append(':is_enabled')
            params['is_enabled'] = flag_value
        elif 'enabled' in existing_cols:
            insert_cols.append('enabled')
            insert_values.append(':enabled')
            params['enabled'] = flag_value
        
        # Handle description/flag_name/feature_name/name - include ALL required columns
        # Check ALL possible name columns and ALWAYS include if NOT NULL without default
        # Priority: description > flag_name > feature_name > name
        
        # Always check for description first (preferred column)
        if 'description' in existing_cols:
            # Always include description if it exists (whether required or optional)
            insert_cols.append('description')
            insert_values.append(':description')
            params['description'] = description
        
        # Check for flag_name - ALWAYS include if it's required (NOT NULL without default)
        if 'flag_name' in existing_cols:
            if not existing_cols_info['flag_name']['nullable'] and not existing_cols_info['flag_name']['default']:
                # flag_name is REQUIRED, must include it
                insert_cols.append('flag_name')
                insert_values.append(':flag_name')
                params['flag_name'] = description
            elif 'description' not in existing_cols:
                # If description doesn't exist but flag_name does, include flag_name
                insert_cols.append('flag_name')
                insert_values.append(':flag_name')
                params['flag_name'] = description
        
        # Check for feature_name - ALWAYS include if it's required (NOT NULL without default)
        if 'feature_name' in existing_cols:
            if not existing_cols_info['feature_name']['nullable'] and not existing_cols_info['feature_name']['default']:
                # feature_name is REQUIRED, must include it (this is likely causing the error!)
                insert_cols.append('feature_name')
                insert_values.append(':feature_name')
                params['feature_name'] = description
            elif 'description' not in existing_cols and 'flag_name' not in existing_cols:
                # Only include if description and flag_name don't exist
                insert_cols.append('feature_name')
                insert_values.append(':feature_name')
                params['feature_name'] = description
        
        # Check for name - ALWAYS include if it's required (NOT NULL without default)
        if 'name' in existing_cols and 'name' != pk_col:  # Don't duplicate if name is the primary key
            if not existing_cols_info['name']['nullable'] and not existing_cols_info['name']['default']:
                # name is REQUIRED, must include it
                insert_cols.append('name')
                insert_values.append(':name')
                params['name'] = description
            elif 'description' not in existing_cols and 'flag_name' not in existing_cols and 'feature_name' not in existing_cols:
                # Only include if none of the other name columns exist
                insert_cols.append('name')
                insert_values.append(':name')
                params['name'] = description
        
        # Build ON DUPLICATE KEY UPDATE clause
        update_parts = []
        if 'flag_value' in existing_cols:
            update_parts.append('flag_value = :flag_value')
        elif 'is_enabled' in existing_cols:
            update_parts.append('is_enabled = :is_enabled')
        elif 'enabled' in existing_cols:
            update_parts.append('enabled = :enabled')
        
        if 'description' in existing_cols:
            update_parts.append('description = :description')
        elif 'flag_name' in existing_cols:
            update_parts.append('flag_name = :flag_name')
        
        if not update_parts:
            # No update needed, just insert
            query = text(f"""
                INSERT INTO feature_flags ({', '.join(insert_cols)})
                VALUES ({', '.join(insert_values)})
            """)
        else:
            query = text(f"""
                INSERT INTO feature_flags ({', '.join(insert_cols)})
                VALUES ({', '.join(insert_values)})
                ON DUPLICATE KEY UPDATE {', '.join(update_parts)}
            """)
        
        db.session.execute(query, params)
        db.session.commit()
        
        return jsonify({'success': True, 'message': 'Feature flag created successfully'}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/settings/feature-flags/<string:flag_key>', methods=['PUT'])
@jwt_required()
def update_feature_flag(flag_key):
    """Update feature flag (toggle or update)"""
    try:
        data = request.get_json()
        # Support both 'enabled' and 'is_enabled'
        if 'is_enabled' in data:
            flag_value = int(data['is_enabled'])
        elif 'enabled' in data:
            flag_value = int(data['enabled'])
        else:
            # If not provided, toggle current value
            check_query = text("SELECT flag_value FROM feature_flags WHERE flag_key = :key")
            current = db.session.execute(check_query, {'key': flag_key}).fetchone()
            flag_value = 0 if current and current[0] == 1 else 1
        
        description = data.get('description')
        
        if description:
            query = text("""
                UPDATE feature_flags
                SET flag_value = :value, description = :desc
                WHERE flag_key = :key
            """)
            db.session.execute(query, {'key': flag_key, 'value': flag_value, 'desc': description})
        else:
            query = text("""
                UPDATE feature_flags
                SET flag_value = :value
                WHERE flag_key = :key
            """)
            db.session.execute(query, {'key': flag_key, 'value': flag_value})
        
        db.session.commit()
        return jsonify({'success': True, 'message': 'Feature flag updated successfully'}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'success': False, 'error': str(e)}), 500

