@app.route('/api/admin/profile', methods=['GET'])
@jwt_required()
def get_admin_profile():
    """Get admin profile with additional metadata"""
    try:
        user_id = get_jwt_identity()
        
        # Remove 'admin_' prefix if present
        if user_id and str(user_id).startswith('admin_'):
            user_id = int(str(user_id).replace('admin_', ''))
        
        from datetime import datetime, timezone
        
        # Ensure password_last_changed column exists in admin_users table
        try:
            check_column_query = text("""
                SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS 
                WHERE TABLE_SCHEMA = DATABASE() 
                AND TABLE_NAME = 'admin_users' 
                AND COLUMN_NAME = 'password_last_changed'
            """)
            column_exists = db.session.execute(check_column_query).scalar() > 0
            
            if not column_exists:
                # Add password_last_changed column to admin_users table
                add_column_query = text("""
                    ALTER TABLE admin_users 
                    ADD COLUMN password_last_changed DATETIME NULL 
                    AFTER password_hash
                """)
                db.session.execute(add_column_query)
                db.session.commit()
                print(f"[PROFILE] Added password_last_changed column to admin_users table")
        except Exception as alter_err:
            db.session.rollback()
            print(f"[PROFILE] Warning: Could not ensure password_last_changed column exists: {str(alter_err)}")
        
        query = text("""
            SELECT id, username, email, full_name, phone, avatar_url, created_at, last_login, updated_at, password_last_changed
            FROM admin_users
            WHERE id = :user_id
        """)
        result = db.session.execute(query, {'user_id': user_id}).fetchone()
        
        if not result:
            return jsonify({'error': 'Admin user not found'}), 404
        
        # Helper function to convert datetime to ISO format with UTC timezone
        def to_iso_datetime(dt):
            """Convert datetime to ISO format string with UTC timezone"""
            if not dt:
                return None
            # If datetime is naive (no timezone), assume UTC
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.isoformat()
        
        # Get password_last_changed from admin_users table (not app_settings)
        # Password last changed is now stored in admin_users table column
        password_last_changed = result[9] if len(result) > 9 else None
        print(f"[PROFILE] Retrieved password_last_changed from admin_users for user {user_id}: {password_last_changed} (type: {type(password_last_changed)})")
        
        # Convert password_last_changed to ISO format using helper function
        password_last_changed = to_iso_datetime(password_last_changed) if password_last_changed else None
        
        # Get active sessions count
        active_sessions_query = text("""
            SELECT COUNT(*) FROM user_sessions
            WHERE user_id = :user_id AND user_type = 'admin'
            AND last_activity > DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE)
            AND COALESCE(terminated_by_admin, 0) = 0
        """)
        timeout_minutes = get_session_timeout_minutes()
        active_sessions_count = db.session.execute(active_sessions_query, {'user_id': user_id, 'timeout_minutes': timeout_minutes}).scalar() or 0
        
        # Get active sessions list (include id for revoke functionality)
        sessions_query = text("""
            SELECT id, session_id, ip_address, browser, os, device_type, entry_time, last_activity
            FROM user_sessions
            WHERE user_id = :user_id AND user_type = 'admin'
            AND last_activity > DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE)
            AND COALESCE(terminated_by_admin, 0) = 0
            ORDER BY last_activity DESC
            LIMIT 10
        """)
        sessions_result = db.session.execute(sessions_query, {'user_id': user_id, 'timeout_minutes': timeout_minutes}).fetchall()
        active_sessions_list = []
        for row in sessions_result:
            active_sessions_list.append({
                'id': row[0],  # Add id field for revoke functionality
                'session_id': row[1],
                'ip_address': row[2],
                'browser': row[3],
                'os': row[4],
                'device_type': row[5],
                'entry_time': to_iso_datetime(row[6]),
                'last_activity': to_iso_datetime(row[7])
            })
        
        # Get login history from user_sessions table
        login_history = []
        try:
            login_history_query = text("""
                SELECT entry_time, ip_address, browser, os, device_type, user_agent
                FROM user_sessions
                WHERE user_id = :user_id AND user_type = 'admin'
                ORDER BY entry_time DESC
                LIMIT 10
            """)
            login_history_result = db.session.execute(login_history_query, {'user_id': user_id}).fetchall()
            for row in login_history_result:
                # Convert DATETIME to ISO format with timezone using helper function
                timestamp_str = to_iso_datetime(row[0])
                
                login_history.append({
                    'action': 'LOGIN_SUCCESS',
                    'ip_address': row[1],
                    'timestamp': timestamp_str,
                    'browser': row[2],
                    'os': row[3],
                    'device_type': row[4],
                    'user_agent': row[5] if len(row) > 5 else None
                })
        except Exception as e:
            print(f"[PROFILE] Error fetching login history from user_sessions: {str(e)}")
            import traceback
            traceback.print_exc()
            login_history = []  # Return empty array if error
        
        # Get recent activity from user_actions table
        # IMPORTANT: Filter by actor_type='admin' to ensure we only get admin actions
        # User_id 1 is admin, so we should only show actions where actor_type='admin'
        recent_activity = []
        try:
            activity_query = text("""
                SELECT id, action_type, action_details, page_url, timestamp
                FROM user_actions
                WHERE user_id = :user_id AND actor_type = 'admin'
                ORDER BY timestamp DESC
                LIMIT 10
            """)
            activity_result = db.session.execute(activity_query, {'user_id': user_id}).fetchall()
            for row in activity_result:
                action_id = row[0]
                action_type = row[1]
                # Parse action_details if it's JSON
                action_details = row[2]
                if action_details:
                    try:
                        import json
                        action_details = json.loads(action_details) if isinstance(action_details, str) else action_details
                    except:
                        # If parsing fails, keep as dict or create dict from string
                        if isinstance(action_details, str):
                            try:
                                action_details = {'raw': action_details}
                            except:
                                action_details = {}
                        pass  # Keep as dict if already parsed
                
                page_url = row[3]
                # Convert TIMESTAMP to ISO format with timezone using helper function
                timestamp_str = to_iso_datetime(row[4])
                
                # Extract notes from action_details
                notes = ''
                if isinstance(action_details, dict):
                    notes = action_details.get('notes', '') or action_details.get('message', '') or action_details.get('description', '')
                
                recent_activity.append({
                    'id': action_id,  # Include ID for React key
                    'action': action_type,  # action_type
                    'action_type': action_type,  # For compatibility
                    'resource': action_details.get('resource_type', '') if isinstance(action_details, dict) else '',
                    'resource_type': action_details.get('resource_type', '') if isinstance(action_details, dict) else '',
                    'resource_id': action_details.get('resource_id', '') if isinstance(action_details, dict) else '',
                    'action_details': action_details,
                    'page_url': page_url,
                    'timestamp': timestamp_str,
                    'notes': notes
                })
        except Exception as e:
            print(f"[PROFILE] Error fetching recent activity from user_actions: {str(e)}")
            import traceback
            traceback.print_exc()
            recent_activity = []  # Return empty array if error
        
        # Get preferences from app_settings
        preferences_query = text("""
            SELECT setting_value FROM app_settings
            WHERE setting_key = 'preferences' AND category = 'profile' AND user_id = :user_id
        """)
        preferences_result = db.session.execute(preferences_query, {'user_id': user_id}).fetchone()
        preferences = {}
        if preferences_result and preferences_result[0]:
            try:
                preferences = json.loads(preferences_result[0])
            except:
                preferences = {}
        
        profile = {
            'id': result[0],
            'username': result[1],
            'email': result[2],
            'full_name': result[3],
            'phone': result[4],
            'avatar_url': result[5],
            'created_at': to_iso_datetime(result[6]),
            'last_login': to_iso_datetime(result[7]),
            'updated_at': to_iso_datetime(result[8]),
            'profile_last_updated': to_iso_datetime(result[8]),  # Use updated_at as profile_last_updated
            'password_last_changed': password_last_changed,  # Tracked in admin_users table, already converted
            'active_sessions_count': active_sessions_count,
            'active_sessions_list': active_sessions_list,
            'login_history': login_history,
            'recent_activity': recent_activity,
            'preferences': preferences,
            'role': 'admin'
        }
        
        return jsonify({'success': True, 'profile': profile}), 200
    except Exception as e:
        print(f"Error fetching admin profile: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500

