# ==================== NOTIFICATION SYSTEM ====================

def check_notification_enabled(admin_id, notification_type):
    """
    Check if a specific notification type is enabled for an admin user.
    Maps grouped notification types (e.g., 'product_operations') to individual types (e.g., 'product_created', 'product_updated', 'product_deleted').
    
    Args:
        admin_id: The admin user ID
        notification_type: The specific notification type (e.g., 'product_created', 'order_updated')
    
    Returns:
        bool: True if the notification is enabled, False otherwise
    """
    try:
        # Map individual notification types to grouped preference types
        type_mapping = {
            # Product operations
            'product_created': 'product_operations',
            'product_updated': 'product_operations',
            'product_deleted': 'product_operations',
            # Order operations
            'order_created': 'order_operations',
            'order_updated': 'order_operations',
            'order_cancelled': 'order_operations',
            'payment_received': 'order_operations',
            # Coupon operations
            'coupon_created': 'coupon_operations',
            'coupon_updated': 'coupon_operations',
            'coupon_deleted': 'coupon_operations',
            # Payment operations
            'payment_gateway_updated': 'payment_operations',
            # Reward operations
            'reward_points_adjusted': 'reward_operations',
            'reward_points_earned': 'reward_operations',
            # Email operations
            'email_sent': 'email_operations',
            'email_failed': 'email_operations',
            # System operations
            'system_alert': 'system_operations',
            'inventory_alert': 'system_operations',
            # Customer operations
            'customer_registered': 'customer_operations',
            'customer_updated': 'customer_operations',
        }
        
        # Get the grouped preference type
        preference_type = type_mapping.get(notification_type)
        if not preference_type:
            # If not mapped, check for exact match (e.g., 'revenue_alerts')
            preference_type = notification_type
        
        # Check notification_preferences table
        query = text("""
            SELECT is_enabled
            FROM notification_preferences
            WHERE user_id = :user_id AND notification_type = :notification_type
            LIMIT 1
        """)
        result = db.session.execute(query, {
            'user_id': admin_id,
            'notification_type': preference_type
        }).fetchone()
        
        print(f"[NOTIFICATION CHECK] Query result for user {admin_id}, type '{preference_type}': {result}")
        
        # If preference exists, return its value (default True if None)
        if result:
            is_enabled = bool(result[0]) if result[0] is not None else True
            print(f"[NOTIFICATION CHECK] Preference found: is_enabled = {is_enabled}")
            return is_enabled
        
        # If preference doesn't exist, default to True (notifications enabled by default)
        print(f"[NOTIFICATION CHECK] No preference found, defaulting to True (enabled)")
        return True
        
    except Exception as e:
        print(f"[NOTIFICATION] Error checking notification preference: {str(e)}")
        # Default to True if there's an error
        return True

def get_current_admin_id():
    """
    Helper function to get current admin ID from JWT token.
    Returns None if not available.
    """
    try:
        current_user_id = get_jwt_identity()
        admin_id = None
        if isinstance(current_user_id, str) and current_user_id.startswith('admin_'):
            admin_id = int(current_user_id.replace('admin_', ''))
        elif isinstance(current_user_id, int):
            admin_id = current_user_id
        return admin_id
    except Exception as e:
        print(f"[NOTIFICATION] Error getting admin ID: {e}")
        return None

def create_notification(admin_id, notification_type, title, message, priority='medium', metadata=None):
    """
    Create a notification for an admin user if the notification type is enabled.
    
    Args:
        admin_id: The admin user ID (can be None, will try to get from JWT)
        notification_type: The notification type (e.g., 'product_created', 'order_updated')
        title: Notification title
        message: Notification message
        priority: Notification priority ('low', 'medium', 'high')
        metadata: Optional JSON metadata
    
    Returns:
        bool: True if notification was created, False otherwise
    """
    try:
        # If admin_id is None, try to get it from JWT
        if admin_id is None:
            admin_id = get_current_admin_id()
            if admin_id is None:
                print(f"[NOTIFICATION] ❌ Cannot create notification: No admin_id available")
                return False
        
        # Check if notification is enabled for this user
        is_enabled = check_notification_enabled(admin_id, notification_type)
        print(f"[NOTIFICATION] Checking if {notification_type} is enabled for admin {admin_id}: {is_enabled}")
        if not is_enabled:
            print(f"[NOTIFICATION] Notification {notification_type} is disabled for admin {admin_id}")
            return False
        
        # Ensure notifications table exists and has all required columns
        try:
            # First, check if table exists and what columns it has
            check_table_query = text("""
                SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES 
                WHERE TABLE_SCHEMA = DATABASE() 
                AND TABLE_NAME = 'notifications'
            """)
            table_exists = db.session.execute(check_table_query).scalar() > 0
            
            if not table_exists:
                print(f"[NOTIFICATION] Notifications table doesn't exist, creating it...")
                create_table_query = text("""
                    CREATE TABLE IF NOT EXISTS notifications (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        user_id INT NOT NULL,
                        notification_type VARCHAR(100) NOT NULL,
                        title VARCHAR(255) NOT NULL,
                        message TEXT NOT NULL,
                        priority VARCHAR(20) DEFAULT 'medium',
                        metadata JSON,
                        is_read TINYINT(1) DEFAULT 0,
                        created_at DATETIME NOT NULL,
                        updated_at DATETIME NOT NULL,
                        INDEX idx_user_id (user_id),
                        INDEX idx_is_read (is_read),
                        INDEX idx_created_at (created_at),
                        INDEX idx_notification_type (notification_type)
                    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
                """)
                db.session.execute(create_table_query)
                db.session.commit()
                print("[NOTIFICATION] ✅ Created notifications table")
            else:
                # Check if updated_at column exists
                check_col_query = text("""
                    SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS 
                    WHERE TABLE_SCHEMA = DATABASE() 
                    AND TABLE_NAME = 'notifications' 
                    AND COLUMN_NAME = 'updated_at'
                """)
                has_updated_at = db.session.execute(check_col_query).scalar() > 0
                
                if not has_updated_at:
                    print("[NOTIFICATION] Adding 'updated_at' column to notifications table...")
                    alter_query = text("ALTER TABLE notifications ADD COLUMN updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP AFTER created_at")
                    db.session.execute(alter_query)
                    db.session.commit()
                    print("[NOTIFICATION] ✅ Added 'updated_at' column")
            
            # Insert notification - try with updated_at first
            try:
                insert_query = text("""
                    INSERT INTO notifications 
                    (user_id, notification_type, title, message, priority, metadata, is_read, created_at, updated_at)
                    VALUES (:user_id, :notification_type, :title, :message, :priority, :metadata, 0, UTC_TIMESTAMP(), UTC_TIMESTAMP())
                """)
                
                metadata_json = None
                if metadata:
                    import json
                    metadata_json = json.dumps(metadata)
                
                db.session.execute(insert_query, {
                    'user_id': admin_id,
                    'notification_type': notification_type,
                    'title': title,
                    'message': message,
                    'priority': priority,
                    'metadata': metadata_json
                })
                
                db.session.commit()
                print(f"[NOTIFICATION] ✅ Created notification: {notification_type} for admin {admin_id}")
                print(f"[NOTIFICATION] ✅ Notification details: title='{title}', message='{message[:50]}...'")
                return True
            except Exception as insert_err:
                # If updated_at column doesn't exist, try without it
                if 'updated_at' in str(insert_err) or 'Unknown column' in str(insert_err):
                    print("[NOTIFICATION] Retrying insert without updated_at column...")
                    db.session.rollback()
                    insert_query = text("""
                        INSERT INTO notifications 
                        (user_id, notification_type, title, message, priority, metadata, is_read, created_at)
                        VALUES (:user_id, :notification_type, :title, :message, :priority, :metadata, 0, UTC_TIMESTAMP())
                    """)
                    
                    metadata_json = None
                    if metadata:
                        import json
                        metadata_json = json.dumps(metadata)
                    
                    db.session.execute(insert_query, {
                        'user_id': admin_id,
                        'notification_type': notification_type,
                        'title': title,
                        'message': message,
                        'priority': priority,
                        'metadata': metadata_json
                    })
                    
                    db.session.commit()
                    print(f"[NOTIFICATION] ✅ Created notification (without updated_at): {notification_type} for admin {admin_id}")
                    return True
                else:
                    raise insert_err
            
        except Exception as table_err:
            db.session.rollback()
            # If table doesn't exist, create it
            if 'doesn\'t exist' in str(table_err).lower() or 'Table' in str(table_err):
                print(f"[NOTIFICATION] Notifications table doesn't exist, creating it...")
                try:
                    create_table_query = text("""
                        CREATE TABLE IF NOT EXISTS notifications (
                            id INT AUTO_INCREMENT PRIMARY KEY,
                            user_id INT NOT NULL,
                            notification_type VARCHAR(100) NOT NULL,
                            title VARCHAR(255) NOT NULL,
                            message TEXT NOT NULL,
                            priority VARCHAR(20) DEFAULT 'medium',
                            metadata JSON,
                            is_read TINYINT(1) DEFAULT 0,
                            created_at DATETIME NOT NULL,
                            updated_at DATETIME NOT NULL,
                            INDEX idx_user_id (user_id),
                            INDEX idx_is_read (is_read),
                            INDEX idx_created_at (created_at),
                            INDEX idx_notification_type (notification_type)
                        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
                    """)
                    db.session.execute(create_table_query)
                    db.session.commit()
                    
                    # Retry insertion
                    metadata_json = None
                    if metadata:
                        import json
                        metadata_json = json.dumps(metadata)
                    
                    db.session.execute(insert_query, {
                        'user_id': admin_id,
                        'notification_type': notification_type,
                        'title': title,
                        'message': message,
                        'priority': priority,
                        'metadata': metadata_json
                    })
                    db.session.commit()
                    print(f"[NOTIFICATION] ✅ Created notification: {notification_type} for admin {admin_id}")
                    return True
                except Exception as create_err:
                    db.session.rollback()
                    print(f"[NOTIFICATION] ❌ Error creating notifications table: {str(create_err)}")
                    return False
            else:
                print(f"[NOTIFICATION] ❌ Error creating notification: {str(table_err)}")
                return False
                
    except Exception as e:
        db.session.rollback()
        print(f"[NOTIFICATION] ❌ Error in create_notification: {str(e)}")
        import traceback
        traceback.print_exc()
        return False

@app.route('/api/admin/notifications', methods=['GET'])
@jwt_required()
def get_admin_notifications():
    """Get admin notifications from the database"""
    try:
        current_user_id = get_jwt_identity()
        # Extract admin ID from JWT identity
        admin_id = None
        if isinstance(current_user_id, str) and current_user_id.startswith('admin_'):
            admin_id = int(current_user_id.replace('admin_', ''))
        elif isinstance(current_user_id, int):
            admin_id = current_user_id
        
        if not admin_id:
            return jsonify({'error': 'Invalid user'}), 401
        
        limit = request.args.get('limit', type=int) or 20
        
        try:
            # Ensure notifications table has all required columns
            try:
                # Check if priority column exists, if not add it
                check_col_query = text("""
                    SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS 
                    WHERE TABLE_SCHEMA = DATABASE() 
                    AND TABLE_NAME = 'notifications' 
                    AND COLUMN_NAME = 'priority'
                """)
                has_priority = db.session.execute(check_col_query).scalar() > 0
                
                if not has_priority:
                    print("[NOTIFICATIONS] Adding 'priority' column to notifications table...")
                    alter_query = text("ALTER TABLE notifications ADD COLUMN priority VARCHAR(20) DEFAULT 'medium' AFTER message")
                    db.session.execute(alter_query)
                    db.session.commit()
                    print("[NOTIFICATIONS] ✅ Added 'priority' column")
            except Exception as alter_err:
                print(f"[NOTIFICATIONS] Warning: Could not check/add priority column: {alter_err}")
                db.session.rollback()
            
            # Query notifications table
            query = text("""
                SELECT id, notification_type, title, message, priority, metadata, is_read, created_at
                FROM notifications
                WHERE user_id = :user_id
                ORDER BY created_at DESC
                LIMIT :limit
            """)
            result = db.session.execute(query, {'user_id': admin_id, 'limit': limit}).fetchall()
            
            notifications = []
            for row in result:
                # Format created_at timestamp - ensure it's ISO format with timezone
                created_at_str = None
                if len(row) > 7 and row[7]:
                    try:
                        from datetime import datetime, timezone
                        created_at_dt = row[7]
                        # If it's a datetime object, ensure it's timezone-aware
                        if isinstance(created_at_dt, datetime):
                            if created_at_dt.tzinfo is None:
                                # Assume UTC if timezone-naive
                                created_at_dt = created_at_dt.replace(tzinfo=timezone.utc)
                            created_at_str = created_at_dt.isoformat()
                        elif isinstance(created_at_dt, str):
                            # If it's already a string, try to parse and reformat
                            try:
                                if 'T' not in created_at_dt:
                                    # MySQL format: YYYY-MM-DD HH:MM:SS
                                    parsed_dt = datetime.strptime(created_at_dt, '%Y-%m-%d %H:%M:%S')
                                    parsed_dt = parsed_dt.replace(tzinfo=timezone.utc)
                                    created_at_str = parsed_dt.isoformat()
                                else:
                                    # Already in ISO format
                                    parsed_dt = datetime.fromisoformat(created_at_dt.replace('Z', '+00:00'))
                                    if parsed_dt.tzinfo is None:
                                        parsed_dt = parsed_dt.replace(tzinfo=timezone.utc)
                                    created_at_str = parsed_dt.isoformat()
                            except:
                                created_at_str = created_at_dt
                        else:
                            created_at_str = str(created_at_dt)
                    except Exception as ts_err:
                        print(f"[GET NOTIFICATIONS] Error formatting created_at: {ts_err}")
                        created_at_str = str(row[7]) if row[7] else None
                
                notifications.append({
                    'id': row[0],
                    'notification_type': row[1],
                    'type': row[1],  # Alias for compatibility
                    'title': row[2],
                    'message': row[3],
                    'priority': row[4] if len(row) > 4 and row[4] else 'medium',
                    'metadata': row[5] if len(row) > 5 else None,
                    'is_read': bool(row[6]) if len(row) > 6 else False,
                    'created_at': created_at_str
                })
            
            # Get unread count
            count_query = text("""
                SELECT COUNT(*) FROM notifications
                WHERE user_id = :user_id AND is_read = 0
            """)
            unread_count = db.session.execute(count_query, {'user_id': admin_id}).scalar() or 0
            
            print(f"[GET NOTIFICATIONS] Returning {len(notifications)} notifications for admin {admin_id}, {unread_count} unread")
            if notifications:
                print(f"[GET NOTIFICATIONS] Latest notification: {notifications[0].get('title', 'N/A')}")
            
            return jsonify({
                'notifications': notifications,
                'unread_count': unread_count
            }), 200
            
        except Exception as query_err:
            # If table doesn't exist, return empty array
            if 'doesn\'t exist' in str(query_err).lower() or 'Table' in str(query_err):
                return jsonify({
                    'notifications': [],
                    'unread_count': 0
                }), 200
            # If column doesn't exist, try to add it and retry
            if 'Unknown column' in str(query_err) and 'priority' in str(query_err):
                print("[NOTIFICATIONS] Priority column missing, attempting to add it...")
                try:
                    alter_query = text("ALTER TABLE notifications ADD COLUMN priority VARCHAR(20) DEFAULT 'medium' AFTER message")
                    db.session.execute(alter_query)
                    db.session.commit()
                    print("[NOTIFICATIONS] ✅ Added 'priority' column, retrying query...")
                    
                    # Retry the query
                    query = text("""
                        SELECT id, notification_type, title, message, priority, metadata, is_read, created_at
                        FROM notifications
                        WHERE user_id = :user_id
                        ORDER BY created_at DESC
                        LIMIT :limit
                    """)
                    result = db.session.execute(query, {'user_id': admin_id, 'limit': limit}).fetchall()
                    
                    notifications = []
                    for row in result:
                        notifications.append({
                            'id': row[0],
                            'notification_type': row[1],
                            'type': row[1],
                            'title': row[2],
                            'message': row[3],
                            'priority': row[4] if len(row) > 4 and row[4] else 'medium',
                            'metadata': row[5] if len(row) > 5 else None,
                            'is_read': bool(row[6]) if len(row) > 6 else False,
                            'created_at': row[7].isoformat() if len(row) > 7 and row[7] else None
                        })
                    
                    count_query = text("""
                        SELECT COUNT(*) FROM notifications
                        WHERE user_id = :user_id AND is_read = 0
                    """)
                    unread_count = db.session.execute(count_query, {'user_id': admin_id}).scalar() or 0
                    
                    return jsonify({
                        'notifications': notifications,
                        'unread_count': unread_count
                    }), 200
                except Exception as retry_err:
                    print(f"[NOTIFICATIONS] Error adding column or retrying: {retry_err}")
                    db.session.rollback()
                    return jsonify({
                        'notifications': [],
                        'unread_count': 0,
                        'warning': 'Table structure issue, please contact admin'
                    }), 200
            raise query_err
            
    except Exception as e:
        print(f"[ERROR] Error getting notifications: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500

