# ==================== UNIFIED TAX & CURRENCY MANAGEMENT ====================

@app.route('/api/tax/rates', methods=['GET'])
@jwt_required(optional=True)
def get_tax_rates():
    """Get all regional tax rates - only returns countries that exist in countries table, removes duplicates"""
    try:
        from sqlalchemy import text
        
        # ✅ CRITICAL: Prioritize TaxCountry.default_tax_rate over Country.default_tax_rate
        # TaxCountry is where Tax Management stores rates, so it should take precedence
        # Only get countries that exist in the countries table
        # Join with countries table to ensure we only return existing countries
        # Remove duplicates by country_code (keep the first one found)
        query = text("""
            SELECT DISTINCT
                c.country_code,
                c.country_name,
                c.currency_code,
                CASE 
                    WHEN tc.default_tax_rate IS NOT NULL THEN tc.default_tax_rate
                    WHEN c.default_tax_rate IS NOT NULL THEN c.default_tax_rate
                    ELSE 0.0
                END as tax_rate,
                COALESCE(tc.is_active, c.is_active, 1) as is_active,
                tc.id as tax_country_id,
                c.id as country_id
            FROM countries c
            LEFT JOIN tax_countries tc ON tc.country_code = c.country_code AND tc.is_active = 1
            WHERE c.is_active = 1
            ORDER BY c.country_name
        """)
        
        results = db.session.execute(query).fetchall()
        
        # Remove duplicates by country_code (in case there are multiple entries)
        seen_country_codes = set()
        data = []
        
        for row in results:
            country_code = row[0]
            if not country_code or country_code in seen_country_codes:
                continue
            seen_country_codes.add(country_code)
            
            tax_rate_value = float(row[3] or 0.0)
            tax_country_id = row[5] if row[5] else None
            
            # ✅ Debug logging for India specifically
            if country_code in ('IND', 'IN'):
                print(f"[GET TAX RATES] {country_code}: tax_rate={tax_rate_value}%, tax_country_id={tax_country_id}")
            
            # ✅ CRITICAL FIX: Only use tax_country_id as 'id', NOT country_id
            # If we use country_id and there's no TaxCountry record, PUT /tax/rates/{id} will fail with 404
            # If tax_country_id is None, we return id=None, which tells frontend to CREATE instead of UPDATE
            tax_country_id = row[5]  # This is the actual TaxCountry.id
            data.append({
                'id': tax_country_id,  # ✅ Only use tax_country_id (can be None if no TaxCountry record exists)
                'country_code': country_code,
                'country_name': row[1] or country_code,
                'currency_code': row[2] or '',
                'tax_type': 'GST',
                'tax_name': 'GST',
                'tax_rate': tax_rate_value,
                'is_active': bool(row[4]) if row[4] is not None else True,
                'country_id': row[6]  # Include country_id separately for reference (not used for updates)
            })
        
        return jsonify({
            'success': True,
            'data': {'taxes': data}
        }), 200
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({
            'success': False,
            'message': f"Error fetching tax rates: {str(e)}"
        }), 500

@app.route('/api/tax/rates', methods=['POST'])
@jwt_required()
def create_tax_rate():
    """Create a new regional tax rate"""
    try:
        data = request.get_json() or {}
        country_code = (data.get('country_code') or '').upper()
        country_name = data.get('country_name') or country_code
        tax_rate = float(data.get('tax_rate') or 0.0)
        tax_name = data.get('tax_name', 'GST')
        
        if not country_code:
            return jsonify({'success': False, 'message': 'country_code is required'}), 400
        
        # ✅ CRITICAL: Normalize country code to 3-letter format
        country_code_normalized = normalize_country_code_to_3_letter(country_code)
        if country_code_normalized:
            country_code = country_code_normalized
        
        # Get country and currency_code FIRST (before any conditional logic)
        # ✅ Use db.session.query() to avoid any potential variable shadowing issues
        country_obj = db.session.query(Country).filter_by(country_code=country_code).first()
        currency_code = country_obj.currency_code if country_obj else 'INR'
        
        # Check if exists
        existing = TaxCountry.query.filter_by(country_code=country_code).first()
        if existing:
            existing.default_tax_rate = tax_rate
            existing.is_active = True
        else:
            existing = TaxCountry(
                country_code=country_code,
                country_name=country_name,
                currency_code=currency_code,
                default_tax_rate=tax_rate,
                is_active=True
            )
            db.session.add(existing)
        
        # CRITICAL: Sync tax rate to Country table for tax calculation
        if country_obj:
            country_obj.default_tax_rate = tax_rate
            print(f"✅ Synced tax rate {tax_rate}% to Country table for {country_code}")
        else:
            # Create country entry if it doesn't exist
            country_obj = Country(
                country_code=country_code,
                country_name=country_name,
                currency_code=currency_code,
                default_tax_rate=tax_rate,
                is_active=True
            )
            db.session.add(country_obj)
            print(f"✅ Created Country entry for {country_code} with tax rate {tax_rate}%")
        
        db.session.commit()
        
        # Trigger price recalculation for this country
        try:
            from app.services.price_recalculation_service import PriceRecalculationService  # type: ignore
            # ✅ DO NOT import Country here - it's already available at module level
            # Importing it here causes variable shadowing and UnboundLocalError
            
            # Recalculate all products for this country
            result = PriceRecalculationService.recalculate_all_products_for_country(
                country_code, existing.currency_code if hasattr(existing, 'currency_code') else None
            )
            print(f"✅ Triggered price recalculation for country {country_code}: {result.get('success', 0)} products updated")
        except Exception as e:
            print(f"⚠️  Error triggering price recalculation: {str(e)}")
            import traceback
            traceback.print_exc()
            # Don't fail the request if recalculation fails
        
        return jsonify({
            'success': True,
            'data': {'tax': {
                'id': existing.id,
                'country_code': existing.country_code,
                'country_name': existing.country_name,
                'tax_rate': float(existing.default_tax_rate)
            }},
            'message': 'Tax rate saved successfully. Product prices have been recalculated.'
        }), 200
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500

@app.route('/api/tax/category', methods=['POST', 'OPTIONS'])
@jwt_required()
def set_category_tax():
    """Set tax rate for a category - applies to all products in that category"""
    # Handle CORS preflight
    if request.method == 'OPTIONS':
        response = jsonify({'success': True})
        response.headers.add('Access-Control-Allow-Origin', '*')
        response.headers.add('Access-Control-Allow-Headers', 'Content-Type, Authorization')
        response.headers.add('Access-Control-Allow-Methods', 'POST, OPTIONS')
        return response, 200
    
    try:
        data = request.get_json() or {}
        category_id = data.get('category_id')
        category_name = data.get('category_name', '')
        tax_rate = float(data.get('tax_rate') or 0.0)
        
        print(f"\n{'='*60}")
        print(f"💾 SETTING CATEGORY TAX")
        print(f"{'='*60}")
        print(f"Category ID: {category_id}")
        print(f"Category Name: {category_name}")
        print(f"Tax Rate: {tax_rate}%")
        print(f"{'='*60}\n")
        
        if not category_id:
            return jsonify({'success': False, 'message': 'category_id is required'}), 400
        
        # Check if category exists
        from sqlalchemy import text
        category_check = db.session.execute(
            text("SELECT id, name FROM categories WHERE id = :cat_id"),
            {'cat_id': category_id}
        ).fetchone()
        
        if not category_check:
            return jsonify({'success': False, 'message': 'Category not found'}), 404
        
        # Store category tax - try TaxRule model first, fallback to direct product update
        try:
            # Try to use TaxRule model if available
            from app.models import TaxRule  # type: ignore
            existing_rule = TaxRule.query.filter_by(category_id=category_id).first()
            
            if existing_rule:
                existing_rule.tax_value = tax_rate
                existing_rule.updated_at = datetime.utcnow()
                print(f"✅ Updated existing TaxRule for category {category_id}")
            else:
                new_rule = TaxRule(
                    rule_name=f'Tax for {category_name or category_check.name}',
                    category_id=category_id,
                    country_code='IN',  # Default
                    tax_calculation_type='percentage',
                    tax_value=tax_rate,
                    tax_applies_to='product',
                    is_active=True
                )
                db.session.add(new_rule)
                print(f"✅ Created new TaxRule for category {category_id}")
            
            db.session.commit()
            
        except (ImportError, AttributeError) as e:
            print(f"⚠️  TaxRule model not available, using direct product update: {str(e)}")
            # TaxRule model not available, continue with direct product update
        
        # Update all products in this category to have this tax rate
        result = db.session.execute(
            text("""
                UPDATE products 
                SET tax_rate = :tax_rate, updated_at = NOW()
                WHERE category_id = :cat_id
            """),
            {'tax_rate': tax_rate, 'cat_id': category_id}
        )
        updated_products = result.rowcount
        db.session.commit()
        
        print(f"✅ Updated {updated_products} products in category {category_id} with tax rate {tax_rate}%")
        
        # Trigger price recalculation for all products in this category
        try:
            from app.services.price_recalculation_service import PriceRecalculationService  # type: ignore
            from app.models import Country  # type: ignore
            
            # Get all countries
            countries = Country.query.filter_by(is_active=True).all()
            total_recalculated = 0
            
            # Get all products in this category
            products = db.session.execute(
                text("SELECT id FROM products WHERE category_id = :cat_id"),
                {'cat_id': category_id}
            ).fetchall()
            
            for (product_id,) in products:
                for country in countries:
                    try:
                        result = PriceRecalculationService.recalculate_product_price(
                            product_id, country.country_code, country.currency_code
                        )
                        if result.get('success'):
                            total_recalculated += 1
                    except Exception as e:
                        print(f"⚠️  Error recalculating product {product_id} for {country.country_code}: {str(e)}")
            
            print(f"✅ Recalculated prices for {total_recalculated} product-country combinations")
        except Exception as e:
            print(f"⚠️  Error triggering price recalculation: {str(e)}")
            import traceback
            traceback.print_exc()
            # Don't fail the request if recalculation fails
        
        return jsonify({
            'success': True,
            'message': f'Category tax rate set to {tax_rate}% for all products in category. Prices recalculated.',
            'data': {
                'category_id': category_id,
                'category_name': category_name or category_check.name,
                'tax_rate': tax_rate,
                'products_updated': updated_products
            }
        }), 200
            
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        print(f"❌ Error setting category tax: {str(e)}")
        return jsonify({'success': False, 'message': f"Error setting category tax: {str(e)}"}), 500

@app.route('/api/tax/rates/<int:tax_id>', methods=['PUT'])
@jwt_required()
def update_tax_rate(tax_id):
    """Update a tax rate - synced with DB"""
    try:
        tax = TaxCountry.query.get(tax_id)
        if not tax:
            return jsonify({'success': False, 'message': 'Tax rate not found'}), 404
        
        data = request.get_json() or {}
        
        # ✅ CRITICAL: Normalize country_code if provided (e.g., 'IN' -> 'IND')
        if 'country_code' in data:
            normalized_country_code = normalize_country_code_to_3_letter(data['country_code'])
            if normalized_country_code and normalized_country_code != tax.country_code:
                print(f"[Tax Update] Normalizing country_code: {data['country_code']} -> {normalized_country_code}")
                tax.country_code = normalized_country_code
        
        if 'tax_rate' in data:
            new_tax_rate = float(data['tax_rate'])
            old_tax_rate = tax.default_tax_rate
            tax.default_tax_rate = new_tax_rate
            print(f"[Tax Update] TaxCountry ID {tax_id} ({tax.country_code}): {old_tax_rate}% -> {new_tax_rate}%")
            
            # CRITICAL: Sync tax rate to Country table for tax calculation
            # ✅ Fixed: Use country_obj to avoid any potential variable shadowing
            country_obj = db.session.query(Country).filter_by(country_code=tax.country_code).first()
            if country_obj:
                country_obj.default_tax_rate = new_tax_rate
                print(f"✅ Synced updated tax rate {new_tax_rate}% to Country table for {tax.country_code}")
            else:
                # Create country entry if it doesn't exist
                country_obj = Country(
                    country_code=tax.country_code,
                    country_name=tax.country_name,
                    currency_code=tax.currency_code if hasattr(tax, 'currency_code') else 'INR',
                    default_tax_rate=new_tax_rate,
                    is_active=True
                )
                db.session.add(country_obj)
                print(f"✅ Created Country entry for {tax.country_code} with tax rate {new_tax_rate}%")
        if 'tax_name' in data:
            pass  # Not stored in TaxCountry model
        if 'is_active' in data:
            tax.is_active = bool(data['is_active'])
        
        db.session.commit()
        print(f"[Tax Update] ✅ Successfully updated tax rate for {tax.country_code}")
        
        # ✅ Verify the update was saved correctly by querying immediately
        db.session.refresh(tax)  # Refresh from DB to ensure we have latest values
        verify_tax = TaxCountry.query.get(tax_id)
        if verify_tax:
            print(f"[Tax Update] ✅ Verification: TaxCountry ID {tax_id} now has tax_rate={verify_tax.default_tax_rate}% for {verify_tax.country_code}")
        
        # Trigger price recalculation for this country
        try:
            # Optional import - may not be available in all setups
            # ✅ Fixed: Don't import Country here - it's already available at module level
            # Importing it here causes variable shadowing issues
            try:
                from app.services.price_recalculation_service import PriceRecalculationService  # type: ignore
                # Don't import Country - it's already defined in this module
                
                # Recalculate all products for this country
                result = PriceRecalculationService.recalculate_all_products_for_country(
                    tax.country_code, tax.currency_code if hasattr(tax, 'currency_code') else None
                )
                print(f"✅ Triggered price recalculation for country {tax.country_code}: {result.get('success', 0)} products updated")
            except ImportError:
                # Service not available, skip recalculation
                print("⚠️  Price recalculation service not available")
                pass
        except Exception as e:
            print(f"⚠️  Error triggering price recalculation: {str(e)}")
            import traceback
            traceback.print_exc()
        
        # ✅ Return the updated tax data so frontend can use it immediately
        final_tax_rate = verify_tax.default_tax_rate if verify_tax else tax.default_tax_rate
        return jsonify({
            'success': True,
            'message': 'Tax rate updated successfully',
            'data': {
                'id': tax.id,
                'country_code': tax.country_code,
                'country_name': tax.country_name,
                'tax_rate': float(final_tax_rate),
                'tax_type': 'GST',
                'tax_name': 'GST',
                'is_active': tax.is_active
            }
        }), 200
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500

