@app.route('/api/tax/settings', methods=['POST'])
@jwt_required()
def update_tax_settings():
    """Update tax settings - Stores in app_settings table"""
    try:
        from sqlalchemy import text
        
        data = request.get_json() or {}
        current_user = get_jwt_identity()
        # For global settings, use NULL user_id so they apply to all users
        user_id = None  # Use NULL for global tax settings
        
        print(f"[TAX SETTINGS POST] Received data: {data}")
        print(f"[TAX SETTINGS POST] Current user: {current_user}, user_id: {user_id}")
        
        # Ensure app_settings table exists (create if not exists)
        try:
            db.session.execute(text("""
                CREATE TABLE IF NOT EXISTS app_settings (
                    id INT PRIMARY KEY AUTO_INCREMENT,
                    setting_key VARCHAR(100) NOT NULL,
                    setting_value TEXT,
                    setting_type VARCHAR(20) DEFAULT 'string',
                    category VARCHAR(50) DEFAULT 'general',
                    user_id INT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    UNIQUE KEY unique_setting (setting_key, category, user_id),
                    INDEX idx_category (category),
                    INDEX idx_user_id (user_id)
                )
            """))
            db.session.commit()
            print("[TAX SETTINGS POST] ✅ app_settings table created/verified")
        except Exception as e:
            db.session.rollback()
            print(f"[TAX SETTINGS POST] ⚠️  Could not create app_settings table (might already exist): {str(e)}")
            # Continue anyway - table might already exist
        
        # Settings to save - map frontend field names to database keys
        settings_to_save = {
            'tax_inclusive_pricing': str(data.get('tax_inclusive_pricing', False)).lower(),
            'show_tax_on_product_pages': str(data.get('show_tax_on_product', data.get('show_tax_on_product_pages', True))).lower(),
            'show_tax_in_cart': str(data.get('show_tax_in_cart', True)).lower(),
            'automatic_tax_calculation': str(data.get('automatic_tax_calculation', True)).lower()
        }
        
        print(f"[TAX SETTINGS POST] Settings to save: {settings_to_save}")
        
        # Save each setting
        saved_count = 0
        for key, value in settings_to_save.items():
            try:
                # First, try to delete existing setting for this key/category/user_id combo
                # This handles the case where user_id is NULL
                delete_query = text("""
                    DELETE FROM app_settings 
                    WHERE setting_key = :key 
                    AND category = 'tax' 
                    AND (user_id = :user_id OR (user_id IS NULL AND :user_id IS NULL))
                """)
                db.session.execute(delete_query, {'key': key, 'user_id': user_id})
                
                # Then insert the new value
                insert_query = text("""
                    INSERT INTO app_settings (setting_key, setting_value, setting_type, category, user_id)
                    VALUES (:key, :value, 'boolean', 'tax', :user_id)
                """)
                db.session.execute(insert_query, {
                    'key': key,
                    'value': value,
                    'user_id': user_id
                })
                saved_count += 1
                print(f"[TAX SETTINGS POST] ✅ Saved setting: {key} = {value}")
            except Exception as e:
                print(f"[TAX SETTINGS POST] ❌ Error saving {key}: {str(e)}")
                db.session.rollback()
                # Try alternative approach with REPLACE or UPDATE
                try:
                    # Try REPLACE instead
                    replace_query = text("""
                        REPLACE INTO app_settings (setting_key, setting_value, setting_type, category, user_id)
                        VALUES (:key, :value, 'boolean', 'tax', :user_id)
                    """)
                    db.session.execute(replace_query, {
                        'key': key,
                        'value': value,
                        'user_id': user_id
                    })
                    saved_count += 1
                    print(f"[TAX SETTINGS POST] ✅ Saved setting (REPLACE): {key} = {value}")
                except Exception as e2:
                    print(f"[TAX SETTINGS POST] ❌ REPLACE also failed for {key}: {str(e2)}")
        
        db.session.commit()
        print(f"[TAX SETTINGS POST] ✅ Committed {saved_count} settings to database")
        
        return jsonify({
            'success': True,
            'message': f'Tax settings saved successfully ({saved_count} settings saved)',
            'data': {
                'tax_inclusive_pricing': settings_to_save['tax_inclusive_pricing'] == 'true',
                'show_tax_on_product': settings_to_save['show_tax_on_product_pages'] == 'true',
                'show_tax_in_cart': settings_to_save['show_tax_in_cart'] == 'true',
                'automatic_tax_calculation': settings_to_save['automatic_tax_calculation'] == 'true'
            }
        }), 200
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        print(f"[TAX SETTINGS POST] ❌ Error: {str(e)}")
        return jsonify({'success': False, 'message': f'Failed to save tax settings: {str(e)}'}), 500

