@app.route('/api/tax/exemptions', methods=['POST'])
@jwt_required()
def update_tax_exemptions():
    """Update tax exemptions (mark products as tax-exempt or taxable)"""
    try:
        data = request.get_json() or {}
        product_ids = data.get('product_ids', [])
        is_exempt = data.get('is_exempt', True)
        
        if not product_ids:
            return jsonify({'success': False, 'message': 'product_ids is required'}), 400
        
        # Use raw SQL to update products safely
        from sqlalchemy import text
        is_taxable_value = 0 if is_exempt else 1
        
        update_query = text("""
            UPDATE products
            SET is_taxable = :is_taxable, updated_at = NOW()
            WHERE id IN :product_ids
        """)
        
        result = db.session.execute(update_query, {
            'is_taxable': is_taxable_value,
            'product_ids': tuple(product_ids)
        })
        updated = result.rowcount
        db.session.commit()
        
        return jsonify({
            'success': True,
            'message': f'Updated {updated} products',
            'data': {
                'updated_count': updated
            }
        }), 200
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        print(f"[Tax Exemptions Update Error] {str(e)}")
        return jsonify({'success': False, 'message': str(e)}), 500

@app.route('/api/tax/countries-from-currencies', methods=['GET'])
@jwt_required()
def get_countries_from_currencies():
    """Get countries that exist in the database for tax management - only returns existing countries, removes duplicates by normalizing codes"""
    try:
        from sqlalchemy import text
        
        # Normalize country codes: map 2-letter to 3-letter codes for consistency
        def normalize_country_code(code):
            if not code:
                return None
            code_upper = code.upper().strip()
            # Map 2-letter codes to 3-letter codes (prefer 3-letter ISO standard)
            code_map = {
                'AU': 'AUS', 'IN': 'IND', 'US': 'USA', 'GB': 'GBR', 'CA': 'CAN',
                'JP': 'JPN', 'CN': 'CHN', 'BR': 'BRA', 'SG': 'SGP', 'CH': 'CHE',
                'ZA': 'ZAF', 'NZ': 'NZL', 'AE': 'ARE', 'SA': 'SAU', 'DE': 'DEU',
                'FR': 'FRA', 'IT': 'ITA', 'ES': 'ESP', 'NL': 'NLD', 'BE': 'BEL',
                'AT': 'AUT', 'SE': 'SWE', 'NO': 'NOR', 'DK': 'DNK', 'FI': 'FIN',
                'PL': 'POL', 'CZ': 'CZE', 'HU': 'HUN', 'RO': 'ROU', 'GR': 'GRC',
                'PT': 'PRT', 'IE': 'IRL', 'MX': 'MEX', 'AR': 'ARG', 'CL': 'CHL',
                'CO': 'COL', 'PE': 'PER', 'KR': 'KOR', 'TH': 'THA', 'MY': 'MYS',
                'ID': 'IDN', 'PH': 'PHL', 'VN': 'VNM', 'IL': 'ISR', 'EG': 'EGY',
                'PK': 'PAK', 'BD': 'BGD', 'LK': 'LKA', 'NP': 'NPL'
            }
            # If it's a 2-letter code, convert to 3-letter
            if len(code_upper) == 2 and code_upper in code_map:
                return code_map[code_upper]
            # If it's already 3-letter or other, return as-is
            return code_upper
        
        # Get all countries from the countries table that are active
        countries_query = text("""
            SELECT 
                c.country_code, 
                c.country_name, 
                c.currency_code, 
                c.default_tax_rate, 
                c.is_active,
                c.id
            FROM countries c
            WHERE c.is_active = 1
            ORDER BY c.country_name
        """)
        country_results = db.session.execute(countries_query).fetchall()
        
        # Deduplicate by normalized country code (AU and AUS become AUS, etc.)
        seen_normalized_codes = {}
        countries_data = []
        
        for row in country_results:
            original_code = row[0]
            if not original_code:
                continue
            
            # Normalize the code
            normalized_code = normalize_country_code(original_code)
            
            # Skip if we've already seen this normalized code
            if normalized_code in seen_normalized_codes:
                continue
            
            # Mark as seen
            seen_normalized_codes[normalized_code] = True
            
            country_name = row[1] or original_code
            currency_code = row[2]
            default_tax_rate = float(row[3] or 0.0) if row[3] is not None else 0.0
            is_active = bool(row[4]) if row[4] is not None else True
            country_id = row[5]
            
            # Get tax rate from TaxCountry table - check both original and normalized codes
            tax_check = db.session.execute(
                text("""
                    SELECT default_tax_rate, country_code 
                    FROM tax_countries 
                    WHERE (country_code = :code1 OR country_code = :code2) 
                    AND is_active = 1 
                    LIMIT 1
                """),
                {'code1': original_code, 'code2': normalized_code}
            ).fetchone()
            
            if tax_check and tax_check[0] is not None:
                tax_rate = float(tax_check[0])
            else:
                tax_rate = default_tax_rate
            
            # Use normalized code for consistency
            countries_data.append({
                'id': country_id,
                'country_code': normalized_code,  # Use normalized code
                'country_name': country_name,
                'currency_code': currency_code,
                'default_tax_rate': tax_rate,
                'tax_rate': tax_rate,
                'has_tax_rate': bool(tax_rate and tax_rate > 0),
                'is_active': is_active
            })
        
        # Sort by country name
        countries_data.sort(key=lambda x: x['country_name'])
        
        return jsonify({
            'success': True,
            'data': {
                'countries': countries_data
            }
        }), 200
    except Exception as e:
        db.session.rollback()
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500

