@app.route('/api/product-packs', methods=['POST'])
@app.route('/api/product-packs/', methods=['POST'])
@jwt_required()
def create_product_pack():
    """Create a new product pack"""
    try:
        data = request.get_json()
        
        # Validate required fields
        if not data.get('product_id'):
            return jsonify({'error': 'Product ID is required'}), 400
        if not data.get('name'):
            return jsonify({'error': 'Pack name is required'}), 400
        
        # Check if product exists
        product = Product.query.get(data['product_id'])
        if not product:
            return jsonify({'error': 'Product not found'}), 404
        
        # Create pack
        pack = ProductPack(
            product_id=data['product_id'],
            name=data['name'],
            bottles=data.get('bottles', 1),
            tablets=data.get('tablets', 0),
            months=data.get('months', 1),
            discount_percentage=data.get('discount_percentage', 0),
            badge=data.get('badge'),
            display_order=data.get('display_order', 0),
            is_active=data.get('is_active', True)
        )
        
        db.session.add(pack)
        db.session.flush()  # Flush to get pack.id and load relationships
        
        # Calculate prices after flush so product relationship is available
        pack.calculate_prices()
        
        db.session.commit()
        
        return jsonify({
            'success': True,
            'pack': pack.to_dict()
        }), 201
    except Exception as e:
        db.session.rollback()
        print(f"[ERROR] Failed to create product pack: {str(e)}")
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500

