@app.route('/api/admin/sessions', methods=['GET'])
@jwt_required()
def get_admin_sessions():
    """Get all user sessions (both customer and admin) with filters and pagination"""
    try:
        # Initialize analytics tables if they don't exist
        try:
            init_analytics_tables()
        except Exception as init_err:
            print(f"[WARNING] Could not initialize analytics tables: {init_err}")
        
        # Get session timeout from settings (in minutes)
        timeout_minutes = get_session_timeout_minutes()
        
        # Get query parameters
        limit = request.args.get('limit', 50, type=int)
        offset = request.args.get('offset', 0, type=int)
        actor_type = request.args.get('actor_type', '')  # 'customer' or 'admin'
        session_type = request.args.get('session_type', '')  # Filter by session type if needed
        is_active = request.args.get('is_active', '')
        user_id = request.args.get('user_id', '')
        
        # Build query to get sessions ONLY from user_sessions table
        # All sessions (admin, customer, guest) are tracked in user_sessions table
        # Differentiate customers from users: customers are users who have placed orders
        query_base = """
            SELECT 
                us.id,
                us.session_id,
                us.user_id,
                us.ip_address,
                us.user_agent,
                us.device_type,
                us.browser,
                us.os,
                COALESCE(us.login_at, us.entry_time) as login_at,
                COALESCE(us.last_seen_at, us.last_activity) as last_seen_at,
                us.last_activity as last_activity,
                us.entry_time as created_at,
                us.last_activity as updated_at,
                CASE 
                    -- CRITICAL: user_id = 1 is always admin (System Administrator)
                    WHEN us.user_id = 1 THEN 'admin'
                    WHEN COALESCE(us.user_type, 'user') = 'admin' THEN 'admin'
                    WHEN us.session_id LIKE 'admin_session_%' THEN 'admin'
                    WHEN COALESCE(us.user_type, 'user') = 'guest' THEN 'guest'
                    WHEN COALESCE(us.user_type, 'user') = 'customer' THEN 'customer'
                    WHEN us.user_id IS NOT NULL AND EXISTS (
                        SELECT 1 FROM orders o WHERE o.user_id = us.user_id LIMIT 1
                    ) THEN 'customer'
                    WHEN COALESCE(us.user_type, 'user') = 'user' THEN 'user'
                    ELSE 'user'
                END as actor_type,
                CASE 
                    -- CRITICAL: user_id = 1 is always admin (System Administrator)
                    WHEN us.user_id = 1 THEN 'admin'
                    WHEN COALESCE(us.user_type, 'user') = 'admin' THEN 'admin'
                    WHEN us.session_id LIKE 'admin_session_%' THEN 'admin'
                    WHEN COALESCE(us.user_type, 'user') = 'guest' THEN 'guest'
                    WHEN COALESCE(us.user_type, 'user') = 'customer' THEN 'customer'
                    WHEN us.user_id IS NOT NULL AND EXISTS (
                        SELECT 1 FROM orders o WHERE o.user_id = us.user_id LIMIT 1
                    ) THEN 'customer'
                    ELSE 'user'
                END as user_type,
                CASE 
                    WHEN us.session_id LIKE 'admin_session_%' THEN 'admin'
                    WHEN us.session_id LIKE 'session_%' AND us.user_id IS NULL THEN 'site'
                    WHEN us.session_id LIKE 'session_%' AND us.user_id IS NOT NULL THEN 'site'
                    ELSE 'site'
                END as session_type,
                CASE 
                    WHEN COALESCE(us.terminated_by_admin, 0) = 1 THEN 0
                    WHEN us.last_activity > DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE) THEN 1 
                    ELSE 0 
                END as is_active,
                COALESCE(us.terminated_by_admin, 0) as terminated_by_admin,
                us.terminated_at,
                COALESCE(us.expires_at, DATE_ADD(us.last_activity, INTERVAL :timeout_minutes MINUTE)) as expires_at,
                COALESCE(us.pages_viewed, 0) as pages_viewed,
                COALESCE(us.time_spent_seconds, 0) as time_spent_seconds,
                us.landing_page,
                us.current_page
            FROM user_sessions us
            WHERE 1=1
        """
        
        params = {'timeout_minutes': timeout_minutes}
        
        # Debug: Log filter parameters
        print(f"[FILTERS] Applied filters: actor_type={actor_type}, session_type={session_type}, is_active={is_active}, user_id={user_id}")
        
        # Apply filters - use the EXACT SAME logic as the CASE statement for actor_type
        # This ensures filters match what's displayed in the frontend
        # The CASE statement priority: user_id=1 > admin > guest > customer (with orders) > user
        if actor_type and actor_type.lower() == 'customer':
            # Only customer sessions - match the CASE logic exactly:
            # user_type='customer' OR (user_id IS NOT NULL AND has orders AND NOT admin)
            query_base += """ AND (
                COALESCE(us.user_type, 'user') = 'customer' 
                OR (
                    us.user_id IS NOT NULL 
                    AND us.user_id != 1 
                    AND us.session_id NOT LIKE 'admin_session_%'
                    AND COALESCE(us.user_type, 'user') != 'admin'
                    AND EXISTS (SELECT 1 FROM orders o WHERE o.user_id = us.user_id LIMIT 1)
                )
            )"""
        elif actor_type and actor_type.lower() == 'admin':
            # Only admin sessions - match the CASE logic exactly:
            # user_id=1 OR user_type='admin' OR admin_session_ pattern
            query_base += """ AND (
                us.user_id = 1 
                OR COALESCE(us.user_type, 'user') = 'admin' 
                OR us.session_id LIKE 'admin_session_%'
            )"""
        elif actor_type and actor_type.lower() == 'guest':
            # Only guest sessions - match the CASE logic exactly:
            # user_type='guest' AND user_id IS NULL (guests have no user_id)
            query_base += """ AND (
                COALESCE(us.user_type, 'user') = 'guest' 
                AND us.user_id IS NULL
                AND us.session_id NOT LIKE 'admin_session_%'
            )"""
        elif actor_type and actor_type.lower() == 'user':
            # Only user sessions - match the CASE logic exactly:
            # user_type='user' AND NOT admin AND NOT customer AND NOT guest
            query_base += """ AND (
                COALESCE(us.user_type, 'user') = 'user' 
                AND us.user_id IS NOT NULL
                AND us.user_id != 1
                AND us.session_id NOT LIKE 'admin_session_%'
                AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = us.user_id LIMIT 1)
            )"""
        
        # Apply session_type filter
        if session_type:
            if session_type.lower() == 'admin':
                query_base += " AND us.session_id LIKE 'admin_session_%'"
            elif session_type.lower() == 'site':
                query_base += " AND (us.session_id LIKE 'session_%' OR us.session_id NOT LIKE 'admin_session_%')"
        
        if user_id:
            query_base += " AND us.user_id = :user_id"
            params['user_id'] = int(user_id)
        
        if is_active != '':
            # Handle both string and boolean values: 'true', '1', 'True', true, 1, etc.
            is_active_bool = (
                is_active == '1' or 
                is_active.lower() == 'true' or 
                is_active.lower() == '1' or
                (isinstance(is_active, bool) and is_active) or
                (isinstance(is_active, int) and is_active == 1)
            )
            if is_active_bool:
                query_base += " AND us.last_activity > DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE) AND COALESCE(us.terminated_by_admin, 0) = 0"
            else:
                query_base += " AND (us.last_activity <= DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE) OR COALESCE(us.terminated_by_admin, 0) = 1)"
        
        # Preserve a copy without pagination for stats queries
        stats_base_query = query_base
        
        # Get total count - use the same query structure (without pagination) to ensure consistency
        count_query_str = f"SELECT COUNT(*) as total FROM ({stats_base_query}) as subquery"
        count_query = text(count_query_str)
        total_result = db.session.execute(count_query, params).fetchone()
        total = total_result[0] if total_result else 0
        
        # Add pagination for the main sessions query
        paginated_query = stats_base_query + " ORDER BY us.last_activity DESC LIMIT :limit OFFSET :offset"
        params['limit'] = limit
        params['offset'] = offset
        
        # Convert to text object and execute query
        sessions_query = text(paginated_query)
        print(f"[FILTERS] Executing query with params: {params}")
        print(f"[FILTERS] Query will return max {limit} sessions starting at offset {offset}")
        sessions_result = db.session.execute(sessions_query, params).fetchall()
        print(f"[FILTERS] Query returned {len(sessions_result)} sessions")
        
        # Convert to list of dictionaries
        sessions = []
        for row in sessions_result:
            # Helper function to safely format timestamps
            def safe_format_ts(ts):
                if not ts:
                    return {'utc': None, 'display': None}
                try:
                    return format_timestamp(ts)
                except Exception:
                    pass
                    # If format_timestamp fails, return ISO format
                    return {'utc': ts.isoformat() if hasattr(ts, 'isoformat') else str(ts), 'display': str(ts)}
            
            session_dict = {
                'id': row[0],
                'session_id': row[1],
                'user_id': row[2],
                'ip_address': row[3],
                'user_agent': row[4],
                'device_type': row[5],
                'browser': row[6],
                'os': row[7],
                'login_at': safe_format_ts(row[8])['utc'],
                'login_at_display': safe_format_ts(row[8])['display'],
                'last_seen_at': safe_format_ts(row[9])['utc'],
                'last_seen_at_display': safe_format_ts(row[9])['display'],
                'last_activity': safe_format_ts(row[10])['utc'] if len(row) > 10 and row[10] else None,
                'created_at': safe_format_ts(row[11])['utc'],
                'updated_at': safe_format_ts(row[12])['utc'],
                'actor_type': row[13] if len(row) > 13 else 'user',  # Fixed: was row[12], should be row[13]
                'user_type': row[14] if len(row) > 14 else 'user',  # Fixed: was row[13], should be row[14]
                'session_type': row[15] if len(row) > 15 else 'site',  # Fixed: was row[14], should be row[15]
                'is_active': bool(row[16]) if len(row) > 16 else False,  # Fixed: was row[15], should be row[16]
                'terminated_by_admin': bool(row[17]) if len(row) > 17 else False,  # Fixed: was row[16], should be row[17]
                'terminated_at': safe_format_ts(row[18])['utc'] if len(row) > 18 and row[18] else None,  # Fixed: was row[17], should be row[18]
                'terminated_at_display': safe_format_ts(row[18])['display'] if len(row) > 18 and row[18] else None,
                'expires_at': safe_format_ts(row[19])['utc'] if len(row) > 19 and row[19] else None,  # Fixed: was row[18], should be row[19]
                'expires_at_display': safe_format_ts(row[19])['display'] if len(row) > 19 and row[19] else None,
                'pages_viewed': row[20] or 0 if len(row) > 20 else 0,  # Fixed: was row[19], should be row[20]
                'time_spent_seconds': row[21] or 0 if len(row) > 21 else 0,  # Fixed: was row[20], should be row[21]
                'landing_page': row[22] if len(row) > 22 else None,  # Fixed: was row[21], should be row[22]
                'current_page': row[23] if len(row) > 23 else None  # Fixed: was row[22], should be row[23]
            }
            sessions.append(session_dict)
        
        # Get user information for sessions (admin, customer, and guest)
        for session in sessions:
            if session['actor_type'] == 'guest':
                # Guest session - no user_id
                session['user'] = None
                session['user_name'] = 'Guest Session'
            elif session['user_id']:
                try:
                    if session['actor_type'] == 'admin':
                        # Get admin user info
                        admin_user = db.session.query(AdminUser).filter_by(id=session['user_id']).first()
                        if admin_user:
                            session['user'] = {
                                'id': admin_user.id,
                                'name': admin_user.full_name or admin_user.username or admin_user.email,
                                'email': admin_user.email,
                                'username': admin_user.username
                            }
                            session['user_name'] = admin_user.full_name or admin_user.username or admin_user.email
                    else:
                        # Get customer user info
                        user = db.session.query(User).filter_by(id=session['user_id']).first()
                        if user:
                            session['user'] = {
                                'id': user.id,
                                'name': user.full_name or user.email,
                                'email': user.email
                            }
                            session['user_name'] = user.full_name or user.email
                except Exception as e:
                    print(f"[WARNING] Failed to get user info for session {session['id']}: {e}")
                    pass
        
        # Cleanup expired sessions before calculating stats
        cleanup_expired_sessions()
        
        # Fix existing admin sessions in database for better visibility in phpMyAdmin
        #  - Ensure user_type = 'admin' and (when possible) role = 'admin'
        #  - Try to keep is_active column (if exists) in sync with termination/expiration rules
        try:
            # Attempt full update including legacy 'role' and 'is_active' columns if they exist
            fix_admin_sessions_query = text("""
                UPDATE user_sessions 
                SET 
                    user_type = 'admin',
                    -- Legacy role column (older schemas) - safe to ignore if it doesn't exist
                    role = 'admin',
                    -- Legacy is_active column (older schemas) - recompute from termination/timeout
                    is_active = CASE 
                        WHEN COALESCE(terminated_by_admin, 0) = 1 
                             OR last_activity <= DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE)
                        THEN 0 
                        ELSE 1 
                    END,
                    updated_at = UTC_TIMESTAMP()
                WHERE (user_id = 1 OR session_id LIKE 'admin_session_%')
            """)
            fix_result = db.session.execute(fix_admin_sessions_query, {'timeout_minutes': timeout_minutes})
            db.session.commit()
            if fix_result.rowcount > 0:
                print(f"[FIX] Updated {fix_result.rowcount} admin session(s) with correct admin flags (user_type/role/is_active)")
        except Exception as fix_err:
            # If legacy columns (role/is_active) don't exist, fall back to updating only user_type
            db.session.rollback()
            try:
                fallback_fix_query = text("""
                    UPDATE user_sessions 
                    SET user_type = 'admin',
                        updated_at = UTC_TIMESTAMP()
                    WHERE (user_id = 1 OR session_id LIKE 'admin_session_%')
                    AND COALESCE(user_type, 'user') != 'admin'
                """)
                fix_result = db.session.execute(fallback_fix_query)
                db.session.commit()
                if fix_result.rowcount > 0:
                    print(f"[FIX] Updated {fix_result.rowcount} admin session(s) with correct user_type='admin' (fallback)")
            except Exception as fallback_err:
                db.session.rollback()
                print(f"[WARNING] Failed to fix admin sessions (both primary and fallback): {fix_err} | {fallback_err}")
        
        # Calculate stats - ensure stats subquery has no pagination placeholders
        stats_base_query_no_pagination = stats_base_query.split(" ORDER BY us.last_activity DESC LIMIT :limit OFFSET :offset")[0]
        
        stats_query_str = f"""
            SELECT 
                COUNT(*) as total_sessions,
                SUM(CASE WHEN COALESCE(terminated_by_admin, 0) = 1 THEN 0 WHEN last_activity > DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE) THEN 1 ELSE 0 END) as active_sessions,
                SUM(CASE WHEN user_id = 1 OR COALESCE(user_type, 'user') = 'admin' OR session_id LIKE 'admin_session_%' THEN 1 ELSE 0 END) as admin_sessions,
                SUM(CASE WHEN (user_id = 1 OR COALESCE(user_type, 'user') = 'admin' OR session_id LIKE 'admin_session_%') AND COALESCE(terminated_by_admin, 0) = 0 AND last_activity > DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE) THEN 1 ELSE 0 END) as active_admin_sessions,
                SUM(CASE WHEN user_id != 1 AND COALESCE(user_type, 'user') = 'user' AND session_id NOT LIKE 'admin_session_%' THEN 1 ELSE 0 END) as user_sessions
            FROM ({stats_base_query_no_pagination}) as stats_subquery
        """
        stats_query = text(stats_query_str)
        # Use same params but without limit/offset
        stats_params = {k: v for k, v in params.items() if k not in ['limit', 'offset']}
        stats_result = db.session.execute(stats_query, stats_params).fetchone()
        
        stats = {
            'total_sessions': int(stats_result[0]) if stats_result and stats_result[0] else 0,
            'active_sessions': int(stats_result[1]) if stats_result and stats_result[1] else 0,
            'admin_sessions': int(stats_result[2]) if stats_result and stats_result[2] else 0,  # Total admin sessions
            'active_admin_sessions': int(stats_result[3]) if stats_result and stats_result[3] else 0,  # Active admin sessions
            'customer_sessions': int(stats_result[4]) if stats_result and len(stats_result) > 4 and stats_result[4] else 0,
            'user_sessions': int(stats_result[5]) if stats_result and len(stats_result) > 5 and stats_result[5] else 0,
            'guest_sessions': int(stats_result[6]) if stats_result and len(stats_result) > 6 and stats_result[6] else 0
        }
        
        return jsonify({
            'success': True,
            'sessions': sessions,
            'total': total,
            'stats': stats
        }), 200
        
    except Exception as e:
        print(f"[ERROR] Failed to fetch sessions: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e),
            'sessions': [],
            'total': 0,
            'stats': {
                'total_sessions': 0,
                'active_sessions': 0,
                'admin_sessions': 0
            }
        }), 500

@app.route('/api/admin/sessions/<int:session_id>/close', methods=['POST'])
@jwt_required()
def close_admin_session(session_id):
    """Force close a user session - if it's the current session, force logout"""
    try:
        # Get current user's identity to check if this is their session
        current_user_id = get_jwt_identity()
        current_admin_id = None
        if current_user_id and isinstance(current_user_id, str) and current_user_id.startswith('admin_'):
            current_admin_id = int(current_user_id.replace('admin_', ''))
        
        # First check if session exists in user_sessions (admin) or customer_sessions
        # Also get the session details to check if it's the current user's session
        # IMPORTANT: select columns in a fixed, documented order so indexes below are correct
        check_query = text("""
            SELECT 
                'user_sessions' as table_name,
                id          AS row_id,
                user_id     AS session_user_id,
                session_id  AS session_token,
                user_type   AS session_user_type
            FROM user_sessions 
            WHERE id = :session_id
            LIMIT 1
        """)
        table_result = db.session.execute(check_query, {'session_id': session_id}).fetchone()
        
        # If not in user_sessions, check customer_sessions
        if not table_result:
            check_customer_query = text("""
                SELECT 
                    'customer_sessions' as table_name,
                    id          AS row_id,
                    user_id     AS session_user_id,
                    session_id  AS session_token,
                    'customer'  AS session_user_type
                FROM customer_sessions 
                WHERE id = :session_id
                LIMIT 1
            """)
            table_result = db.session.execute(check_customer_query, {'session_id': session_id}).fetchone()
        
        if not table_result:
            return jsonify({
                'success': False,
                'error': 'Session not found'
            }), 404
        
        # NOTE: The SELECT order is:
        #   table_name (0), id (1), user_id (2), session_id (3), user_type (4)
        # Map these explicitly to avoid index mistakes.
        table_name = table_result[0]
        session_db_id = table_result[1]
        session_user_id = table_result[2]
        session_session_id = table_result[3] if len(table_result) > 3 else None
        session_user_type = table_result[4] if len(table_result) > 4 else None
        
        # Get current session_id from request if provided
        request_data = request.get_json() if request.is_json else {}
        current_session_id_from_request = request_data.get('current_session_id')
        
        # Try to get current session_id from JWT token if not provided in request
        if not current_session_id_from_request:
            try:
                from flask_jwt_extended import get_jwt
                jwt_data = get_jwt()
                if jwt_data and 'session_id' in jwt_data:
                    current_session_id_from_request = jwt_data['session_id']
                    print(f"[DEBUG] Got session_id from JWT token: {current_session_id_from_request}")
            except:
                pass
        
        # Also try to get from active session in database
        if not current_session_id_from_request and current_admin_id:
            try:
                active_session_query = text("""
                    SELECT session_id
                    FROM user_sessions 
                    WHERE user_id = :user_id 
                    AND user_type = 'admin'
                    AND COALESCE(terminated_by_admin, 0) = 0
                    AND last_activity > DATE_SUB(UTC_TIMESTAMP(), INTERVAL 30 MINUTE)
                    ORDER BY last_activity DESC
                    LIMIT 1
                """)
                active_session_result = db.session.execute(active_session_query, {'user_id': current_admin_id}).fetchone()
                if active_session_result:
                    current_session_id_from_request = active_session_result[0]
                    print(f"[DEBUG] Got session_id from active session: {current_session_id_from_request}")
            except:
                pass
        
        # Check if this is the current user's session
        # CRITICAL: Force logout should ONLY happen when:
        # 1. The session being closed is an ADMIN session (user_type='admin' OR session_id starts with 'admin_session_')
        # 2. The session belongs to the CURRENT admin (user_id matches current_admin_id)
        # 3. The session_id matches the CURRENT active session_id (REQUIRED - admin can have multiple sessions)
        # NEVER force logout for customer/user/guest sessions - they don't have access to admin panel anyway
        is_current_session = False
        print(f"[DEBUG] Session closure check: current_admin_id={current_admin_id}, session_user_id={session_user_id}, session_user_type={session_user_type}, current_session_id_from_request={current_session_id_from_request}, session_session_id={session_session_id}")
        
        # CRITICAL: Only check for forced logout if this is an ADMIN session
        # Customer/user/guest sessions should NEVER trigger forced logout
        is_admin_session = (
            session_user_type == 'admin' or 
            (session_session_id and 'admin_session_' in str(session_session_id))
        )
        
        # ONLY proceed with forced logout check if ALL conditions are met:
        # 1. This is an admin session
        # 2. The current user is an admin
        # 3. The session belongs to the current admin
        # 4. The session_id matches the current active session_id (REQUIRED)
        if is_admin_session and current_admin_id and session_user_id == current_admin_id:
            # CRITICAL: For admin sessions, ONLY force logout if session_id matches the CURRENT active session
            # Do NOT force logout just because user_id matches - admin can have multiple sessions
            # The session_id match is REQUIRED - without it, we cannot determine if it's the current session
            if current_session_id_from_request:
                # If session_id is provided, check if it matches (most reliable)
                if current_session_id_from_request == session_session_id or str(current_session_id_from_request) == str(session_session_id):
                    is_current_session = True
                    print(f"[DEBUG] ✅ Current admin session detected: user_id={current_admin_id}, session_id matches: {session_session_id} - WILL force logout")
                else:
                    print(f"[DEBUG] ❌ Session ID mismatch: request={current_session_id_from_request}, db={session_session_id} - NOT current session, will NOT force logout")
            else:
                # If session_id not provided, we CANNOT reliably determine if it's the current session
                # Do NOT force logout - only close the session silently
                # This prevents accidental logout when closing other admin sessions
                print(f"[DEBUG] ⚠️ No session_id provided in request or JWT - cannot determine if current session. Will NOT force logout for safety.")
                is_current_session = False
        else:
            # This is NOT an admin session, OR it doesn't belong to current admin
            # NEVER force logout for customer/user/guest sessions
            if not is_admin_session:
                print(f"[DEBUG] ❌ Session is NOT admin session (type={session_user_type}) - will NOT force logout")
            elif not current_admin_id:
                print(f"[DEBUG] ❌ Current user is NOT admin - will NOT force logout")
            elif session_user_id != current_admin_id:
                print(f"[DEBUG] ❌ Session belongs to different admin (session_user_id={session_user_id}, current_admin_id={current_admin_id}) - will NOT force logout")
                is_current_session = False
        
        # Update the session to mark it as closed
        # Set last_activity to be expired (31 minutes ago) BUT ensure it's not before entry_time
        # Set terminated_by_admin = 1 to mark as manually terminated
        # This will make is_active = 0 in the query (terminated_by_admin check)
        # CRITICAL: Ensure last_activity is never set to be before entry_time
        close_query = text(f"""
            UPDATE {table_name} 
            SET last_activity = GREATEST(entry_time, DATE_SUB(UTC_TIMESTAMP(), INTERVAL 31 MINUTE)),
                terminated_by_admin = 1,
                terminated_at = UTC_TIMESTAMP(),
                updated_at = UTC_TIMESTAMP()
            WHERE id = :session_id
        """)
        
        result = db.session.execute(close_query, {'session_id': session_id})
        db.session.commit()
        
        print(f"[DEBUG] Closed session {session_id}: rows_affected={result.rowcount}, is_current_session={is_current_session}")
        
        if result.rowcount == 0:
            return jsonify({
                'success': False,
                'error': 'Session not found or already closed'
            }), 404
        
        # If this is the current user's session, return special response to force logout
        if is_current_session:
            print(f"[DEBUG] Returning force_logout for current session {session_id}")
            return jsonify({
                'success': True,
                'message': 'Session closed successfully',
                'force_logout': True,
                'session_expired': True
            }), 200
        
        return jsonify({
            'success': True,
            'message': 'Session closed successfully'
        }), 200
        
    except Exception as e:
        db.session.rollback()
        print(f"[ERROR] Failed to close session: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

# ==================== ADMIN ACTIONS ROUTES ====================

@app.route('/api/admin/actions', methods=['GET'])
@jwt_required()
def get_admin_actions():
    """Get all user actions for activity log - using user_actions table (same as Recent Activity)"""
    try:
        # Get query parameters
        limit = request.args.get('limit', 50, type=int)
        offset = request.args.get('offset', 0, type=int)
        actor_type = request.args.get('actor_type', '')  # 'admin', 'customer', 'guest'
        action_type = request.args.get('action_type', '')  # Filter by action type
        user_id = request.args.get('user_id', '')
        resource_type = request.args.get('resource_type', '')  # From action_details JSON
        resource_id = request.args.get('resource_id', '')
        start_date = request.args.get('start_date', '')
        end_date = request.args.get('end_date', '')
        
        # Build base query for user_actions table (same as Recent Activity in Account Settings)
        base_query = text("""
            SELECT id, user_id, actor_type, action_type, action_details, page_url, ip_address, timestamp
            FROM user_actions
            WHERE 1=1
        """)
        
        params = {}
        conditions = []
        
        # Apply filters
        if actor_type:
            conditions.append("actor_type = :actor_type")
            params['actor_type'] = actor_type
        
        if action_type:
            conditions.append("action_type LIKE :action_type")
            params['action_type'] = f'%{action_type}%'
        
        if user_id:
            conditions.append("user_id = :user_id")
            params['user_id'] = int(user_id) if user_id.isdigit() else user_id
        
        if start_date:
            try:
                start_dt = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
                conditions.append("timestamp >= :start_date")
                params['start_date'] = start_dt
            except Exception:
                pass
        
        if end_date:
            try:
                end_dt = datetime.fromisoformat(end_date.replace('Z', '+00:00'))
                conditions.append("timestamp <= :end_date")
                params['end_date'] = end_dt
            except Exception:
                pass
        
        # Build full query with conditions
        if conditions:
            query_sql = base_query.text + " AND " + " AND ".join(conditions)
        else:
            query_sql = base_query.text
        
        # Add ordering, limit, and offset
        query_sql += " ORDER BY timestamp DESC LIMIT :limit OFFSET :offset"
        params['limit'] = limit
        params['offset'] = offset
        
        try:
            # Execute query with error handling
            try:
                result = db.session.execute(text(query_sql), params).fetchall()
            except Exception as query_err:
                print(f"[ACTIONS] Query error: {query_err}")
                # Try simpler query if complex one fails
                try:
                    simple_query = text("""
                        SELECT id, user_id, actor_type, action_type, action_details, page_url, ip_address, timestamp
                        FROM user_actions
                        ORDER BY timestamp DESC
                        LIMIT :limit OFFSET :offset
                    """)
                    result = db.session.execute(simple_query, {'limit': limit, 'offset': offset}).fetchall()
                    print(f"[ACTIONS] Using simple query, got {len(result)} results")
                except Exception as simple_err:
                    print(f"[ACTIONS] Simple query also failed: {simple_err}")
                    return jsonify({
                        'success': True,
                        'actions': [],
                        'total': 0,
                        'limit': limit,
                        'offset': offset
                    }), 200
            
            # Convert to action format expected by frontend
            actions = []
            for row in result:
                action_id = row[0]
                action_user_id = row[1]
                action_actor_type = row[2]
                action_action_type = row[3]
                action_details_json = row[4]
                action_page_url = row[5]
                action_ip_address = row[6]
                action_timestamp = row[7]
                
                # Parse action_details if it's JSON
                action_details = {}
                resource_type_from_details = ''
                resource_id_from_details = None
                notes = ''
                
                if action_details_json:
                    try:
                        action_details = json.loads(action_details_json) if isinstance(action_details_json, str) else action_details_json
                        resource_type_from_details = action_details.get('resource_type', '')
                        resource_id_from_details = action_details.get('resource_id')
                        notes = action_details.get('notes', '')
                    except:
                        notes = str(action_details_json)
                
                # Apply resource_type and resource_id filters if specified
                if resource_type and resource_type_from_details != resource_type:
                    continue
                if resource_id and resource_id_from_details and str(resource_id_from_details) != str(resource_id):
                    continue
                
                # Map action_type to display-friendly label
                action_label = action_action_type.replace('_', ' ').title()
                if 'LOGIN' in action_action_type:
                    action_label = 'Login' if 'SUCCESS' in action_action_type else 'Login Failed'
                elif 'LOGOUT' in action_action_type:
                    action_label = 'Logout'
                elif 'CREATE' in action_action_type:
                    action_label = 'Created'
                elif 'EDIT' in action_action_type or 'UPDATE' in action_action_type:
                    action_label = 'Updated'
                elif 'DELETE' in action_action_type:
                    action_label = 'Deleted'
                
                # Get resource label
                resource_label = None
                if resource_type_from_details and resource_id_from_details:
                    resource_label = f"{resource_type_from_details.title()} #{resource_id_from_details}"
                
                # Convert timestamp to ISO format with timezone (ensure UTC)
                from datetime import timezone
                if action_timestamp:
                    # Ensure timestamp is timezone-aware (assume UTC if naive)
                    if action_timestamp.tzinfo is None:
                        timestamp_dt = action_timestamp.replace(tzinfo=timezone.utc)
                    else:
                        timestamp_dt = action_timestamp
                    timestamp_str = timestamp_dt.isoformat()
                else:
                    timestamp_str = datetime.now(timezone.utc).isoformat()
                
                action = {
                    'id': action_id,
                    'timestamp': timestamp_str,
                    'user_id': action_user_id or 'system',
                    'actor_type': action_actor_type or 'admin',
                    'action_type': action_action_type,
                    'action_label': action_label,
                    'resource_type': resource_type_from_details or 'unknown',
                    'resource_id': resource_id_from_details,
                    'resource_label': resource_label,
                    'ip_address': action_ip_address or 'N/A',
                    'details': notes or action_page_url or '',
                    'page_url': action_page_url,
                    'action_details': action_details
                }
                actions.append(action)
            
            # Get total count (without limit/offset) - handle errors gracefully
            try:
                count_query = text("""
                    SELECT COUNT(*) FROM user_actions WHERE 1=1
                """)
                if conditions:
                    count_sql = count_query.text + " AND " + " AND ".join(conditions)
                    count_params = {k: v for k, v in params.items() if k not in ['limit', 'offset']}
                else:
                    count_sql = count_query.text
                    count_params = {}
                
                # For resource_type and resource_id filters, we need to check action_details JSON
                # This is more complex, so we'll count from the already fetched results if these filters are used
                if resource_type or resource_id:
                    # Filter actions based on resource_type and resource_id
                    filtered_actions = []
                    for action in actions:
                        if resource_type and action['resource_type'] != resource_type:
                            continue
                        if resource_id and action['resource_id'] and str(action['resource_id']) != str(resource_id):
                            continue
                        filtered_actions.append(action)
                    actions = filtered_actions
                    total = len(actions)
                else:
                    try:
                        total = db.session.execute(text(count_sql), count_params).scalar() or 0
                    except Exception as count_err:
                        print(f"[ACTIONS] Error getting count: {count_err}, using actions length")
                        total = len(actions)
            except Exception as count_total_err:
                print(f"[ACTIONS] Error in count logic: {count_total_err}, using actions length")
                total = len(actions)
                
        except Exception as query_err:
            # Table might not exist or error occurred - try to get at least latest 20 logs
            print(f"[WARNING] Could not query user_actions table: {query_err}")
            import traceback
            traceback.print_exc()
            
            # Fallback: Try to get latest 20 logs with simple query
            try:
                print("[ACTIONS] Attempting fallback query to get latest 20 logs...")
                fallback_query = text("""
                    SELECT id, user_id, actor_type, action_type, action_details, page_url, ip_address, timestamp
                    FROM user_actions
                    ORDER BY timestamp DESC
                    LIMIT 20
                """)
                fallback_result = db.session.execute(fallback_query).fetchall()
                fallback_actions = []
                for row in fallback_result:
                    from datetime import timezone
                    if row[7]:
                        # Ensure timestamp is timezone-aware (assume UTC if naive)
                        if row[7].tzinfo is None:
                            timestamp_dt = row[7].replace(tzinfo=timezone.utc)
                        else:
                            timestamp_dt = row[7]
                        timestamp_str = timestamp_dt.isoformat()
                    else:
                        timestamp_str = datetime.now(timezone.utc).isoformat()
                    action_details = {}
                    try:
                        if row[4]:
                            action_details = json.loads(row[4]) if isinstance(row[4], str) else row[4]
                    except:
                        pass
                    action_label = row[3].replace('_', ' ').title()
                    resource_type = action_details.get('resource_type', 'unknown')
                    resource_id = action_details.get('resource_id')
                    fallback_actions.append({
                        'id': row[0],
                        'timestamp': timestamp_str,
                        'user_id': row[1] or 'system',
                        'actor_type': row[2] or 'admin',
                        'action_type': row[3],
                        'action_label': action_label,
                        'resource_type': resource_type,
                        'resource_id': resource_id,
                        'resource_label': f"{resource_type.title()} #{resource_id}" if resource_type and resource_id else None,
                        'ip_address': row[6] or 'N/A',
                        'details': action_details.get('notes', '') or row[5] or '',
                        'page_url': row[5],
                        'action_details': action_details
                    })
                print(f"[ACTIONS] Fallback query returned {len(fallback_actions)} actions")
                return jsonify({
                    'success': True,
                    'actions': fallback_actions,
                    'total': len(fallback_actions),
                    'limit': 20,
                    'offset': 0,
                    'warning': 'Using fallback query due to error. Showing latest 20 logs only.'
                }), 200
            except Exception as fallback_err:
                print(f"[ACTIONS] Fallback query also failed: {fallback_err}")
                return jsonify({
                    'success': True,
                    'actions': [],
                    'total': 0,
                    'warning': 'Could not retrieve activity logs. Please check database connection.'
                }), 200
        
        # Return actions in expected format
        return jsonify({
            'success': True,
            'actions': actions,
            'total': total
        }), 200
        
    except Exception as e:
        print(f"[ERROR] Failed to get admin actions: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

# ==================== SESSION EXPIRATION CLEANUP ====================

def cleanup_expired_sessions():
    """
    Automatically close sessions that have been inactive for more than the configured timeout.
    This runs on every request to ensure expired sessions are marked as inactive.
    Uses dynamic session timeout from security settings.
    
    Session expiration logic:
    - Sessions expire after configured timeout (default 30 minutes) of inactivity
    - last_activity is updated on every activity, extending expiration
    - When last_activity is older than timeout, session is considered expired
    - Expired sessions are NOT deleted, but marked as inactive (is_active = 0 in query)
    """
    try:
        timeout_minutes = get_session_timeout_minutes()
        
        # Mark expired sessions as inactive in user_sessions table
        # Sessions expire when last_activity is older than timeout_minutes
        # We don't modify last_activity here - we just identify expired sessions
        # The query logic in get_admin_sessions() will mark them as inactive based on last_activity
        # Only update sessions that haven't been manually terminated by admin
        expired_sessions_query = text("""
            UPDATE user_sessions 
            SET updated_at = UTC_TIMESTAMP()
            WHERE last_activity <= DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE)
            AND COALESCE(terminated_by_admin, 0) = 0
            AND updated_at < DATE_SUB(UTC_TIMESTAMP(), INTERVAL 1 MINUTE)
        """)
        result = db.session.execute(expired_sessions_query, {'timeout_minutes': timeout_minutes})
        
        # Also update customer_sessions table for consistency
        expired_customer_sessions_query = text("""
            UPDATE customer_sessions 
            SET updated_at = UTC_TIMESTAMP()
            WHERE last_activity <= DATE_SUB(UTC_TIMESTAMP(), INTERVAL :timeout_minutes MINUTE)
            AND updated_at < DATE_SUB(UTC_TIMESTAMP(), INTERVAL 1 MINUTE)
        """)
        db.session.execute(expired_customer_sessions_query, {'timeout_minutes': timeout_minutes})
        
        db.session.commit()
        
        if result.rowcount > 0:
            print(f"[CLEANUP] Marked {result.rowcount} expired session(s) as inactive")
    except Exception as e:
        # Don't fail requests if cleanup fails
        db.session.rollback()
        print(f"[CLEANUP] Error cleaning up expired sessions: {e}")
        pass

# ==================== REQUEST LOGGING ====================

@app.before_request
def log_request_info():
    """
    Minimal logging: only track start time for API calls.
    Also cleanup expired sessions on every request.
    We keep the actual terminal output in a single clean line
    in the after_request handler.
    """
    import time
    g.start_time = time.time()
    # Cleanup expired sessions on every request (non-blocking)
    try:
        cleanup_expired_sessions()
    except Exception:
        pass
        pass  # Don't fail requests if cleanup fails

@app.after_request
def log_response_info(response):
    """
    Log API calls with status codes and response time.
    Example:
      API CALL: GET /api/products -> 200 (12.34ms)
    """
    if request.path.startswith('/api/'):
        import time
        duration = (time.time() - g.start_time) * 1000  # ms
        print(f"API CALL: {request.method} {request.path} -> {response.status_code} ({duration:.2f}ms)")
    return response

@app.errorhandler(404)
def not_found(error):
    return jsonify({'error': 'Endpoint not found'}), 404

@app.errorhandler(500)
def internal_error(error):
    db.session.rollback()
    return jsonify({'error': 'Internal server error'}), 500

