# ==================== AUTOMATIC RATE UPDATES ====================

def schedule_automatic_rate_updates():
    """
    Schedule automatic exchange rate updates every 6 hours
    Uses threading.Timer for simple background scheduling
    """
    def fetch_rates_job():
        """Background job to fetch exchange rates"""
        try:
            with app.app_context():
                # print(f"\n{'='*60}")
                # print(f"🔄 AUTOMATIC RATE UPDATE TRIGGERED")
                # print(f"Time: {datetime.now(timezone.utc).isoformat()}")
                # print(f"{'='*60}")
                
                # Call the fetch function
                success, data_dict, message = fetch_live_rates_internal('INR')
                
                if success:
                    # print("✅ Automatic rate update completed successfully")
                    pass
                else:
                    # print(f"⚠️  Automatic rate update failed: {message}")
                    pass
                    
        except Exception as e:
            # print(f"❌ Error in automatic rate update: {str(e)}")
            # import traceback
            # traceback.print_exc()
            pass
        finally:
            # Schedule next update (6 hours = 21600 seconds)
            update_interval = int(os.environ.get('CURRENCY_UPDATE_INTERVAL', 21600))  # Default 6 hours
            timer = threading.Timer(update_interval, fetch_rates_job)
            timer.daemon = True  # Allow program to exit even if timer is running
            timer.start()
            # print(f"⏰ Next automatic update scheduled in {update_interval/3600:.1f} hours")
    
    # Start the first update after 1 minute (to let app initialize)
    initial_delay = 60  # 1 minute
    timer = threading.Timer(initial_delay, fetch_rates_job)
    timer.daemon = True
    timer.start()
    # print(f"⏰ Automatic rate updates scheduled (every {os.environ.get('CURRENCY_UPDATE_INTERVAL', 21600)/3600:.1f} hours)")

