    @app.route('/api/rewards/campaigns', methods=['GET', 'POST'])
    @jwt_required()
    def rewards_campaigns_alias():
        """Alias for /api/rewards-v2/campaigns and /api/reward-campaigns/campaigns"""
        if request.method == 'GET':
            # Use the existing get_reward_campaigns function
            try:
                # Return all campaigns - let frontend handle expiration display
                # Also auto-update expired campaigns in database
                campaigns_query = text("""
                    SELECT 
                        id, name, description, campaign_type, bonus_multiplier, bonus_points,
                        min_purchase_amount, applicable_tiers, valid_from, valid_until,
                        is_active, created_at, updated_at, priority, stackable, max_uses_per_user, auto_apply
                    FROM reward_campaigns
                    ORDER BY created_at DESC
                """)
                
                # Auto-update expired campaigns to inactive (using IST timezone)
                # Compare dates properly - valid_until should be compared as DATE, not DATETIME
                update_expired = text("""
                    UPDATE reward_campaigns 
                    SET is_active = FALSE, updated_at = NOW()
                    WHERE is_active = TRUE 
                      AND valid_until IS NOT NULL 
                      AND DATE(valid_until) < DATE(CONVERT_TZ(NOW(), @@session.time_zone, '+05:30'))
                """)
                try:
                    db.session.execute(update_expired)
                    db.session.commit()
                    print(f"[Campaigns] Auto-updated expired campaigns")
                except Exception as update_err:
                    db.session.rollback()
                    print(f"[Campaigns] Error updating expired campaigns: {update_err}")
                result = db.session.execute(campaigns_query).fetchall()
                campaigns = []
                for row in result:
                    applicable_tiers = row[7] or ''
                    if isinstance(applicable_tiers, str) and applicable_tiers:
                        try:
                            tiers_list = json.loads(applicable_tiers) if applicable_tiers.startswith('[') else applicable_tiers.split(',')
                        except:
                            tiers_list = applicable_tiers.split(',') if applicable_tiers else []
                    else:
                        tiers_list = []
                    
                    campaigns.append({
                        'id': row[0],
                        'name': row[1],
                        'description': row[2],
                        'campaign_type': row[3] if row[3] in ['multiplier', 'bonus_points', 'cashback', 'signup_bonus', 'birthday_bonus', 'double_points'] else 'multiplier',
                        'bonus_multiplier': float(row[4]) if row[4] else None,
                        'bonus_points': int(row[5]) if row[5] else None,
                        'min_purchase_amount': float(row[6]) if row[6] else 0,
                        'applicable_tiers': tiers_list if isinstance(tiers_list, list) else [],
                        # Format dates as YYYY-MM-DD only (no time) to avoid timezone issues
                        'valid_from': row[8].strftime('%Y-%m-%d') if row[8] else None,
                        'valid_until': row[9].strftime('%Y-%m-%d') if row[9] else None,
                        'is_active': bool(row[10]),
                        'created_at': row[11].isoformat() if row[11] else None,
                        'updated_at': row[12].isoformat() if row[12] else None,
                        'priority': int(row[13]) if len(row) > 13 and row[13] else 0,
                        'stackable': bool(row[14]) if len(row) > 14 and row[14] is not None else False,
                        'max_uses_per_user': int(row[15]) if len(row) > 15 and row[15] else None,
                        'auto_apply': bool(row[16]) if len(row) > 16 and row[16] is not None else False
                    })
                return jsonify({'success': True, 'campaigns': campaigns}), 200
            except Exception as e:
                print(f"[Campaigns] Error: {str(e)}")
                import traceback
                traceback.print_exc()
                return jsonify({'success': True, 'campaigns': []}), 200
        else:  # POST
            return create_reward_campaign()
    
