    @app.route('/api/rewards/tiers', methods=['GET', 'POST'])
    @jwt_required()
    def get_or_create_reward_tiers():
        """Get all reward tiers or create a new one"""
        try:
            if request.method == 'GET':
                # Check if reward_tiers table exists, if not return empty array
                try:
                    query = text("""
                        SELECT id, tier_name, min_lifetime_spend, points_multiplier,
                               points_earning_rate_multiplier, perks, badge_color,
                               free_shipping_threshold, priority_support, early_access,
                               display_order, is_active, created_at, updated_at
                        FROM reward_tiers
                        ORDER BY display_order ASC, min_lifetime_spend ASC
                    """)
                    result = db.session.execute(query).fetchall()
                    tiers = []
                    for row in result:
                        perks_data = row[5] if row[5] else '[]'
                        try:
                            perks = json.loads(perks_data) if isinstance(perks_data, str) else perks_data
                        except:
                            perks = []
                        
                        tiers.append({
                            'id': row[0],
                            'tier_name': row[1] or 'bronze',
                            'min_lifetime_spend': float(row[2]) if row[2] else 0.0,
                            'points_multiplier': float(row[3]) if row[3] else 1.0,
                            'points_earning_rate_multiplier': float(row[4]) if row[4] else 1.0,
                            'perks': perks if isinstance(perks, list) else [],
                            'badge_color': row[6] or '#gray',
                            'free_shipping_threshold': float(row[7]) if row[7] else None,
                            'priority_support': bool(row[8]) if row[8] is not None else False,
                            'early_access': bool(row[9]) if row[9] is not None else False,
                            'display_order': int(row[10]) if row[10] else 0,
                            'is_active': bool(row[11]) if row[11] is not None else True,
                            'created_at': row[12].isoformat() if row[12] else None,
                            'updated_at': row[13].isoformat() if row[13] else None
                        })
                    return jsonify({'tiers': tiers}), 200
                except Exception as e:
                    # Table doesn't exist, return empty array
                    print(f"[Tiers] Table may not exist: {str(e)}")
                    return jsonify({'tiers': []}), 200
            else:  # POST
                data = request.get_json()
                # Create reward_tiers table if it doesn't exist
                create_tiers_table = text("""
                    CREATE TABLE IF NOT EXISTS reward_tiers (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        tier_name VARCHAR(50) NOT NULL,
                        min_lifetime_spend DECIMAL(10,2) DEFAULT 0.00,
                        points_multiplier DECIMAL(5,2) DEFAULT 1.00,
                        points_earning_rate_multiplier DECIMAL(5,2) DEFAULT 1.00,
                        perks TEXT,
                        badge_color VARCHAR(20) DEFAULT '#gray',
                        free_shipping_threshold DECIMAL(10,2) NULL,
                        priority_support BOOLEAN DEFAULT FALSE,
                        early_access BOOLEAN DEFAULT FALSE,
                        display_order INT DEFAULT 0,
                        is_active BOOLEAN DEFAULT TRUE,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                        UNIQUE KEY unique_tier_name (tier_name)
                    )
                """)
                db.session.execute(create_tiers_table)
                db.session.commit()
                
                # Insert new tier
                insert_query = text("""
                    INSERT INTO reward_tiers (
                        tier_name, min_lifetime_spend, points_multiplier,
                        points_earning_rate_multiplier, perks, badge_color,
                        free_shipping_threshold, priority_support, early_access,
                        display_order, is_active
                    ) VALUES (
                        :tier_name, :min_spend, :multiplier, :earning_multiplier,
                        :perks, :badge_color, :free_shipping, :priority, :early,
                        :display_order, :is_active
                    )
                """)
                db.session.execute(insert_query, {
                    'tier_name': data.get('tier_name', 'bronze'),
                    'min_spend': float(data.get('min_lifetime_spend', 0)),
                    'multiplier': float(data.get('points_multiplier', 1.0)),
                    'earning_multiplier': float(data.get('points_earning_rate_multiplier', 1.0)),
                    'perks': json.dumps(data.get('perks', [])) if isinstance(data.get('perks'), list) else data.get('perks', '[]'),
                    'badge_color': data.get('badge_color', '#gray'),
                    'free_shipping': float(data.get('free_shipping_threshold')) if data.get('free_shipping_threshold') else None,
                    'priority': bool(data.get('priority_support', False)),
                    'early': bool(data.get('early_access', False)),
                    'display_order': int(data.get('display_order', 0)),
                    'is_active': bool(data.get('is_active', True))
                })
                db.session.commit()
                return jsonify({'success': True, 'message': 'Tier created successfully'}), 201
        except Exception as e:
            db.session.rollback()
            print(f"[Tiers] Error: {str(e)}")
            import traceback
            traceback.print_exc()
            return jsonify({'error': str(e)}), 500
    
