    # Reward Settings endpoints
    @app.route('/api/rewards/settings', methods=['GET', 'PUT'])
    @jwt_required()
    def get_or_update_reward_settings():
        """Get or update reward settings"""
        try:
            if request.method == 'GET':
                # Get settings from reward_settings table
                query = text("""
                    SELECT setting_key, setting_value, setting_type
                    FROM reward_settings
                    ORDER BY setting_key
                """)
                result = db.session.execute(query).fetchall()
                settings = {}
                for row in result:
                    key = row[0]
                    value = row[1]
                    setting_type = row[2] or 'string'
                    
                    # Convert based on type
                    if setting_type == 'boolean':
                        value = value.lower() in ('true', '1', 'yes') if value else False
                    elif setting_type == 'number':
                        try:
                            # Ensure proper float parsing - handle both 0.10 and 0.01 correctly
                            value = float(value) if value else 0
                            print(f"[Reward Settings GET] Parsed {key} = {value} (type: {setting_type}, raw: {row[1]})")
                        except Exception as parse_err:
                            print(f"[Reward Settings GET] Error parsing {key} value '{value}': {str(parse_err)}")
                            value = 0
                    
                    settings[key] = {'value': value, 'type': setting_type}
                
                print(f"[Reward Settings GET] Loaded {len(settings)} settings from reward_settings table")
                return jsonify({'settings': settings}), 200
            else:  # PUT
                data = request.get_json()
                if not data:
                    return jsonify({'error': 'No data provided'}), 400
                
                print(f"[Reward Settings] Updating settings: {list(data.keys())}")
                
                for key, value_data in data.items():
                    try:
                        if isinstance(value_data, dict):
                            value = value_data.get('value', value_data)
                            setting_type = value_data.get('type', 'string')
                        else:
                            value = value_data
                            setting_type = 'string'
                        
                        # Determine type if not provided
                        if setting_type == 'string':
                            if isinstance(value, bool):
                                setting_type = 'boolean'
                            elif isinstance(value, (int, float)):
                                setting_type = 'number'
                        
                        # Check if setting exists in reward_settings table
                        check_query = text("""
                            SELECT id FROM reward_settings 
                            WHERE setting_key = :key
                            LIMIT 1
                        """)
                        existing = db.session.execute(check_query, {'key': key}).fetchone()
                        
                        if existing:
                            # Update existing setting
                            update_query = text("""
                                UPDATE reward_settings 
                                SET setting_value = :value,
                                    setting_type = :type,
                                    updated_at = NOW()
                                WHERE setting_key = :key
                            """)
                            db.session.execute(update_query, {
                                'key': key,
                                'value': str(value),
                                'type': setting_type
                            })
                            print(f"[Reward Settings] Updated {key} = {value} (type: {setting_type})")
                        else:
                            # Insert new setting
                            insert_query = text("""
                                INSERT INTO reward_settings (setting_key, setting_value, setting_type, updated_at)
                                VALUES (:key, :value, :type, NOW())
                            """)
                            db.session.execute(insert_query, {
                                'key': key,
                                'value': str(value),
                                'type': setting_type
                            })
                            print(f"[Reward Settings] Inserted {key} = {value} (type: {setting_type})")
                    except Exception as setting_error:
                        print(f"[Reward Settings] Error saving {key}: {str(setting_error)}")
                        import traceback
                        traceback.print_exc()
                        raise
                
                db.session.commit()
                
                # Verify settings were saved by reading them back from reward_settings table
                keys_list = list(data.keys())
                verify_result = []
                if keys_list:
                    try:
                        placeholders = ','.join([f':key{i}' for i in range(len(keys_list))])
                        verify_query = text(f"""
                            SELECT setting_key, setting_value, setting_type, updated_at
                            FROM reward_settings 
                            WHERE setting_key IN ({placeholders})
                            ORDER BY setting_key
                        """)
                        params = {f'key{i}': key for i, key in enumerate(keys_list)}
                        verify_result = db.session.execute(verify_query, params).fetchall()
                    except Exception as verify_err:
                        print(f"[Reward Settings] Verification query error: {str(verify_err)}")
                
                print(f"[Reward Settings] Successfully updated {len(data)} settings")
                if verify_result:
                    print(f"[Reward Settings] Verification - Read back {len(verify_result)} settings:")
                    for row in verify_result:
                        print(f"  ✅ {row[0]} = {row[1]} (type: {row[2]}, updated: {row[3]})")
                
                return jsonify({
                    'success': True, 
                    'message': 'Settings updated successfully',
                    'updated_count': len(data),
                    'verified': len(verify_result)
                }), 200
        except Exception as e:
            db.session.rollback()
            print(f"[Reward Settings] Error: {str(e)}")
            return jsonify({'error': str(e)}), 500
    
