    @app.route('/rewards/history/<int:user_id>', methods=['GET'])
    @jwt_required()
    def get_rewards_history(user_id):
        """Get reward transaction history for a user"""
        try:
            transactions = RewardTransaction.query.filter_by(user_id=user_id)\
                .order_by(desc(RewardTransaction.created_at))\
                .limit(100).all()
            
            history = [{
                'id': txn.id,
                'points_delta': txn.points if txn.transaction_type == 'earned' else -txn.points,
                'transaction_type': txn.transaction_type,
                'points': txn.points,
                'balance_after': txn.balance_after,
                'reason': txn.description or 'N/A',
                'order_id': txn.reference_id if txn.reference_type == 'order' else None,
                'created_at': txn.created_at.isoformat() if txn.created_at else None
            } for txn in transactions]
            
            return jsonify({'history': history}), 200
        except Exception as e:
            print(f"[Reward History] Error: {str(e)}")
            return jsonify({'history': []}), 200
    
